macro_rules! let_row { ($($tokens:tt)*) => { let $($tokens)*; }; }
macro_rules! state_test {
    (sync $name:ident $($body:tt)*) => {
        #[test]
        fn $name() { $($body)* }
    };
    (result $name:ident $($body:tt)*) => {
        #[test]
        fn $name() -> Result<()> { $($body)* }
    };
}

fn blank_test_state() -> State {
    State::new_for_testing(
        World::default(),
        Kura::blank_kura_for_testing(),
        LiveQueryStore::start_test(),
    )
}
fn blank_test_state_from_kura(kura: &Arc<Kura>) -> State {
    State::new_for_testing(
        World::default(),
        Arc::clone(kura),
        LiveQueryStore::start_test(),
    )
}
fn blank_test_state_with_kura() -> (State, Arc<Kura>) {
    let kura = Kura::blank_kura_for_testing();
    let state = blank_test_state_from_kura(&kura);
    (state, kura)
}
