state_test! { sync state_snapshot_rejects_serialized_asset_definition_domain_index
    let (state, _, _) = snapshot_state_with_numeric_asset();
    let block = state.block(BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0));
    let_row! { block_snapshot = norito::json::to_value(&block.world).expect("serialize staged world snapshot") };
    let_row! { norito::json::Value::Object(block_world_object) = block_snapshot else { panic!("staged world snapshot must be an object"); } };
    assert!(
        !block_world_object.contains_key("asset_definition_domains"),
        "staged snapshots must omit the same derived ownership index as committed snapshots"
    );
    drop(block);
    let mut snapshot = norito::json::to_value(&state).expect("serialize state");
    let_row! { norito::json::Value::Object(state_object) = &mut snapshot else { panic!("state snapshot must be an object"); } };
    let_row! { norito::json::Value::Object(world_object) = state_object .get_mut("world") .expect("state snapshot contains world") else { panic!("world snapshot must be an object"); } };
    assert!(
        !world_object.contains_key("asset_definition_domains"),
        "derived ownership index must not be serialized"
    );
    world_object.insert("asset_definition_domains".to_owned(), norito::json!({}));
    let_row! { error = match deserialize_state_snapshot_value(snapshot) { Ok(_) => panic!("persisted derived ownership index must be rejected"), Err(error) => error, } };
    assert!(
        error.to_string().contains("unknown field"),
        "unexpected snapshot error: {error}"
    );
}
