fn snapshot_state_with_orchard_pool() -> (State, AccountId, AssetDefinitionId) {
    use iroha_data_model::privacy::{
        PRIVACY_ORCHARD_POOL_INITIAL_EPOCH_V1, PrivacyActiveLifecycleV1, PrivacyNamespaceScopeV1,
        PrivacyNamespaceV1, PrivacyPoolIdV1, PrivacyPoolNamespaceV1, PrivacyProtocolIdV1,
        PrivacyProtocolLifecycleV1, PrivacyRootRoleV1,
    };
    let domain_id = DomainId::try_new("orchard_snapshot", "universal").expect("domain id");
    let domain = Domain::new(domain_id.clone()).build(&ALICE_ID);
    let owner = Account::new(ALICE_ID.clone()).build(&ALICE_ID);
    let reserve_account = BOB_ID.clone();
    let reserve = Account::new(reserve_account.clone()).build(&ALICE_ID);
    let_row! { asset_definition_id = AssetDefinitionId::derive_from_components(domain_id, "coin".parse().expect("asset name")) };
    let_row! { definition = AssetDefinition::new( asset_definition_id.clone(), "coin".to_owned(), NumericSpec::integer(), iroha_data_model::asset::AssetBalancePolicy::Global, None, ) .build(&ALICE_ID) };
    let mut world = World::with_assets([domain], [owner, reserve], [definition], [], []);
    let_row! { namespace = PrivacyNamespaceV1::new( PrivacyProtocolIdV1::OrchardHalo2ActionsV1, PrivacyNamespaceScopeV1::Pool(PrivacyPoolNamespaceV1 { pool_id: PrivacyPoolIdV1::new([0xA1; 32]), }), ) };
    let_row! { bootstrap = iroha_data_model::privacy::PrivacyOrchardPoolBootstrapV1::new( PrivacyPoolIdV1::new([0xA1; 32]), asset_definition_id.clone(), iroha_data_model::asset::AssetBalanceScope::Global, reserve_account.clone(), ) .expect("canonical Orchard pool bootstrap") };
    let bootstrap_digest = bootstrap.digest().expect("Orchard bootstrap digest");
    let_row! { pool_state = crate::privacy_state::PrivacyOrchardPoolStateV1::bootstrap(bootstrap) .expect("canonical Orchard pool state") };
    let root = pool_state.root();
    let_row! { provenance = crate::privacy_state::PrivacyRootProvenanceV1::orchard_pool_bootstrap(bootstrap_digest, 1) .expect("canonical Orchard bootstrap provenance") };
    let_row! { root_key = crate::privacy_state::PrivacyRootKeyV1::new( namespace, PrivacyRootRoleV1::NoteCommitmentAnchor, PRIVACY_ORCHARD_POOL_INITIAL_EPOCH_V1, root, ) .expect("canonical Orchard bootstrap root key") };
    let_row! { head_key = crate::privacy_state::PrivacyRootHeadKeyV1::new( namespace, PrivacyRootRoleV1::NoteCommitmentAnchor, ) .expect("canonical Orchard root-head key") };
    let_row! { state_key = crate::privacy_state::PrivacyCommitmentKeyV1::orchard_pool_state(namespace) .expect("canonical Orchard pool-state key") };
    let_row! { profile = crate::privacy_profiles::compiled_privacy_profile_v1( PrivacyProtocolIdV1::OrchardHalo2ActionsV1, ) .expect("compiled Orchard profile") };
    world.privacy_activations.insert(
        crate::privacy_state::PrivacyActivationKeyV1::new(
            PrivacyProtocolIdV1::OrchardHalo2ActionsV1,
        ),
        profile.activation_record(PrivacyProtocolLifecycleV1::Active(
            PrivacyActiveLifecycleV1 {
                proposed_at_height: 1,
                activated_at_height: 2,
                state_since_height: 2,
            },
        )),
    );
    world.privacy_commitments.insert(
        state_key,
        crate::privacy_state::PrivacyStateItemRecordV1::orchard_pool_state(pool_state)
            .expect("canonical Orchard pool-state record"),
    );
    world.privacy_roots.insert(root_key, provenance);
    world.privacy_root_heads.insert(
        head_key,
        crate::privacy_state::PrivacyRootHeadRecordV1::new(
            PRIVACY_ORCHARD_POOL_INITIAL_EPOCH_V1,
            root,
            provenance,
            None,
        )
        .expect("canonical Orchard root head"),
    );
    (
        State::new(
            world,
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ),
        reserve_account,
        asset_definition_id,
    )
}
state_test! { sync state_snapshot_rejects_dangling_orchard_public_dependencies
    let (valid_state, _, _) = snapshot_state_with_orchard_pool();
    let_row! { valid_value = norito::json::to_value(&valid_state).expect("serialize valid Orchard snapshot") };
    deserialize_state_snapshot_value(valid_value)
        .expect("complete Orchard public dependencies restore");
    let (missing_reserve, reserve_account, _) = snapshot_state_with_orchard_pool();
    let mut accounts = missing_reserve.world.accounts.block();
    assert!(accounts.remove(reserve_account.clone()).is_some());
    accounts.commit();
    let_row! { value = norito::json::to_value(&missing_reserve).expect("serialize missing-reserve snapshot") };
    let_row! { error = deserialize_state_snapshot_value(value) .err() .expect("missing Orchard reserve account must fail closed") };
    let error = error.to_string();
    assert!(error.contains("world.privacy_state"), "{error}");
    assert!(
        error.contains("references missing reserve account"),
        "{error}"
    );
    assert!(error.contains(&reserve_account.to_string()), "{error}");
    let (missing_definition, _, asset_definition_id) = snapshot_state_with_orchard_pool();
    let mut asset_definitions = missing_definition.world.asset_definitions.block();
    assert!(
        asset_definitions
            .remove(asset_definition_id.clone())
            .is_some()
    );
    asset_definitions.commit();
    let_row! { value = norito::json::to_value(&missing_definition).expect("serialize missing-definition snapshot") };
    let_row! { error = deserialize_state_snapshot_value(value) .err() .expect("missing Orchard asset definition must fail closed") };
    let error = error.to_string();
    assert!(error.contains("world.privacy_state"), "{error}");
    assert!(
        error.contains("references missing asset definition"),
        "{error}"
    );
    assert!(error.contains(&asset_definition_id.to_string()), "{error}");
}
