state_test! { sync account_alias_bindings_roundtrip_through_state_json
    let mut world = World::default();
    let domain_id: DomainId = DomainId::try_new("alias", "world").expect("domain id");
    let_row! { primary_label = alias_in_domain( &domain_id, "primary".parse::<Name>().expect("primary label name"), ) };
    let_row! { bound_label = alias_in_domain( &domain_id, "issuance".parse::<Name>().expect("bound label name"), ) };
    let account_id = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let_row! { details = AccountDetails::new( Metadata::default(), Some(primary_label.clone()), None, Vec::new(), ) };
    world
        .accounts
        .insert(account_id.clone(), AccountValue::new(details));
    world
        .account_aliases
        .insert(primary_label.clone(), account_id.clone());
    world
        .account_aliases
        .insert(bound_label.clone(), account_id.clone());
    world.account_rekey_records.insert(
        primary_label.clone(),
        iroha_data_model::account::rekey::AccountRekeyRecord::new(
            primary_label.clone(),
            account_id.clone(),
        ),
    );
    world.account_rekey_records.insert(
        bound_label.clone(),
        iroha_data_model::account::rekey::AccountRekeyRecord::new(
            bound_label.clone(),
            account_id.clone(),
        ),
    );
    world
        .rebuild_account_alias_index()
        .expect("rebuild should preserve additional alias bindings");
    world
        .rebuild_account_rekey_records()
        .expect("rebuild should preserve rekey records");
    let_row! { state = State::new( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let json_value = norito::json::to_value(&state).expect("serialize state");
    let_row! { seed = deserialize::KuraSeed { kura: Kura::blank_kura_for_testing(), query_handle: LiveQueryStore::start_test(), #[cfg(feature = "telemetry")] telemetry: crate::telemetry::StateTelemetry::default(), } };
    let_row! { restored = seed .into_state_from_json(json_value) .expect("deserialize state") };
    let view = restored.world_view();
    assert_eq!(
        view.account_aliases().get(&primary_label),
        Some(&account_id)
    );
    assert_eq!(view.account_aliases().get(&bound_label), Some(&account_id));
    assert_eq!(
        view.account_rekey_records()
            .get(&bound_label)
            .expect("bound alias rekey record")
            .active_account_id,
        account_id
    );
    assert_eq!(
        view.bound_account_aliases(&account_id)
            .into_iter()
            .collect::<BTreeSet<_>>(),
        BTreeSet::from([primary_label, bound_label])
    );
}
