state_test! { sync explorer_count_indexes_exclude_many_unrelated_rows
    let target_domain = DomainId::try_new("gallery", "universal").expect("target domain");
    let unrelated_domain = DomainId::try_new("warehouse", "universal").expect("unrelated domain");
    let_row! { target_definition = AssetDefinitionId::derive_from_components(target_domain.clone(), "target".parse().unwrap()) };
    let target_asset = AssetId::new(target_definition.clone(), ALICE_ID.clone());
    let target_nft = NftId::new(target_domain.clone(), "target".parse().unwrap());
    let mut world = World::default();
    for domain_id in [&target_domain, &unrelated_domain] {
        world.domains.insert(
            domain_id.clone(),
            Domain::new(domain_id.clone()).build(&ALICE_ID),
        );
    }
    world.asset_definitions.insert(
        target_definition.clone(),
        AssetDefinition::numeric(
            target_definition.clone(),
            "target",
            iroha_data_model::asset::AssetBalancePolicy::Global,
            Some(target_domain.clone()),
        )
        .build(&ALICE_ID),
    );
    world
        .asset_definition_domains
        .insert(target_definition, target_domain.clone());
    let (asset_id, asset_value) = Asset::new(target_asset.clone(), 1_u32).into_key_value();
    world.assets.insert(asset_id, asset_value);
    let_row! { (nft_id, nft_value) = Nft::new(target_nft.clone(), Metadata::default()) .build(&ALICE_ID) .into_key_value() };
    world.nfts.insert(nft_id, nft_value);
    for index in 0..200_u16 {
        let definition_name: Name = format!("asset_{index}").parse().expect("asset name");
        let_row! { definition = AssetDefinitionId::derive_from_components( unrelated_domain.clone(), definition_name.clone(), ) };
        world.asset_definitions.insert(
            definition.clone(),
            AssetDefinition::numeric(
                definition.clone(),
                definition_name.to_string(),
                iroha_data_model::asset::AssetBalancePolicy::Global,
                Some(unrelated_domain.clone()),
            )
            .build(&ALICE_ID),
        );
        world
            .asset_definition_domains
            .insert(definition.clone(), unrelated_domain.clone());
        let unrelated_asset = AssetId::new(definition, BOB_ID.clone());
        let (asset_id, asset_value) = Asset::new(unrelated_asset, 1_u32).into_key_value();
        world.assets.insert(asset_id, asset_value);
        let_row! { unrelated_nft = NftId::new( unrelated_domain.clone(), format!("nft_{index}").parse().expect("NFT name"), ) };
        let_row! { (nft_id, nft_value) = Nft::new(unrelated_nft, Metadata::default()) .build(&BOB_ID) .into_key_value() };
        world.nfts.insert(nft_id, nft_value);
    }
    world
        .rebuild_asset_definition_indexes()
        .expect("valid asset definition domain contexts");
    world.rebuild_nft_owner_index();
    let view = world.view();
    assert_eq!(
        view.assets_by_account().get(&ALICE_ID),
        Some(&BTreeSet::from([target_asset.clone()])),
        "account projection must not include unrelated accounts"
    );
    assert_eq!(
        view.assets_by_domain().get(&target_domain),
        Some(&BTreeSet::from([target_asset])),
        "asset-domain projection must not include unrelated domains"
    );
    assert_eq!(
        view.nfts_by_domain().get(&target_domain),
        Some(&BTreeSet::from([target_nft])),
        "NFT-domain projection must not include unrelated domains"
    );
    assert_eq!(
        view.assets_by_domain()
            .get(&unrelated_domain)
            .map(BTreeSet::len),
        Some(200)
    );
    assert_eq!(
        view.nfts_by_domain()
            .get(&unrelated_domain)
            .map(BTreeSet::len),
        Some(200)
    );
}
state_test! { sync explorer_count_indexes_rollback_apply_and_commit_with_primary_rows
    let domain = DomainId::try_new("gallery", "universal").expect("domain");
    let_row! { definition = AssetDefinitionId::derive_from_components(domain.clone(), "ticket".parse().unwrap()) };
    let asset_id = AssetId::new(definition.clone(), ALICE_ID.clone());
    let nft_id = NftId::new(domain.clone(), "badge".parse().unwrap());
    let_row! { world = World::with_assets( [Domain::new(domain.clone()).build(&ALICE_ID)], [Account::new(ALICE_ID.clone()).build(&ALICE_ID)], [AssetDefinition::numeric( definition, "ticket", iroha_data_model::asset::AssetBalancePolicy::Global, Some(domain.clone()), ) .build(&ALICE_ID)], [], [], ) };
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let state = State::new_for_testing(world, kura, query_handle);
    let world = &state.world;
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
    let mut block = state.block(header);
    {
        let mut transaction = block.transaction();
        let (_, value) = Asset::new(asset_id.clone(), 1_u32).into_key_value();
        transaction.world.track_asset_holder(&asset_id);
        transaction.world.assets.insert(asset_id.clone(), value);
        let_row! { (_, value) = Nft::new(nft_id.clone(), Metadata::default()) .build(&ALICE_ID) .into_key_value() };
        transaction.world.insert_nft_entry(nft_id.clone(), value);
        // Drop without applying: the primary rows and every derived bucket must roll back.
    }
    assert!(block.world.assets.get(&asset_id).is_none());
    assert!(block.world.assets_by_account.get(&ALICE_ID).is_none());
    assert!(block.world.assets_by_domain.get(&domain).is_none());
    assert!(block.world.nfts.get(&nft_id).is_none());
    assert!(block.world.nfts_by_domain.get(&domain).is_none());
    {
        let mut transaction = block.transaction();
        let (_, value) = Asset::new(asset_id.clone(), 1_u32).into_key_value();
        transaction.world.track_asset_holder(&asset_id);
        transaction.world.assets.insert(asset_id.clone(), value);
        let_row! { (_, value) = Nft::new(nft_id.clone(), Metadata::default()) .build(&ALICE_ID) .into_key_value() };
        transaction.world.insert_nft_entry(nft_id.clone(), value);
        transaction.apply();
    }
    assert!(block.world.assets_by_account.get(&ALICE_ID).is_some());
    assert!(block.world.assets_by_domain.get(&domain).is_some());
    assert!(block.world.nfts_by_domain.get(&domain).is_some());
    block.commit().expect("commit explorer index fixture");
    let view = world.view();
    assert_eq!(
        view.assets_by_account().get(&ALICE_ID),
        Some(&BTreeSet::from([asset_id]))
    );
    assert_eq!(
        view.nfts_by_domain().get(&domain),
        Some(&BTreeSet::from([nft_id]))
    );
}
state_test! { sync rwas_status_and_frozen_iters_use_secondary_indexes
    let owner = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let domain = DomainId::try_new("vault", "universal").expect("domain");
    let vaulted = Some("vaulted".parse::<Name>().expect("vaulted status"));
    let pending = Some("pending".parse::<Name>().expect("pending status"));
    let target_id = RwaId::generated(domain.clone(), Hash::new("target"));
    let other_vaulted_id = RwaId::generated(domain.clone(), Hash::new("other-vaulted"));
    let pending_id = RwaId::generated(domain, Hash::new("pending"));
    let_row! { lot = |id: RwaId, status: Option<Name>, is_frozen: bool| { let mut rwa = Rwa::new( id, 1_u32, NumericSpec::integer(), "certificate".to_owned(), status, Metadata::default(), Vec::new(), RwaControlPolicy::default(), owner.clone(), ); rwa.is_frozen = is_frozen; rwa.into_key_value() } };
    let mut world = World::default();
    let (id, value) = lot(target_id.clone(), vaulted.clone(), true);
    world.rwas.insert(id, value);
    let (id, value) = lot(other_vaulted_id.clone(), vaulted.clone(), false);
    world.rwas.insert(id, value);
    let (id, value) = lot(pending_id, pending, false);
    world.rwas.insert(id, value);
    world.rebuild_rwa_indexes();
    let_row! { mut vaulted_ids = world .view() .rwas_by_status_iter(&vaulted) .map(|entry| entry.id().clone()) .collect::<Vec<_>>() };
    vaulted_ids.sort();
    let mut expected_vaulted = vec![target_id.clone(), other_vaulted_id];
    expected_vaulted.sort();
    assert_eq!(
        vaulted_ids, expected_vaulted,
        "status index should only return RWA lots with the requested status",
    );
    let_row! { frozen_ids = world .view() .rwas_by_frozen_iter(true) .map(|entry| entry.id().clone()) .collect::<Vec<_>>() };
    assert_eq!(
        frozen_ids,
        vec![target_id],
        "frozen-state index should only return frozen RWA lots in key order",
    );
}
