state_test! { sync find_proof_records_by_status_uses_status_index_updates
    let backend = "halo2/ipa";
    let_row! { verified_id = ProofId { backend: backend.into(), proof_hash: [0x11; 32], } };
    let_row! { rejected_id = ProofId { backend: backend.into(), proof_hash: [0x22; 32], } };
    let_row! { updated_id = ProofId { backend: backend.into(), proof_hash: [0x33; 32], } };
    let_row! { record = |id: &ProofId, status: ProofStatus| ProofRecord { id: id.clone(), vk_ref: None, vk_commitment: None, status, verified_at_height: Some(1), bridge: None, } };
    let state = blank_state();
    let block = new_dummy_block_with_payload(|_| {});
    let mut state_block = state.block(block.as_ref().header());
    let mut stx = state_block.transaction();
    stx.world
        .insert_proof_record(record(&verified_id, ProofStatus::Verified));
    stx.world
        .insert_proof_record(record(&rejected_id, ProofStatus::Rejected));
    stx.world
        .insert_proof_record(record(&updated_id, ProofStatus::Submitted));
    stx.world
        .insert_proof_record(record(&updated_id, ProofStatus::Verified));
    let_row! { verified_ids = FindProofRecordsByStatus { status: ProofStatus::Verified, } .execute(CompoundPredicate::PASS, &stx) .expect("query verified proof records") .map(|record| record.id) .collect::<Vec<_>>() };
    assert_eq!(verified_ids, vec![verified_id.clone(), updated_id.clone()]);
    let_row! { submitted_ids = FindProofRecordsByStatus { status: ProofStatus::Submitted, } .execute(CompoundPredicate::PASS, &stx) .expect("query submitted proof records") .map(|record| record.id) .collect::<Vec<_>>() };
    assert!(
        submitted_ids.is_empty(),
        "replacement should remove stale status-index entries",
    );
    let_row! { generic_by_id = FindProofRecords .execute( CompoundPredicate::<ProofRecord>::build(|predicate| { predicate.equals("id", updated_id.clone()) }), &stx, ) .expect("query proof records by generic id predicate") .map(|record| record.id) .collect::<Vec<_>>() };
    assert_eq!(generic_by_id, vec![updated_id.clone()]);
    let_row! { generic_by_backend = FindProofRecords .execute( CompoundPredicate::<ProofRecord>::build(|predicate| { predicate.equals("backend", backend) }), &stx, ) .expect("query proof records by generic backend predicate") .map(|record| record.id) .collect::<Vec<_>>() };
    assert_eq!(
        generic_by_backend,
        vec![verified_id.clone(), rejected_id.clone(), updated_id.clone()]
    );
    let_row! { generic_by_backend_and_status = FindProofRecords .execute( CompoundPredicate::<ProofRecord>::build(|predicate| { predicate .equals("backend", backend) .equals("status", ProofStatus::Rejected) }), &stx, ) .expect("query proof records by generic backend and status predicate") .map(|record| record.id) .collect::<Vec<_>>() };
    assert_eq!(generic_by_backend_and_status, vec![rejected_id]);
}
