state_test! { sync account_scope_directory_tracks_manifest_driven_uaid_binding_changes
    let state = blank_state();
    let block = new_dummy_block_with_payload(|_| {});
    let mut state_block = state.block(block.as_ref().header());
    let mut stx = state_block.transaction();
    let retail_dataspace = DataSpaceId::new(17);
    let treasury_dataspace = DataSpaceId::new(18);
    let_row! { dataspace_catalog = iroha_data_model::nexus::DataSpaceCatalog::new(vec![ iroha_data_model::nexus::DataSpaceMetadata::default(), iroha_data_model::nexus::DataSpaceMetadata { id: retail_dataspace, alias: "retail".to_string(), description: None, fault_tolerance: 1, }, iroha_data_model::nexus::DataSpaceMetadata { id: treasury_dataspace, alias: "treasury".to_string(), description: None, fault_tolerance: 1, }, ]) .expect("dataspace catalog") };
    stx.nexus.dataspace_catalog = dataspace_catalog.clone();
    stx.world.dataspace_catalog = dataspace_catalog;
    let authority = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let account_id = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let uaid = UniversalAccountId::from_hash(Hash::new(b"uaid::account-scope-refresh"));
    Register::account(Account::new(authority.clone()))
        .execute(&authority, &mut stx)
        .expect("register authority");
    Register::account(Account::new(account_id.clone()).with_uaid(Some(uaid)))
        .execute(&authority, &mut stx)
        .expect("register account");
    let_row! { manifest_record = |dataspace| { let manifest = AssetPermissionManifest { version: ManifestVersion::default(), uaid, dataspace, issued_ms: 0, activation_epoch: 1, expiry_epoch: None, entries: Vec::new(), }; let mut record = SpaceDirectoryManifestRecord::new(manifest); record.lifecycle.mark_activated(1); record } };
    let mut retail_set = SpaceDirectoryManifestSet::default();
    retail_set.upsert(manifest_record(retail_dataspace));
    stx.world.space_directory_manifests.insert(uaid, retail_set);
    stx.world.rebuild_space_directory_bindings(uaid);
    let_row! { retail_scopes = stx .world .account_scope_entry(&account_id) .expect("retail account scope") .expect("account scope entry after retail manifest") .iter() .map(|(dataspace_id, domains)| (*dataspace_id, domains.clone())) .collect::<BTreeMap<_, _>>() };
    assert_eq!(
        retail_scopes,
        BTreeMap::from([
            (DataSpaceId::UNIVERSAL, BTreeSet::new()),
            (retail_dataspace, BTreeSet::new()),
        ]),
        "UAID bindings should surface the manifest dataspace in the account scope directory",
    );
    let mut treasury_set = SpaceDirectoryManifestSet::default();
    treasury_set.upsert(manifest_record(treasury_dataspace));
    stx.world
        .space_directory_manifests
        .insert(uaid, treasury_set);
    stx.world.rebuild_space_directory_bindings(uaid);
    let_row! { treasury_scopes = stx .world .account_scope_entry(&account_id) .expect("treasury account scope") .expect("account scope entry after manifest rotation") .iter() .map(|(dataspace_id, domains)| (*dataspace_id, domains.clone())) .collect::<BTreeMap<_, _>>() };
    assert_eq!(
        treasury_scopes,
        BTreeMap::from([
            (DataSpaceId::UNIVERSAL, BTreeSet::new()),
            (treasury_dataspace, BTreeSet::new()),
        ]),
        "manifest-driven UAID binding changes should refresh the account scope directory",
    );
}
fn make_tlv(ty: PointerType, payload: &[u8]) -> Vec<u8> {
    let mut tlv = Vec::with_capacity(7 + payload.len() + 32);
    tlv.extend_from_slice(&(ty as u16).to_be_bytes());
    tlv.push(1);
    let length = u32::try_from(payload.len()).expect("payload length exceeds u32");
    tlv.extend_from_slice(&length.to_be_bytes());
    tlv.extend_from_slice(payload);
    let hash: [u8; 32] = Hash::new(payload).into();
    tlv.extend_from_slice(&hash);
    tlv
}
fn dummy_accepted_transaction() -> AcceptedTransaction<'static> {
    let keypair = crate::state::checked_keypair_with_algorithm(Algorithm::Ed25519);
    let authority = AccountId::new(keypair.public_key().clone());
    let_row! { mut builder = TransactionBuilder::new( *super::DEFAULT_TEST_NETWORK_ID, authority, iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) };
    builder.set_creation_time(Duration::from_millis(0));
    let_row! { tx = builder .with_instructions([Log::new(Level::INFO, "dummy".to_owned())]) .sign(keypair.private_key()) };
    AcceptedTransaction::new_unchecked(Cow::Owned(tx))
}
