state_test! { sync missing_malformed_or_invalid_autoscale_committee_pin_fails_closed
    let valid = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 1);
    assert_eq!(
        autoscale_lane_pinned_committee_with_pops(&valid)
            .expect("valid synthetic committee")
            .len(),
        4
    );
    let mut missing = valid.clone();
    missing.metadata.remove(AUTOSCALE_META_COMMITTEE);
    let mut malformed = valid.clone();
    malformed
        .metadata
        .insert(AUTOSCALE_META_COMMITTEE.to_owned(), "0A".to_owned());
    let mut oversized = valid.clone();
    oversized.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        "00".repeat(MAX_AUTOSCALE_COMMITTEE_BYTES.saturating_add(1)),
    );
    let mut invalid_pop = valid;
    let_row! { mut decoded = decode_autoscale_lane_committee(&invalid_pop) .expect("valid pin decoding") .expect("valid pin presence") };
    decoded.validator_pops[0] = vec![0; crate::lane_consensus::LANE_BLS_PROOF_BYTES];
    invalid_pop.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        hex::encode(norito::to_bytes(&decoded).expect("encode invalid-PoP fixture")),
    );
    for lane in [missing, malformed, oversized] {
        assert!(matches!(
            ensure_autoscale_managed_lane_shape(&lane),
            Err(LaneLifecycleError::InvalidAutoscaleManagedLane { .. })
        ));
        let nexus = autoscale_transition_test_nexus(vec![LaneConfig::default(), lane], 1, 3, 100);
        assert_eq!(
            nexus_active_lane_dataspace_at_height(LaneId::new(1), &nexus, 2),
            None,
            "missing or malformed incarnation authority must fail closed"
        );
    }
    let_row! { invalid_pop_committee = decode_autoscale_lane_committee(&invalid_pop) .expect("invalid-PoP pin remains shape-canonical") .expect("invalid-PoP pin is present") };
    assert!(
        validate_autoscale_lane_committee_pops(&invalid_pop_committee).is_err(),
        "lifecycle installation/replay must reject a shape-valid forged PoP once"
    );
}
state_test! { sync autoscale_committee_pin_is_part_of_catalog_config_and_incarnation_commitments
    let lane_a = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 1);
    let mut lane_b = lane_a.clone();
    let_row! { mut alternate_keypairs = (0_u8..4) .map(|index| { KeyPair::try_from_seed( vec![0xB1_u8.saturating_add(index); 32], Algorithm::BlsNormal, ) .expect("alternate pinned committee key") }) .collect::<Vec<_>>() };
    alternate_keypairs.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    let_row! { alternate_set = alternate_keypairs .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let_row! { alternate_pops = alternate_keypairs .iter() .map(|keypair| { iroha_crypto::bls_normal_pop_prove(keypair.private_key()) .expect("alternate pinned committee PoP") }) .collect::<Vec<_>>() };
    let_row! { alternate = autoscale_lane_committee_from_validator_set(alternate_set, alternate_pops) .expect("alternate pinned committee") };
    lane_b.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        encode_autoscale_lane_committee(&alternate).expect("alternate pin encoding"),
    );
    assert_ne!(
        merge_lane_config_hash(&lane_a),
        merge_lane_config_hash(&lane_b)
    );
    let_row! { catalog_a = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane_a.clone()]) .expect("first pinned catalog") };
    let_row! { catalog_b = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane_b.clone()]) .expect("second pinned catalog") };
    assert_ne!(
        merge_lane_catalog_hash(&catalog_a),
        merge_lane_catalog_hash(&catalog_b)
    );
    assert_ne!(
        derive_static_lane_incarnations(&catalog_a)[&LaneId::new(1)],
        derive_static_lane_incarnations(&catalog_b)[&LaneId::new(1)],
        "re-pinning authority is necessarily a new lane incarnation"
    );
}
state_test! { sync canonical_lane_frontier_lookup_ignores_unrelated_history_and_contract_state
    let lane_id = LaneId::new(7);
    let dataspace_id = DataSpaceId::new(9);
    let incarnation = Hash::new(b"bounded-frontier-incarnation");
    let descriptor_hash = Hash::new(b"bounded-frontier-descriptor");
    let_row! { marker = AppliedMergeLaneFrontierMarker { version: 1, lane_id, dataspace_id, lane_incarnation: incarnation, lane_block_height: 41, lane_block_descriptor_hash: descriptor_hash, } };
    let_row! { (key, payload) = State::encode_merge_lane_frontier_marker(marker).expect("canonical latest-frontier cell") };
    let mut world = World::default();
    world.smart_contract_state.insert(key, payload);
    for index in 0..1_000_u64 {
        let_row! { unrelated: StatePath = format!("unrelated_contract_state_{index}") .parse() .expect("unrelated state key") };
        world.smart_contract_state.insert(
            unrelated,
            vec![u8::try_from(index % 251).expect("bounded byte")],
        );
    }
    let_row! { old_height_key: StatePath = format!( "{MERGE_EXECUTION_LANE_FRONTIER_MARKER_PREFIX}{}_{}_{}_{}", lane_id.as_u32(), dataspace_id.as_u64(), 40, hex::encode(incarnation.as_ref()) ) .parse() .expect("legacy per-height frontier key") };
    world
        .smart_contract_state
        .insert(old_height_key, b"malformed legacy marker".to_vec());
    let world = world.view();
    assert_eq!(
        State::canonical_merged_lane_frontier_from_world(
            &world,
            lane_id,
            dataspace_id,
            incarnation,
        )
        .expect("exact latest-frontier lookup ignores unrelated keys"),
        (41, Some(descriptor_hash))
    );
}
