state_test! { sync merge_routing_plan_boundary_requires_exact_framed_norito
    let_row! { plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new( LaneId::new(7), DataSpaceId::new(9), )) };
    let framed = norito::encode_canonical(&plan).expect("canonical framed routing plan");
    assert_eq!(
        decode_canonical_merge_routing_plan(&framed)
            .expect("canonical framed routing plan must decode"),
        plan
    );
    let_row! { alternate_flags = norito::core::default_encode_flags() ^ norito::core::header_flags::COMPACT_LEN };
    let_row! { alternate = { let _alternate = norito::core::DecodeFlagsGuard::enter(alternate_flags); norito::to_bytes(&plan).expect("alternate-layout routing plan") } };
    assert_ne!(
        alternate, framed,
        "fixture must exercise a non-canonical routing-plan layout"
    );
    assert!(
        matches!(
            decode_canonical_merge_routing_plan(&alternate),
            Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
                if message.contains("canonical exact framed Norito")
        ),
        "alternate-layout routing plan must reject"
    );
    {
        let _ambient = norito::core::DecodeFlagsGuard::enter(alternate_flags);
        assert_eq!(
            decode_canonical_merge_routing_plan(&framed)
                .expect("canonical routing plan must ignore ambient layout"),
            plan
        );
    }
    let_row! { assert_framed_rejected = |candidate: &[u8], context: &str| { assert!( matches!( decode_canonical_merge_routing_plan(candidate), Err(MergeLedgerCommitError::ExecutionBatchInvalid(message)) if message.contains("framed Norito") ), "{context}" ); } };
    let bare = plan.encode();
    assert_ne!(framed, bare, "framed and bare Norito must remain distinct");
    assert_framed_rejected(&bare, "bare routing plan must reject");
    let_row! { (_, truncated) = framed .split_last() .expect("canonical routing plan frame is nonempty") };
    assert_framed_rejected(truncated, "truncated routing plan frame must reject");
    let mut corrupt = framed.clone();
    *corrupt
        .last_mut()
        .expect("canonical routing plan frame is nonempty") ^= 0x80;
    assert_framed_rejected(&corrupt, "corrupt routing plan frame must reject");
    let mut trailing = framed.clone();
    trailing.push(0);
    assert_framed_rejected(&trailing, "trailing routing plan byte must reject");
    let mut compressed = framed.clone();
    *compressed
        .get_mut(MERGE_INNER_NORITO_COMPRESSION_OFFSET)
        .expect("canonical frame carries the documented compression byte") =
        norito::Compression::Zstd as u8;
    assert!(matches!(
        decode_canonical_merge_routing_plan(&compressed),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
            if message.contains("uncompressed exact framed Norito")
    ));
    let mut declared_bomb = framed;
    declared_bomb
        .get_mut(MERGE_INNER_NORITO_LENGTH_OFFSET..MERGE_INNER_NORITO_LENGTH_OFFSET + 8)
        .expect("canonical frame carries the documented payload length")
        .copy_from_slice(
            &(u64::try_from(MAX_MERGE_EXECUTION_ROUTING_PLAN_BYTES)
                .expect("routing-plan byte cap fits u64")
                + 1)
            .to_le_bytes(),
        );
    assert!(matches!(
        decode_canonical_merge_routing_plan(&declared_bomb),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
            if message.contains("hard byte limit")
    ));
    let oversized = vec![0; MAX_MERGE_EXECUTION_ROUTING_PLAN_BYTES + 1];
    assert!(matches!(
        decode_canonical_merge_routing_plan(&oversized),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
            if message.contains("hard byte limit")
    ));
}
state_test! { sync merge_reservation_key_boundary_requires_current_version
    let route = crate::queue::RoutingDecision::new(LaneId::new(7), DataSpaceId::new(9));
    let plan = crate::queue::RoutingPlan::single(route);
    let_row! { entrypoint_hash = HashOf::from_untyped_unchecked(Hash::new(b"merge-reservation-entrypoint")) };
    let_row! { key = crate::queue::LaneQueueReservationKeyV2 { version: crate::queue::LaneQueueReservationKeyV2::VERSION, signed_transaction_hash: HashOf::from_untyped_unchecked(Hash::from(entrypoint_hash)), entrypoint_hash, queue_plan_admission_binding_hash: Hash::new( b"merge-reservation-queue-plan-admission-binding", ), routing_plan_digest: plan.digest(), coordinator_leg: plan.coordinator_leg(), lane_id: route.lane_id, dataspace_id: route.dataspace_id, lane_incarnation: Hash::new(b"merge-reservation-incarnation"), proposal_height: 13, lane_block_height: 5, lane_block_view: 2, reservation_owner_hash: Hash::new(b"merge-reservation-owner"), proposal_identity_hash: Hash::new(b"merge-reservation-proposal"), } };
    let framed = norito::encode_canonical(&key).expect("encode current merge reservation key");
    assert_eq!(
        decode_canonical_merge_reservation_key(&framed)
            .expect("current merge reservation key must decode"),
        key
    );
    let_row! { alternate_flags = norito::core::default_encode_flags() ^ norito::core::header_flags::COMPACT_LEN };
    let_row! { alternate = { let _alternate = norito::core::DecodeFlagsGuard::enter(alternate_flags); norito::to_bytes(&key).expect("encode alternate-layout merge reservation key") } };
    assert_ne!(
        alternate, framed,
        "fixture must exercise a non-canonical reservation-key layout"
    );
    assert!(
        matches!(
            decode_canonical_merge_reservation_key(&alternate),
            Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
                if message.contains("canonical exact framed Norito")
        ),
        "alternate-layout merge reservation key must reject"
    );
    {
        let _ambient = norito::core::DecodeFlagsGuard::enter(alternate_flags);
        assert_eq!(
            decode_canonical_merge_reservation_key(&framed)
                .expect("canonical reservation key must ignore ambient layout"),
            key
        );
    }
    for malformed_version in [0, crate::queue::LaneQueueReservationKeyV2::VERSION + 1] {
        let mut malformed = key;
        malformed.version = malformed_version;
        let_row! { framed = norito::encode_canonical(&malformed) .expect("encode canonical malformed-version reservation key") };
        assert!(
            matches!(
                decode_canonical_merge_reservation_key(&framed),
                Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
                    if message.contains("unsupported lane queue reservation key version")
            ),
            "merge admission must reject reservation key version {malformed_version}"
        );
    }
    let mut mismatched_hashes = key;
    mismatched_hashes.signed_transaction_hash =
        HashOf::from_untyped_unchecked(Hash::new(b"mismatched-merge-signed-transaction"));
    let_row! { framed = norito::encode_canonical(&mismatched_hashes) .expect("encode canonical hash-mismatched reservation key") };
    assert!(
        matches!(
            decode_canonical_merge_reservation_key(&framed),
            Err(MergeLedgerCommitError::ExecutionBatchInvalid(message))
                if message.contains(
                    "signed transaction hash does not match its entrypoint compatibility hash"
                )
        ),
        "merge admission must reject mismatched reservation identities"
    );
}
