state_test! { sync retired_lane_cleanup_preserves_frontier_for_historical_drain_recovery
    let keypairs = autoscale_drain_keypairs_for_test(4);
    let_row! { validator_set = keypairs .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let lane_id = LaneId::new(1);
    let dataspace_id = DataSpaceId::UNIVERSAL;
    let incarnation = Hash::new(b"retired-frontier-incarnation");
    let descriptor_hash = Hash::new(b"retired-frontier-descriptor");
    let_row! { mut drain_state = autoscale_drain_state_for_test( lane_id, dataspace_id, incarnation, 1, validator_set.clone(), None, ) };
    drain_state.intent.initial_frontier =
        LaneDrainFrontierV1::ordinary(lane_id, dataspace_id, incarnation, 2, Some(descriptor_hash));
    let_row! { body = LaneDrainCertificateBodyV1 { version: 1, intent: drain_state.intent, final_frontier: LaneDrainFrontierV1::ordinary( lane_id, dataspace_id, incarnation, 2, Some(descriptor_hash), ), } };
    let_row! { votes = keypairs .iter() .map(|keypair| { crate::lane_consensus::LaneDrainVoteV1::new_signed( body.clone(), PeerId::new(keypair.public_key().clone()), keypair.private_key(), ) .expect("valid drain vote") }) .collect::<Vec<_>>() };
    let_row! { certificate = crate::lane_consensus::aggregate_lane_drain_votes(body, validator_set, &votes) .expect("self-contained drain certificate") };
    let state = blank_test_state();
    let_row! { (frontier_key, frontier_payload) = State::encode_merge_lane_frontier_marker(AppliedMergeLaneFrontierMarker { version: 1, lane_id, dataspace_id, lane_incarnation: incarnation, lane_block_height: 2, lane_block_descriptor_hash: descriptor_hash, }) .expect("canonical retired frontier") };
    {
        let mut world = state.world.block();
        world
            .smart_contract_state
            .insert(frontier_key.clone(), frontier_payload);
        world.commit();
    }
    let_row! { active_lanes = [MergeLaneBinding { lane_id, dataspace_id, lane_config_hash: Hash::new(b"historical-lane-config"), incarnation, activation_height: 1, }] };
    state
        .validate_merge_lane_drain_certificate_payload(
            std::slice::from_ref(&certificate),
            3,
            &active_lanes,
            false,
        )
        .expect("historical recovery accepts the exact frontier before retirement");
    let mut mismatched_body = certificate.body.clone();
    mismatched_body.final_frontier = LaneDrainFrontierV1::ordinary(
        lane_id,
        dataspace_id,
        incarnation,
        3,
        Some(Hash::new(b"mismatched-drain-final-frontier")),
    );
    let_row! { mismatched_votes = keypairs .iter() .map(|keypair| { crate::lane_consensus::LaneDrainVoteV1::new_signed( mismatched_body.clone(), PeerId::new(keypair.public_key().clone()), keypair.private_key(), ) .expect("structurally valid mismatched drain vote") }) .collect::<Vec<_>>() };
    let_row! { mismatched_certificate = crate::lane_consensus::aggregate_lane_drain_votes( mismatched_body, certificate.validator_set.clone(), &mismatched_votes, ) .expect("aggregate mismatched drain certificate") };
    let_row! { error = state .validate_merge_lane_drain_certificate_payload( std::slice::from_ref(&mismatched_certificate), 3, &active_lanes, false, ) .expect_err("global admission must reject a signed frontier drift") };
    assert!(matches!(
        error,
        MergeLedgerCommitError::ExecutionBatchInvalid(reason)
            if reason.contains("exact globally applied frontier")
    ));
    {
        let mut world = state.world.block();
        State::prune_lane_lifecycle_world_block_state_for_lanes(
            &mut world,
            &BTreeSet::from([lane_id]),
        );
        world.commit();
    }
    assert!(
        state
            .world
            .view()
            .smart_contract_state()
            .get(&frontier_key)
            .is_some(),
        "retirement cleanup must retain the replicated historical frontier"
    );
    state
        .validate_merge_lane_drain_certificate_payload(
            std::slice::from_ref(&certificate),
            3,
            &active_lanes,
            false,
        )
        .expect("restart-style historical validation survives lane cleanup");
}
