state_test! { sync autoscale_default_route_capacity_counts_only_router_owned_lanes
    let policy = LaneRoutingPolicy::default();
    let_row! { mut managed_default = LaneConfig { id: LaneId::new(4), alias: "elastic-lane-4".to_owned(), ..LaneConfig::default() } };
    managed_default
        .metadata
        .insert(AUTOSCALE_META_MANAGED.to_owned(), "true".to_owned());
    managed_default
        .metadata
        .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "42".to_owned());
    let_row! { mut managed_other_dataspace = LaneConfig { id: LaneId::new(5), dataspace_id: DataSpaceId::new(9), alias: "elastic-lane-5".to_owned(), ..LaneConfig::default() } };
    managed_other_dataspace
        .metadata
        .insert(AUTOSCALE_META_MANAGED.to_owned(), "true".to_owned());
    managed_other_dataspace
        .metadata
        .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "43".to_owned());
    let_row! { mut restricted_default_dataspace = LaneConfig { id: LaneId::new(8), alias: "elastic-lane-8".to_owned(), visibility: LaneVisibility::Restricted, ..LaneConfig::default() } };
    restricted_default_dataspace
        .metadata
        .insert(AUTOSCALE_META_MANAGED.to_owned(), "true".to_owned());
    restricted_default_dataspace
        .metadata
        .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "44".to_owned());
    let_row! { manual_default_dataspace = LaneConfig { id: LaneId::new(6), alias: "manual-universal".to_owned(), ..LaneConfig::default() } };
    let_row! { malformed_default_dataspace = { let mut lane = LaneConfig { id: LaneId::new(7), alias: "elastic-lane-7".to_owned(), ..LaneConfig::default() }; lane.metadata .insert(AUTOSCALE_META_MANAGED.to_owned(), "true".to_owned()); lane.metadata .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "later".to_owned()); lane } };
    let_row! { marker_only_default_dataspace = { let mut lane = LaneConfig { id: LaneId::new(9), alias: "created-height-only".to_owned(), ..LaneConfig::default() }; lane.metadata .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "42".to_owned()); lane } };
    let_row! { lanes = vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), dataspace_id: DataSpaceId::new(2), alias: "governance".to_owned(), ..LaneConfig::default() }, managed_default, managed_other_dataspace, manual_default_dataspace, malformed_default_dataspace, restricted_default_dataspace, marker_only_default_dataspace, ] };
    assert_eq!(
        autoscale_default_route_capacity_lanes(&policy, &lanes, 3, 8),
        2
    );
    let_row! { public_profile_lanes = vec![ LaneConfig { id: LaneId::new(0), alias: "core".to_owned(), ..LaneConfig::default() }, LaneConfig { id: LaneId::new(1), alias: "governance".to_owned(), ..LaneConfig::default() }, LaneConfig { id: LaneId::new(2), alias: "zk".to_owned(), ..LaneConfig::default() }, autoscale_elastic_lane_config(LaneId::new(3), DataSpaceId::UNIVERSAL, 42), ] };
    assert_eq!(
        autoscale_default_route_capacity_lanes(&policy, &public_profile_lanes[..3], 3, 4),
        1,
        "unmanaged default-dataspace lanes must not inflate default-route capacity"
    );
    assert_eq!(
        autoscale_default_route_capacity_lanes(&policy, &public_profile_lanes, 3, 4),
        2,
        "only the default route anchor and managed elastic lanes should count as default-route capacity"
    );
}
