state_test! { sync autoscale_cold_window_stages_irreversible_drain_without_geometry_change
    let (mut state, kura) = blank_test_state_with_kura();
    state
        .set_nexus(autoscale_transition_test_nexus(
            vec![
                LaneConfig {
                    id: LaneId::new(0),
                    alias: "core".to_owned(),
                    ..LaneConfig::default()
                },
                LaneConfig {
                    id: LaneId::new(1),
                    alias: "governance".to_owned(),
                    ..LaneConfig::default()
                },
                LaneConfig {
                    id: LaneId::new(2),
                    alias: "zk".to_owned(),
                    ..LaneConfig::default()
                },
            ],
            3,
            4,
            200,
        ))
        .expect("apply autoscale public-profile test nexus config");
    state
        .apply_lane_lifecycle_with_options(
            &iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![autoscale_elastic_lane_config(
                    LaneId::new(3),
                    DataSpaceId::UNIVERSAL,
                    1,
                )],
                retire: Vec::new(),
            },
            false,
            true,
        )
        .expect("seed internally managed public-profile elastic lane");
    seed_autoscale_committee_for_test(&state, 4);
    let first = autoscale_signed_block_with_committed_fragments(None, 100, 0);
    let second = autoscale_signed_block_with_committed_fragments(Some(&first), 200, 0);
    store_committed_autoscale_history_block_for_test(&state, &kura, &first);
    store_block_for_state_commit(&kura, &second);
    let mut state_block = state.block(second.header());
    insert_empty_transaction_block_for_state_commit(&mut state_block, &second);
    commit_autoscale_transition!(state_block, second, nexus);
    assert_lane_ids!(
        nexus,
        vec![
            LaneId::SINGLE,
            LaneId::new(1),
            LaneId::new(2),
            LaneId::new(3),
        ],
        "the first cold carrier must preserve lane geometry while closing the lane"
    );
    assert_eq!(nexus.autoscale.last_transition_height, 2);
    let_row! { pending = state_block .pending_autoscale_lifecycle .as_ref() .expect("cold autoscale decision must stage a drain intent for commit") };
    assert_eq!(
        pending.transition_height, 2,
        "staged drain intent must carry the block transition height"
    );
    let_row! { PendingAutoscaleTransition::DrainIntent { lane, intent, active_lanes, autoscale_capacity_lanes, in_latency_ratio_permille, in_utilization_p95_permille, } = &pending.transition else { panic!("cold autoscale decision must stage a drain intent"); } };
    assert_eq!(*lane, LaneId::new(3));
    assert_eq!(*active_lanes, 2);
    assert_eq!(*autoscale_capacity_lanes, 2);
    assert_eq!(*in_latency_ratio_permille, 500);
    assert_eq!(*in_utilization_p95_permille, 0);
    assert_eq!(intent.close_global_height, 2);
    assert_eq!(intent.lane_id, LaneId::new(3));
    assert_eq!(intent.validator_set.len(), 4);
    assert_eq!(
        intent.validator_set_hash,
        HashOf::new(&intent.validator_set)
    );
    assert_eq!(intent.validator_count, 4);
    assert_eq!(intent.min_quorum, 3);
    assert_eq!(
        pending.catalog_update.updated_catalog, nexus.lane_catalog,
        "staged drain catalog must match the block-local Nexus catalog"
    );
    assert_eq!(
        pending
            .catalog_update
            .updated_lane_config
            .entries()
            .iter()
            .map(|entry| entry.lane_id)
            .collect::<Vec<_>>(),
        nexus
            .lane_config
            .entries()
            .iter()
            .map(|entry| entry.lane_id)
            .collect::<Vec<_>>(),
        "staged drain lane config entries must match the block-local Nexus lane config"
    );
    assert_eq!(
        pending.catalog_update.updated_lane_config.shard_mapping(),
        nexus.lane_config.shard_mapping(),
        "staged drain shard mapping must match the block-local Nexus lane config"
    );
    assert!(pending.plan.additions.is_empty());
    assert!(pending.plan.retire.is_empty());
    assert!(pending.catalog_update.lanes_to_reset.is_empty());
    assert!(
        pending.catalog_update.replaced_lane_ids.is_empty(),
        "drain intent must not be staged as a same-id replacement"
    );
    assert_eq!(
        pending.catalog_update.previous_lane_incarnations,
        pending.catalog_update.updated_lane_incarnations,
        "drain intent must preserve exact lane incarnations"
    );
    let_row! { drain_lane = nexus .lane_catalog .lanes() .iter() .find(|lane| lane.id == LaneId::new(3)) .expect("draining lane remains in the catalog") };
    let_row! { drain_state = decode_autoscale_lane_drain_state(drain_lane) .expect("drain metadata is canonical") .expect("drain metadata is present") };
    assert_eq!(&drain_state.intent, intent);
    assert!(drain_state.commitment.is_none());
}
state_test! { sync pending_drain_body_and_candidate_use_embedded_close_committee_after_roster_change
    let (mut state, _kura) = blank_test_state_with_kura();
    let parent_header = BlockHeader::new(nonzero!(1_u64), None, None, None, 100, 0);
    install_default_autoscale_test_nexus(&mut state, "install autoscale test nexus");
    state
        .apply_lane_lifecycle_with_options(
            &iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![autoscale_elastic_lane_config(
                    LaneId::new(1),
                    DataSpaceId::UNIVERSAL,
                    1,
                )],
                retire: Vec::new(),
            },
            false,
            true,
        )
        .expect("install drain candidate lane");
    state.push_block_hash_for_testing(parent_header.hash());
    let lane_id = LaneId::new(1);
    let_row! { incarnation = state .lane_incarnation(lane_id) .expect("drain candidate incarnation") };
    let keypairs = autoscale_drain_keypairs_for_test(4);
    let_row! { embedded_committee = keypairs .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let_row! { drain_state = autoscale_drain_state_for_test( lane_id, DataSpaceId::UNIVERSAL, incarnation, 1, embedded_committee.clone(), None, ) };
    let mut drained_nexus = state.nexus_snapshot();
    let mut lanes = drained_nexus.lane_catalog.lanes().to_vec();
    lanes
        .iter_mut()
        .find(|lane| lane.id == lane_id)
        .expect("drain lane")
        .metadata
        .insert(
            AUTOSCALE_META_DRAIN_STATE.to_owned(),
            encode_autoscale_lane_drain_state(&drain_state)
                .expect("canonical embedded drain state"),
        );
    drained_nexus.lane_catalog = LaneCatalog::new(drained_nexus.lane_catalog.lane_count(), lanes)
        .expect("drained lane catalog");
    drained_nexus.lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&drained_nexus.lane_catalog);
    *state.nexus.write() = drained_nexus;
    let_row! { unrelated_keypairs = autoscale_drain_keypairs_for_test(6) .into_iter() .skip(2) .collect::<Vec<_>>() };
    let_row! { unrelated_roster = unrelated_keypairs .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    {
        let mut topology = state.commit_topology.block();
        topology.clear();
        topology.extend(unrelated_roster);
        topology.commit();
    }
    let_row! { (body, recovered_committee) = state .pending_autoscale_lane_drain_body() .expect("embedded close committee survives current-roster drift") };
    assert_eq!(recovered_committee, embedded_committee);
    assert_eq!(&body.intent.validator_set, &recovered_committee);
    assert_eq!(body.final_frontier.lane_block_height, 0);
    assert!(body.final_frontier.lane_block_descriptor_hash.is_none());
    let certificate = autoscale_drain_certificate_for_test(body, &keypairs);
    let_row! { candidate = state .merge_drain_candidate_for_next_carrier(&parent_header, 7, certificate.clone()) .expect("valid exact drain certificate produces a cert-only candidate") };
    assert!(candidate.lane_snapshots.is_empty());
    assert!(candidate.execution_batch.is_none());
    assert_eq!(candidate.lane_drain_certificates, vec![certificate.clone()]);
    assert_eq!(candidate.carrier_height, 2);
    assert_eq!(candidate.carrier_parent_hash, parent_header.hash());
    let mut unsupported_candidate = candidate.clone();
    unsupported_candidate.version = crate::merge::MergeLedgerCandidate::VERSION + 1;
    assert!(matches!(
        state.validate_merge_candidate_for_global_round(
            &unsupported_candidate,
            &parent_header,
            7
        ),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(ref message))
            if message.contains("unsupported merge ledger candidate version")
    ));
    let_row! { empty_candidate = crate::merge::MergeLedgerCandidate { lane_drain_certificates: Vec::new(), ..candidate.clone() } };
    assert!(matches!(
        state.validate_merge_candidate_for_global_round(&empty_candidate, &parent_header, 7),
        Err(MergeLedgerCommitError::EmptyEntry)
    ));
    let mut mixed_candidate = candidate.clone();
    mixed_candidate.lane_snapshots = merge_candidate_with_lanes(1, 1).lane_snapshots;
    assert!(matches!(
        state.validate_merge_candidate_for_global_round(&mixed_candidate, &parent_header, 7),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(_))
    ));
    let mut mixed_queue_plan_candidate = candidate.clone();
    mixed_queue_plan_candidate.queue_plan_admissions = vec![vec![0x00]];
    assert!(matches!(
        state.validate_merge_candidate_for_global_round(
            &mixed_queue_plan_candidate,
            &parent_header,
            7,
        ),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(ref message))
            if message.contains("QueuePlan admission controls")
    ));
    let_row! { mixed_queue_plan_qc = merge_qc_for_candidate( &state, &mixed_queue_plan_candidate, &unrelated_keypairs, &[0, 1, 2], ) };
    let_row! { mixed_queue_plan_entry = merge_entry_from_candidate(mixed_queue_plan_candidate, mixed_queue_plan_qc) };
    assert!(matches!(
        state.validate_certified_merge_entry_for_global_order(&mixed_queue_plan_entry),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(ref message))
            if message.contains("QueuePlan admission controls")
    ));
    let qc = merge_qc_for_candidate(&state, &candidate, &unrelated_keypairs, &[0, 1, 2]);
    let entry = merge_entry_from_candidate(candidate.clone(), qc);
    state
        .validate_certified_merge_entry_for_global_order(&entry)
        .expect("certificate-only drain entry is globally admissible");
    let mut unsupported_entry = entry.clone();
    unsupported_entry.version = MergeLedgerEntry::VERSION + 1;
    assert!(matches!(
        state.validate_certified_merge_entry_for_global_order(&unsupported_entry),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(ref message))
            if message.contains("unsupported merge ledger entry version")
    ));
    let_row! { carrier_header = BlockHeader::new( nonzero!(2_u64), Some(parent_header.hash()), None, None, 101, 7, ) };
    let_row! { carrier = state .block_with_certified_merge_entry(carrier_header, &entry) .expect("exact global carrier stages a certificate-only drain") };
    let_row! { staged_lane = carrier .nexus .lane_catalog .lanes() .iter() .find(|lane| lane.id == lane_id) .expect("staged drain lane remains in the catalog") };
    let_row! { staged_drain = decode_autoscale_lane_drain_state(staged_lane) .expect("staged drain metadata is canonical") .expect("staged drain metadata remains present") };
    let_row! { staged_commitment = staged_drain .commitment .expect("certificate-only carrier stages the drain commitment") };
    assert_eq!(
        staged_commitment.certificate_hash,
        certificate.canonical_hash()
    );
    assert_eq!(staged_commitment.merge_entry_hash, entry.canonical_hash());
    assert_eq!(staged_commitment.carrier_height, 2);
    drop(carrier);
    assert!(matches!(
        state.commit_merge_entry(entry.clone()),
        Err(MergeLedgerCommitError::ExecutionRequiresGlobalBlock)
    ));
    let mut wrong_order = certificate.clone();
    wrong_order.validator_set.swap(0, 1);
    assert!(
        state
            .merge_drain_candidate_for_next_carrier(&parent_header, 7, wrong_order)
            .is_err(),
        "certificate validator order must equal the embedded intent order"
    );
    seed_direct_lane_application_marker_for_incarnation(
        &state,
        lane_id,
        incarnation,
        DataSpaceId::UNIVERSAL,
        1,
        0x51,
    );
    assert!(
        state.pending_autoscale_lane_drain_body().is_some(),
        "transient application evidence must not erase the stable drain body"
    );
    assert!(
        state.lane_has_drain_blocking_evidence(lane_id, DataSpaceId::UNIVERSAL, incarnation),
        "an unrepaired exact-incarnation application marker must block drain"
    );
    assert!(matches!(
        state.merge_drain_candidate_for_next_carrier(&parent_header, 7, certificate.clone()),
        Err(MergeLedgerCommitError::ExecutionBatchInvalid(_))
    ));
    let mut duplicated = candidate;
    duplicated.lane_drain_certificates.push(certificate);
    assert!(
        state
            .validate_merge_candidate_for_global_round(&duplicated, &parent_header, 7)
            .is_err(),
        "a merge candidate may carry at most one drain certificate"
    );
}
state_test! { sync drain_intent_uses_incarnation_pin_across_disjoint_roster_and_key_rotation
    let mut state = blank_test_state();
    install_default_autoscale_test_nexus(&mut state, "install roster-boundary autoscale nexus");
    state
        .apply_lane_lifecycle_with_options(
            &iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![autoscale_elastic_lane_config(
                    LaneId::new(1),
                    DataSpaceId::UNIVERSAL,
                    1,
                )],
                retire: Vec::new(),
            },
            false,
            true,
        )
        .expect("install roster-boundary drain lane");
    let old_keypairs = autoscale_drain_keypairs_for_test(4);
    let_row! { new_keypairs = (0..4) .map(|index| { let seed = u8::try_from(index) .expect("new committee index fits u8") .saturating_add(0xB1); KeyPair::try_from_seed(vec![seed; 32], Algorithm::BlsNormal) .expect("deterministic disjoint close-height key") }) .collect::<Vec<_>>() };
    let_row! { all_keypairs = old_keypairs .iter() .chain(&new_keypairs) .cloned() .collect::<Vec<_>>() };
    seed_consensus_keys_with_pops(&state, &all_keypairs);
    {
        let mut topology = state.commit_topology.block();
        topology.clear();
        topology.extend(
            old_keypairs
                .iter()
                .map(|keypair| PeerId::new(keypair.public_key().clone())),
        );
        topology.commit();
    }
    let lane_id = LaneId::new(1);
    let expected_close_committee = state.authoritative_lane_peer_ids_at_height(lane_id, 1);
    assert_eq!(expected_close_committee.len(), 4);
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 100, 0);
    let mut state_block = state.block(header);
    let_row! { new_peers = new_keypairs .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    {
        let mut peers = state_block.world.peers_mut_for_testing().transaction();
        peers.clear();
        peers.extend(new_peers.clone());
        peers.apply();
    }
    for keypair in &old_keypairs {
        let key_id = derive_validator_key_id(keypair.public_key());
        let_row! { mut record = state_block .world .consensus_keys .get(&key_id) .cloned() .expect("old committee key record") };
        record.status = ConsensusKeyStatus::Disabled;
        state_block.world.consensus_keys.insert(key_id, record);
    }
    state_block
        .commit_topology
        .mutate_vec(|topology| topology.clone_from(&new_peers));
    let_row! { overlay_committee = State::derive_new_autoscale_lane_committee_from_sources( &state_block.world, &state_block.network_id, lane_id, state_block.lane_manifests.as_ref(), &state_block.nexus, &new_peers, 1, ) };
    assert_eq!(overlay_committee.len(), 4);
    assert!(
        overlay_committee
            .iter()
            .all(|peer| !expected_close_committee.contains(peer)),
        "the post-block committee must be disjoint for the adversarial boundary"
    );
    let_row! { pinned_overlay_authority = State::authoritative_lane_peer_ids_from_sources( &state_block.world, lane_id, state_block .nexus .staking .validator_mode(lane_id, &state_block.nexus.lane_catalog), state_block.lane_manifests.as_ref(), &state_block.nexus, &new_peers, 1, ) };
    assert_eq!(
        pinned_overlay_authority, expected_close_committee,
        "current-world removal and disjoint topology rotation must not change incarnation authority"
    );
    let_row! { intent = state_block .build_autoscale_lane_drain_intent(lane_id) .expect("drain intent resolves the proposal-height parent authority") };
    assert_eq!(intent.close_global_height, 1);
    assert_eq!(intent.validator_set, expected_close_committee);
    assert_ne!(intent.validator_set, overlay_committee);
    let_row! { body = LaneDrainCertificateBodyV1 { version: 1, intent: intent.clone(), final_frontier: intent.initial_frontier, } };
    for keypair in &new_keypairs {
        assert!(
            crate::lane_consensus::LaneDrainVoteV1::new_signed(
                body.clone(),
                PeerId::new(keypair.public_key().clone()),
                keypair.private_key(),
            )
            .is_err(),
            "a disjoint post-close signer must be rejected before aggregation"
        );
    }
    assert!(
        crate::lane_consensus::aggregate_lane_drain_votes(body.clone(), overlay_committee, &[],)
            .is_err(),
        "a disjoint post-close roster must not certify the old committee's final frontier"
    );
    let_row! { old_keypairs_by_peer = old_keypairs .iter() .map(|keypair| (PeerId::new(keypair.public_key().clone()), keypair)) .collect::<BTreeMap<_, _>>() };
    let_row! { old_votes = intent .validator_set .iter() .map(|peer| { let keypair = old_keypairs_by_peer .get(peer) .expect("embedded old-roster signer key"); crate::lane_consensus::LaneDrainVoteV1::new_signed( body.clone(), peer.clone(), keypair.private_key(), ) .expect("well-formed old-roster vote") }) .collect::<Vec<_>>() };
    crate::lane_consensus::aggregate_lane_drain_votes(body, intent.validator_set, &old_votes)
        .expect("the exact proposal-height committee remains able to certify");
}
#[test]
fn committed_drain_suppresses_hot_scale_out_and_only_later_commitment_retires_highest_lane() {
    for certified in [false, true] {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        let first = autoscale_signed_block_with_committed_fragments(None, 100, 0);
        let second = autoscale_signed_block_with_committed_fragments(Some(&first), 200, 0);
        let third = autoscale_signed_block_with_committed_fragments(Some(&second), 300, 0);
        let fourth = autoscale_signed_block_with_committed_fragments(Some(&third), 400, 100);
        {
            let mut hashes = state.block_hashes.block();
            hashes.push_for_tests(first.header().hash());
            hashes.commit_for_tests();
        }
        state
            .set_nexus(autoscale_transition_test_nexus(
                vec![LaneConfig::default()],
                1,
                4,
                100,
            ))
            .expect("install load-flip autoscale nexus");
        state
            .apply_lane_lifecycle_with_options(
                &iroha_data_model::nexus::LaneLifecyclePlan {
                    additions: vec![
                        autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 1),
                        autoscale_elastic_lane_config(LaneId::new(2), DataSpaceId::UNIVERSAL, 1),
                    ],
                    retire: Vec::new(),
                },
                false,
                true,
            )
            .expect("install two managed lanes");
        {
            let mut hashes = state.block_hashes.block();
            hashes.push_for_tests(second.header().hash());
            hashes.commit_for_tests();
        }
        let lane_id = LaneId::new(2);
        let_row! { incarnation = state .lane_incarnation(lane_id) .expect("highest managed lane incarnation") };
        let_row! { validator_set = autoscale_drain_keypairs_for_test(4) .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
        let_row! { commitment = certified.then(|| LaneDrainCommitmentV1 { version: 1, certificate_hash: HashOf::from_untyped_unchecked(Hash::new( b"load-flip-drain-certificate", )), merge_entry_hash: HashOf::from_untyped_unchecked(Hash::new( b"load-flip-drain-merge-entry", )), carrier_height: 3, frontier: LaneDrainFrontierV1::ordinary( lane_id, DataSpaceId::UNIVERSAL, incarnation, 0, None, ), }) };
        let_row! { drain_state = autoscale_drain_state_for_test( lane_id, DataSpaceId::UNIVERSAL, incarnation, 2, validator_set, commitment, ) };
        let mut nexus = state.nexus_snapshot();
        let mut lanes = nexus.lane_catalog.lanes().to_vec();
        lanes
            .iter_mut()
            .find(|lane| lane.id == lane_id)
            .expect("highest managed lane")
            .metadata
            .insert(
                AUTOSCALE_META_DRAIN_STATE.to_owned(),
                encode_autoscale_lane_drain_state(&drain_state)
                    .expect("canonical load-flip drain state"),
            );
        nexus.lane_catalog = LaneCatalog::new(nexus.lane_catalog.lane_count(), lanes)
            .expect("load-flip drain catalog");
        nexus.lane_config =
            iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
        nexus.autoscale.last_transition_height = 2;
        *state.nexus.write() = nexus;
        if certified {
            let same_carrier = state.block(third.header());
            assert_eq!(
                same_carrier.select_autoscale_scale_in_action(&third),
                None,
                "the certificate carrier itself must never retire its lane"
            );
            drop(same_carrier);
        }
        {
            let mut hashes = state.block_hashes.block();
            hashes.push_for_tests(third.header().hash());
            hashes.commit_for_tests();
        }
        let_row! { committed_fourth = ValidBlock::new_unverified_for_tests(fourth.clone()) .commit_unchecked() .unpack(|_| {}) };
        let mut state_block = state.block(fourth.header());
        state_block.add_committed_fragments(100);
        state_block.maybe_apply_nexus_autoscale(&committed_fourth);
        if certified {
            let_row! { pending = state_block .pending_autoscale_lifecycle .as_ref() .expect("a certified drain retires on the strictly later carrier") };
            assert!(matches!(
                &pending.transition,
                PendingAutoscaleTransition::ScaleIn { lane, .. } if *lane == lane_id
            ));
            assert_eq!(pending.plan.retire, vec![lane_id]);
            assert_eq!(pending.transition_height, 4);
            assert_eq!(state_block.nexus.autoscale.last_transition_height, 4);
            assert!(
                state_block
                    .nexus
                    .lane_catalog
                    .lanes()
                    .iter()
                    .any(|lane| lane.id == LaneId::new(1))
            );
            assert!(
                state_block
                    .nexus
                    .lane_catalog
                    .lanes()
                    .iter()
                    .all(|lane| lane.id != lane_id && lane.id != LaneId::new(3)),
                "only the highest draining lane retires; no hot scale-out may interleave"
            );
        } else {
            assert!(
                state_block.pending_autoscale_lifecycle.is_none(),
                "an uncertified irreversible drain must wait even after load flips hot"
            );
            assert_eq!(state_block.nexus.autoscale.last_transition_height, 2);
            assert!(
                state_block
                    .nexus
                    .lane_catalog
                    .lanes()
                    .iter()
                    .all(|lane| lane.id != LaneId::new(3)),
                "an in-progress drain suppresses unrelated scale-out"
            );
        }
    }
}
