fn autoscale_signed_block_with_committed_fragments(
    prev_block: Option<&SignedBlock>,
    creation_time_ms: u64,
    committed_fragments: u64,
) -> SignedBlock {
    let keypair = crate::state::checked_keypair();
    let_row! { valid = crate::block::ValidBlock::new_dummy_and_modify_header(keypair.private_key(), |header| { let (height, prev_block_hash) = prev_block.map_or((nonzero!(1_u64), None), |block| { ( NonZeroU64::new(block.header().height().get().saturating_add(1)) .expect("saturating nonzero height remains nonzero"), Some(block.hash()), ) }); header.set_height(height); header.set_prev_block_hash(prev_block_hash); header.creation_time_ms = creation_time_ms; }) };
    let mut block: SignedBlock = valid.into();
    let entry_hashes: Vec<HashOf<TransactionEntrypoint>> = Vec::new();
    let results: Vec<TransactionResultInner> = Vec::new();
    block
        .set_transaction_results_with_transcripts(
            Vec::new(),
            &entry_hashes,
            results,
            BTreeMap::new(),
            Vec::new(),
            AxtPolicySnapshot::default(),
        )
        .expect("empty autoscale test block should accept an empty result");
    block.set_committed_fragment_count(committed_fragments);
    block
}
fn store_block_for_state_commit(kura: &Arc<Kura>, block: &SignedBlock) {
    kura.store_block(Arc::new(block.clone()))
        .expect("store block before committing its StateBlock");
}
fn store_committed_autoscale_history_block_for_test(
    state: &State,
    kura: &Arc<Kura>,
    block: &SignedBlock,
) {
    kura.store_block(Arc::new(block.clone()))
        .expect("store committed autoscale history block");
    seed_committed_autoscale_history_block_for_test(state, block);
}
fn seed_committed_autoscale_history_block_for_test(state: &State, block: &SignedBlock) {
    let_row! { record = AutoscaleSampleRecord { block_height: block.header().height().get(), block_hash: block.header().hash(), creation_time_ms: u64::try_from(block.header().creation_time().as_millis()) .expect("test block timestamp fits u64"), work_count: autoscale_block_work_count( block.external_transactions().len(), block.committed_fragment_count(), ), } };
    let cap = autoscale_sample_history_cap(&state.nexus_snapshot().autoscale);
    append_autoscale_sample_record(&mut state.autoscale_sample_history.write(), record, cap);
}
fn insert_empty_transaction_block_for_state_commit(
    state_block: &mut StateBlock<'_>,
    block: &SignedBlock,
) {
    let_row! { block_height = block .header() .height() .try_into() .expect("test block height must fit transaction storage height") };
    state_block
        .transactions
        .insert_block(std::collections::HashSet::new(), block_height);
}
fn commit_state_block_with_empty_autoscale_queue(
    state_block: StateBlock<'_>,
) -> Result<(), TransactionsBlockError> {
    let mut queue_veto = |_: LaneId, _: DataSpaceId, _: Hash| Ok(());
    state_block.commit_with_autoscale_retirement_queue_veto(&mut queue_veto)
}
fn manual_lane_lifecycle_payload() -> iroha_data_model::nexus::LaneLifecycleParameterV1 {
    let expected_catalog = LaneCatalog::default();
    let incarnations = derive_static_lane_incarnations(&expected_catalog);
    let_row! { incarnations = iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations( &expected_catalog, &incarnations, ) .expect("default lifecycle incarnation set is canonical") };
    iroha_data_model::nexus::LaneLifecycleParameterV1::new(
        &expected_catalog,
        &incarnations,
        iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: LaneId::new(1),
                alias: "manual-consensus-lane".to_owned(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        },
    )
    .expect("manual lifecycle payload is canonical")
}
fn manual_lane_lifecycle_test_state(world: World) -> State {
    let_row! { mut state = State::new_for_testing( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let_row! { mut nexus = iroha_config::parameters::actual::Nexus { enabled: true, ..Default::default() } };
    nexus.fees.base_fee = Quantity::zero();
    nexus.fees.per_byte_fee = Quantity::zero();
    nexus.fees.per_instruction_fee = Quantity::zero();
    nexus.fees.per_gas_unit_fee = Quantity::zero();
    state
        .set_nexus(nexus)
        .expect("enable Nexus for manual lifecycle test");
    state
}
fn committed_manual_lane_lifecycle_block(
    authority: &AccountId,
    signer: &KeyPair,
) -> CommittedBlock {
    let parameter = manual_lane_lifecycle_payload().into_custom_parameter();
    let_row! { transaction = TransactionBuilder::new( *super::DEFAULT_TEST_NETWORK_ID, authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .with_instructions([iroha_data_model::isi::SetParameter::new(Parameter::Custom( parameter, ))]) .sign(signer.private_key()) };
    let entry_hash = transaction.hash_as_entrypoint();
    let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
    let_row! { unverified = BlockBuilder::new(vec![accepted]) .chain(0, None) .sign(signer.private_key()) .unpack(|_| {}) };
    let mut signed: SignedBlock = unverified.into();
    signed
        .set_transaction_results(
            Vec::new(),
            &[entry_hash],
            vec![TransactionResultInner::Ok(DataTriggerSequence::default())],
        )
        .expect("manual lifecycle transaction result must match entrypoint");
    ValidBlock::new_unverified_for_tests(signed)
        .commit_unchecked()
        .unpack(|_| {})
}
state_test! { sync consensus_lane_lifecycle_replay_converges_on_fresh_state
    use iroha_executor_data_model::permission::parameter::CanSetParameters;
    let (authority, signer) = gen_account_in("universal");
    let committed = committed_manual_lane_lifecycle_block(&authority, &signer);
    let_row! { replay_world = || { let domain = Domain::new(sample_domain_id()).build(&authority); let account = Account::new(authority.clone()).build(&authority); let mut world = World::with([domain], [account], []); world.account_permissions.insert( authority.clone(), BTreeSet::from([Permission::from(CanSetParameters)]), ); world } };
    let first = manual_lane_lifecycle_test_state(replay_world());
    let replay = manual_lane_lifecycle_test_state(replay_world());
    for state in [&first, &replay] {
        let mut block = state.block(committed.as_ref().header());
        let _ = block.apply(&committed, Vec::new());
        block
            .commit()
            .expect("consensus lane lifecycle replay must commit");
    }
    let first_nexus = first.nexus_snapshot();
    let replay_nexus = replay.nexus_snapshot();
    assert_eq!(first_nexus.lane_catalog, replay_nexus.lane_catalog);
    assert!(lane_config_entries_match(
        &first_nexus.lane_config,
        &replay_nexus.lane_config
    ));
    assert!(
        first_nexus
            .lane_catalog
            .lanes()
            .iter()
            .any(|lane| lane.id == LaneId::new(1)),
        "replayed signed lifecycle transaction must publish the new lane"
    );
    assert_eq!(
        first_nexus.autoscale.last_transition_height, 0,
        "manual transitions must not consume autoscale cooldown"
    );
    let (events_sender, _) = tokio::sync::broadcast::channel(8);
    let_row! { queue = crate::queue::Queue::from_config( iroha_config::parameters::actual::Queue::default(), events_sender, ) };
    assert!(queue.reconfigure_nexus_with_state_if_needed(&first_nexus, &first, None,));
    assert!(
        !queue.reconfigure_nexus_with_state_if_needed(&first_nexus, &first, None),
        "queue topology refresh must be idempotent after committed lifecycle publication"
    );
}
state_test! { sync consensus_lane_lifecycle_rejects_stale_catalog_without_overlay_mutation
    use crate::smartcontracts::Execute as _;
    let state = manual_lane_lifecycle_test_state(World::default());
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
    let mut block = state.block(header);
    let mut transaction = block.transaction();
    let mut payload = manual_lane_lifecycle_payload();
    payload.expected_catalog_hash = Hash::new(b"stale-lane-catalog");
    let_row! { err = iroha_data_model::isi::SetParameter::new(Parameter::Custom( payload.into_custom_parameter(), )) .execute(&ALICE_ID, &mut transaction) .expect_err("stale catalog commitment must fail closed") };
    assert!(
        format!("{err:?}").contains("expected catalog hash"),
        "unexpected stale-catalog error: {err:?}"
    );
    drop(transaction);
    assert_eq!(block.nexus.lane_catalog, LaneCatalog::default());
    assert!(block.pending_autoscale_lifecycle.is_none());
}
state_test! { sync consensus_lane_lifecycle_rejects_second_transition_and_rolls_back_first
    use crate::smartcontracts::Execute as _;
    let state = manual_lane_lifecycle_test_state(World::default());
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
    let mut block = state.block(header);
    let mut transaction = block.transaction();
    let_row! { instruction = || { iroha_data_model::isi::SetParameter::new(Parameter::Custom( manual_lane_lifecycle_payload().into_custom_parameter(), )) } };
    instruction()
        .execute(&ALICE_ID, &mut transaction)
        .expect("first transition may stage in the transaction overlay");
    let_row! { err = instruction() .execute(&ALICE_ID, &mut transaction) .expect_err("a second transition in the same transaction must be rejected") };
    assert!(
        format!("{err:?}").contains("already staged"),
        "unexpected duplicate-transition error: {err:?}"
    );
    drop(transaction);
    assert_eq!(block.nexus.lane_catalog, LaneCatalog::default());
    assert!(block.pending_autoscale_lifecycle.is_none());
}
state_test! { sync normal_validation_requires_can_set_parameters_for_lane_lifecycle
    use iroha_executor_data_model::permission::parameter::CanSetParameters;
    let (authority, signer) = gen_account_in("universal");
    let domain = Domain::new(sample_domain_id()).build(&authority);
    let account = Account::new(authority.clone()).build(&authority);
    for authorized in [false, true] {
        let mut world = World::with([domain.clone()], [account.clone()], []);
        if authorized {
            world.account_permissions.insert(
                authority.clone(),
                BTreeSet::from([Permission::from(CanSetParameters)]),
            );
        }
        let state = manual_lane_lifecycle_test_state(world);
        let_row! { transaction = TransactionBuilder::new( *state.network_id_ref(), authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .with_instructions([iroha_data_model::isi::SetParameter::new(Parameter::Custom( manual_lane_lifecycle_payload().into_custom_parameter(), ))]) .sign(signer.private_key()) };
        let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
        let_row! { parent: SignedBlock = BlockBuilder::new(Vec::<AcceptedTransaction<'static>>::new()) .chain(0, None) .sign(signer.private_key()) .unpack(|_| {}) .into() };
        let_row! { unverified = BlockBuilder::new(vec![accepted]) .chain(0, Some(&parent)) .sign(signer.private_key()) .unpack(|_| {}) };
        let mut state_block = state.block(unverified.header());
        let_row! { committed = unverified .validate_and_record_transactions(&mut state_block) .unpack(|_| {}) .commit_unchecked() .unpack(|_| {}) };
        let signed: SignedBlock = committed.into();
        if authorized {
            assert!(
                signed.error(0).is_none(),
                "CanSetParameters holder should pass lifecycle validation: {:?}",
                signed.error(0)
            );
            assert!(state_block.pending_autoscale_lifecycle.is_some());
        } else {
            let_row! { rejection = format!( "{:?}", signed .error(0) .expect("authority without CanSetParameters must be rejected") ) };
            assert!(
                rejection.contains("Can't set network parameters without CanSetParameters"),
                "unexpected permission rejection: {rejection}"
            );
            assert!(state_block.pending_autoscale_lifecycle.is_none());
        }
    }
}
