state_test! { sync signed_lane_lifecycle_rejects_stale_catalog_after_prior_commit
    use iroha_executor_data_model::permission::parameter::CanSetParameters;
    let (authority, signer) = gen_account_in("universal");
    let domain = Domain::new(sample_domain_id()).build(&authority);
    let account = Account::new(authority.clone()).build(&authority);
    let mut world = World::with([domain], [account], []);
    world.account_permissions.insert(
        authority.clone(),
        BTreeSet::from([Permission::from(CanSetParameters)]),
    );
    let state = manual_lane_lifecycle_test_state(world);
    let first = committed_manual_lane_lifecycle_block(&authority, &signer);
    {
        let mut block = state.block(first.as_ref().header());
        let _ = block.apply(&first, Vec::new());
        block.commit().expect("commit first lifecycle transition");
    }
    let before = state.nexus_snapshot().lane_catalog;
    assert!(before.lanes().iter().any(|lane| lane.id == LaneId::new(1)));
    let_row! { stale_incarnations = derive_static_lane_incarnations(&LaneCatalog::default()) };
    let_row! { stale_incarnations = iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations( &LaneCatalog::default(), &stale_incarnations, ) .expect("default lifecycle incarnation set is canonical") };
    let_row! { stale_payload = iroha_data_model::nexus::LaneLifecycleParameterV1::new( &LaneCatalog::default(), &stale_incarnations, iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![LaneConfig { id: LaneId::new(2), alias: "stale-second-lane".to_owned(), ..LaneConfig::default() }], retire: Vec::new(), }, ) .expect("stale lifecycle payload is structurally canonical") };
    let_row! { transaction = TransactionBuilder::new( *state.network_id_ref(), authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .with_instructions([iroha_data_model::isi::SetParameter::new(Parameter::Custom( stale_payload.into_custom_parameter(), ))]) .sign(signer.private_key()) };
    let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
    let_row! { unverified = BlockBuilder::new(vec![accepted]) .chain(0, Some(first.as_ref())) .sign(signer.private_key()) .unpack(|_| {}) };
    let mut state_block = state.block(unverified.header());
    let_row! { committed = unverified .validate_and_record_transactions(&mut state_block) .unpack(|_| {}) .commit_unchecked() .unpack(|_| {}) };
    let signed: SignedBlock = committed.into();
    let_row! { rejection = format!( "{:?}", signed .error(0) .expect("stale signed lifecycle transition must be rejected") ) };
    assert!(rejection.contains("expected catalog hash"), "{rejection}");
    assert_eq!(state_block.nexus.lane_catalog, before);
    assert!(state_block.pending_autoscale_lifecycle.is_none());
}
state_test! { sync signed_lane_lifecycle_rejects_stale_identical_replacement_incarnation
    let mut state = manual_lane_lifecycle_test_state(World::default());
    let_row! { lane = LaneConfig { id: LaneId::new(1), alias: "replaceable-manual-lane".to_owned(), ..LaneConfig::default() } };
    let_row! { catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane.clone()]) .expect("two-lane catalog is valid") };
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: catalog.clone(),
            ..Default::default()
        })
        .expect("install initial manual lane");
    let_row! { stale_incarnations = iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations( &catalog, &state.lane_incarnations_snapshot(), ) .expect("active incarnations are canonical") };
    let_row! { replacement = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![lane], retire: vec![LaneId::new(1)], } };
    let_row! { stale_payload = iroha_data_model::nexus::LaneLifecycleParameterV1::new( &catalog, &stale_incarnations, replacement.clone(), ) .expect("replacement payload is canonical") };
    let_row! { old_incarnation = state .lane_incarnation(LaneId::new(1)) .expect("lane has an incarnation") };
    state
        .apply_lane_lifecycle(&replacement)
        .expect("first identical replacement succeeds");
    assert_eq!(state.nexus_snapshot().lane_catalog, catalog);
    assert_ne!(
        state.lane_incarnation(LaneId::new(1)),
        Some(old_incarnation),
        "byte-identical replacement must rotate the incarnation"
    );
    let before_incarnations = state.lane_incarnations_snapshot();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
    let mut block = state.block(header);
    let mut transaction = block.transaction();
    let_row! { error = transaction .stage_consensus_lane_lifecycle(&stale_payload) .expect_err("old incarnation-bound payload must not replay") };
    assert!(matches!(
        error,
        LaneLifecycleError::StaleIncarnationRoot { .. }
    ));
    assert_eq!(transaction.lane_incarnations, before_incarnations);
    drop(transaction);
    drop(block);
    assert_eq!(state.lane_incarnations_snapshot(), before_incarnations);
}
