fn autoscale_drain_keypairs_for_test(count: usize) -> Vec<KeyPair> {
    if count == 4 {
        return synthetic_autoscale_committee_keypairs_for_test();
    }
    let_row! { mut keypairs = (0..count) .map(|index| { let seed = u8::try_from(index) .expect("drain committee test index must fit u8") .saturating_add(0x91); KeyPair::try_from_seed(vec![seed; 32], Algorithm::BlsNormal) .expect("deterministic lane drain BLS key") }) .collect::<Vec<_>>() };
    keypairs.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    keypairs
}
