state_test! { sync autoscale_decision_is_identical_with_asymmetric_kura_body_retention
    let full_kura = Kura::blank_kura_for_testing();
    let evicted_kura = Kura::blank_kura_for_testing();
    let_row! { mut full_state = State::new_for_testing( World::default(), Arc::clone(&full_kura), LiveQueryStore::start_test(), ) };
    let_row! { mut evicted_state = State::new_for_testing( World::default(), Arc::clone(&evicted_kura), LiveQueryStore::start_test(), ) };
    let mut nexus = autoscale_transition_test_nexus(vec![LaneConfig::default()], 1, 3, 100);
    nexus.autoscale.scale_out_window_blocks = nonzero!(2_u16);
    full_state
        .set_nexus(nexus.clone())
        .expect("configure full-history validator");
    evicted_state
        .set_nexus(nexus)
        .expect("configure evicted-history validator");
    seed_autoscale_committee_for_test(&full_state, 4);
    seed_autoscale_committee_for_test(&evicted_state, 4);
    let first = autoscale_signed_block_with_committed_fragments(None, 100, 0);
    let second = autoscale_signed_block_with_committed_fragments(Some(&first), 200, 20);
    let third = autoscale_signed_block_with_committed_fragments(Some(&second), 300, 0);
    full_kura
        .store_block(Arc::new(first.clone()))
        .expect("store first body only on the full-history validator");
    full_kura
        .store_block(Arc::new(second.clone()))
        .expect("store second body only on the full-history validator");
    for state in [&full_state, &evicted_state] {
        seed_committed_autoscale_history_block_for_test(state, &first);
        seed_committed_autoscale_history_block_for_test(state, &second);
    }
    let_row! { committed_third = ValidBlock::new_unverified_for_tests(third.clone()) .commit_unchecked() .unpack(|_| {}) };
    let mut full_block = full_state.block(third.header());
    full_block.add_committed_fragments(20);
    full_block.maybe_apply_nexus_autoscale(&committed_third);
    let mut evicted_block = evicted_state.block(third.header());
    evicted_block.add_committed_fragments(20);
    evicted_block.maybe_apply_nexus_autoscale(&committed_third);
    assert_eq!(
        SnapshotNexusRuntime::from_nexus(
            &full_block.nexus,
            &full_block.lane_incarnations,
            &full_block.lane_incarnation_activation_heights,
            &full_block.lane_incarnation_lineage,
        ),
        SnapshotNexusRuntime::from_nexus(
            &evicted_block.nexus,
            &evicted_block.lane_incarnations,
            &evicted_block.lane_incarnation_activation_heights,
            &evicted_block.lane_incarnation_lineage,
        ),
        "Kura body eviction must not change the effective Nexus runtime",
    );
    assert_eq!(
        full_block
            .pending_autoscale_lifecycle
            .as_ref()
            .map(|pending| pending.transition.clone()),
        evicted_block
            .pending_autoscale_lifecycle
            .as_ref()
            .map(|pending| pending.transition.clone()),
        "Kura body eviction must not change the deterministic scale decision"
    );
    assert!(full_block.pending_autoscale_lifecycle.is_some());
}
state_test! { sync autoscale_transition_adds_managed_elastic_lane_when_window_is_hot
    let (mut state, kura) = blank_test_state_with_kura();
    install_default_autoscale_test_nexus(&mut state, "apply autoscale test nexus config");
    seed_autoscale_committee_for_test(&state, 4);
    let first = autoscale_signed_block_with_committed_fragments(None, 100, 0);
    let second = autoscale_signed_block_with_committed_fragments(Some(&first), 200, 0);
    store_committed_autoscale_history_block_for_test(&state, &kura, &first);
    store_block_for_state_commit(&kura, &second);
    let mut state_block = state.block(second.header());
    state_block.add_committed_fragments(20);
    commit_autoscale_transition!(state_block, second, nexus);
    let_row! { lane = nexus .lane_catalog .lanes() .iter() .find(|lane| lane.id == LaneId::new(1)) .expect("scale-out should add lane 1") };
    assert_eq!(lane.dataspace_id, DataSpaceId::UNIVERSAL);
    assert_eq!(lane.alias, "elastic-lane-1");
    assert_eq!(
        lane.metadata.get(AUTOSCALE_META_MANAGED),
        Some(&"true".to_owned())
    );
    assert_eq!(
        lane.metadata.get(AUTOSCALE_META_CREATED_HEIGHT),
        Some(&"2".to_owned())
    );
    assert_eq!(nexus.autoscale.last_transition_height, 2);
    let_row! { pending = state_block .pending_autoscale_lifecycle .as_ref() .expect("successful scale-out must stage a lifecycle update for commit") };
    assert_eq!(
        pending.transition_height, 2,
        "staged scale-out lifecycle must carry the block transition height"
    );
    assert_eq!(
        pending.transition,
        PendingAutoscaleTransition::ScaleOut {
            lane: LaneId::new(1),
            active_lanes: 1,
            autoscale_capacity_lanes: 1,
            out_latency_ratio_permille: 1_000,
            out_utilization_p95_permille: autoscale_utilization_permille(20, 100, 1, 10),
        },
        "staged scale-out lifecycle must preserve deterministic transition telemetry for commit logging"
    );
    assert_eq!(
        pending.catalog_update.updated_catalog, nexus.lane_catalog,
        "staged scale-out catalog must match the block-local Nexus catalog"
    );
    assert_eq!(
        pending
            .catalog_update
            .updated_lane_config
            .entries()
            .iter()
            .map(|entry| entry.lane_id)
            .collect::<Vec<_>>(),
        nexus
            .lane_config
            .entries()
            .iter()
            .map(|entry| entry.lane_id)
            .collect::<Vec<_>>(),
        "staged scale-out lane config entries must match the block-local Nexus lane config"
    );
    assert_eq!(
        pending.catalog_update.updated_lane_config.shard_mapping(),
        nexus.lane_config.shard_mapping(),
        "staged scale-out shard mapping must match the block-local Nexus lane config"
    );
    assert_eq!(
        pending.catalog_update.lanes_to_reset,
        BTreeSet::from([LaneId::new(1)]),
        "scale-out must stage the new elastic lane as a clean state boundary"
    );
    assert!(
        pending.catalog_update.replaced_lane_ids.is_empty(),
        "scale-out of a fresh elastic lane must not be staged as a replacement"
    );
}
state_test! { sync autoscale_transition_prunes_inactive_lane_relay_emergency_overrides
    let (mut state, kura) = blank_test_state_with_kura();
    install_default_autoscale_test_nexus(&mut state, "apply autoscale test nexus config");
    seed_autoscale_committee_for_test(&state, 4);
    let retained_lane = LaneId::SINGLE;
    let stale_lane = LaneId::new(9);
    let_row! { override_set = LaneRelayEmergencyValidatorSet { peers: vec![PeerId::from(ALICE_ID.expect_single_signatory().clone())], expires_at_height: 10, metadata: Metadata::default(), } };
    {
        let mut wb = state.world.block();
        wb.lane_relay_emergency_validators
            .insert(retained_lane, override_set.clone());
        wb.lane_relay_emergency_validators
            .insert(stale_lane, override_set);
        wb.commit();
    }
    let first = autoscale_signed_block_with_committed_fragments(None, 100, 0);
    let mut first_state_block = state.block(first.header());
    let_row! { committed_first = ValidBlock::new_unverified_for_tests(first.clone()) .commit_unchecked() .unpack(|_| {}) };
    let _ = first_state_block.apply_without_execution(&committed_first, Vec::new());
    first_state_block
        .commit()
        .expect("commit first block before autoscale scale-out");
    store_committed_autoscale_history_block_for_test(&state, &kura, &first);
    let second = autoscale_signed_block_with_committed_fragments(Some(&first), 200, 0);
    let mut state_block = state.block(second.header());
    state_block.add_committed_fragments(20);
    let_row! { committed_second = ValidBlock::new_unverified_for_tests(second) .commit_unchecked() .unpack(|_| {}) };
    let _events = state_block.apply_without_execution(&committed_second, Vec::new());
    assert!(
        state_block.pending_autoscale_lifecycle.is_some(),
        "hot window should stage autoscale scale-out"
    );
    assert!(
        state_block
            .world
            .lane_relay_emergency_validators
            .get(&stale_lane)
            .is_none(),
        "autoscale scale-out must prune emergency overrides for lanes absent from the updated catalog"
    );
    assert!(
        state_block
            .world
            .lane_relay_emergency_validators
            .get(&retained_lane)
            .is_some(),
        "autoscale scale-out must retain emergency overrides for active lanes"
    );
    state_block
        .commit()
        .expect("autoscale scale-out commits inactive override cleanup");
    let view = state.world.view();
    assert!(
        view.lane_relay_emergency_validators()
            .get(&stale_lane)
            .is_none(),
        "committed state must not retain inactive-lane emergency overrides after autoscale scale-out"
    );
    assert!(
        view.lane_relay_emergency_validators()
            .get(&retained_lane)
            .is_some(),
        "committed state must retain active-lane emergency overrides after autoscale scale-out"
    );
    assert_eq!(
        state
            .nexus_snapshot()
            .lane_catalog
            .lanes()
            .iter()
            .map(|lane| lane.id)
            .collect::<Vec<_>>(),
        vec![LaneId::SINGLE, LaneId::new(1)]
    );
}
