    let_row! { retired_relay_key = State::verified_lane_relay_state_key(&retired_relay).expect("retired state key") };
    seed_verified_lane_relay_record(&state, &retired_relay);
    let_row! { retained_relay = sample_lane_relay_envelope(3, LaneId::SINGLE, &signers, full_signer_bitmap(4)) .with_manifest_root(Some([0xF8; 32])) };
    let_row! { retained_relay_key = State::verified_lane_relay_state_key(&retained_relay).expect("retained state key") };
    seed_verified_lane_relay_record(&state, &retained_relay);
