state_test! { sync public_lane_economic_cleanup_keys_treat_key_or_record_lane_as_reset_owner
    let world = World::default();
    let reset_lane = LaneId::new(51);
    let retained_lane = LaneId::new(52);
    let validator = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let key_owned_staker = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let record_owned_staker = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let retained_staker = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let_row! { reward_asset_definition = AssetDefinitionId::derive_from_components( DomainId::try_new("publiclane", "universal").expect("reward asset domain"), "resetcheck".parse().expect("reward asset name"), ) };
    let reward_asset = AssetId::new(reward_asset_definition, validator.clone());
    let_row! { stake_record_for = |lane_id: LaneId, staker: AccountId| PublicLaneStakeShare { lane_id, validator: validator.clone(), staker, bonded: iroha_primitives::numeric::Quantity::from(100_u32), pending_unbonds: BTreeMap::new(), metadata: Metadata::default(), } };
    let_row! { reward_record_for = |lane_id: LaneId, epoch: u64| PublicLaneRewardRecord { lane_id, epoch, asset: reward_asset.clone(), total_reward: iroha_primitives::numeric::Quantity::from(epoch.saturating_add(1)), shares: vec![PublicLaneRewardShare { account: validator.clone(), role: PublicLaneRewardRole::Validator, amount: iroha_primitives::numeric::Quantity::from(epoch.saturating_add(1)), }], metadata: Metadata::default(), } };
    let stake_key_owned = (reset_lane, validator.clone(), key_owned_staker.clone());
    let_row! { stake_record_owned = ( retained_lane, validator.clone(), record_owned_staker.clone(), ) };
    let stake_retained = (retained_lane, validator.clone(), retained_staker.clone());
    let reward_key_owned = (reset_lane, 1);
    let reward_record_owned = (retained_lane, 2);
    let reward_retained = (retained_lane, 3);
    let claim_reset = (reset_lane, validator.clone(), reward_asset.clone());
    let claim_retained = (retained_lane, retained_staker.clone(), reward_asset.clone());
    {
        let mut stake_tx = world.public_lane_stake_shares.block();
        stake_tx.insert(
            stake_key_owned.clone(),
            stake_record_for(retained_lane, key_owned_staker),
        );
        stake_tx.insert(
            stake_record_owned.clone(),
            stake_record_for(reset_lane, record_owned_staker),
        );
        stake_tx.insert(
            stake_retained.clone(),
            stake_record_for(retained_lane, retained_staker.clone()),
        );
        stake_tx.commit();
    }
    {
        let mut reward_tx = world.public_lane_rewards.block();
        reward_tx.insert(reward_key_owned, reward_record_for(retained_lane, 1));
        reward_tx.insert(reward_record_owned, reward_record_for(reset_lane, 2));
        reward_tx.insert(reward_retained, reward_record_for(retained_lane, 3));
        reward_tx.commit();
    }
    {
        let mut claim_tx = world.public_lane_reward_claims.block();
        claim_tx.insert(claim_reset.clone(), 1);
        claim_tx.insert(claim_retained.clone(), 1);
        claim_tx.commit();
    }
    let lanes_to_reset = BTreeSet::from([reset_lane]);
    let_row! { stake_keys = State::public_lane_stake_share_keys_for_lanes( &world.public_lane_stake_shares.view(), &lanes_to_reset, ) };
    let_row! { reward_keys = State::public_lane_reward_keys_for_lanes( &world.public_lane_rewards.view(), &lanes_to_reset, ) };
    let_row! { claim_keys = State::public_lane_reward_claim_keys_for_lanes( &world.public_lane_reward_claims.view(), &lanes_to_reset, ) };
    assert_eq!(
        stake_keys.into_iter().collect::<BTreeSet<_>>(),
        BTreeSet::from([stake_key_owned, stake_record_owned]),
        "stake-share cleanup must include key-owned and embedded-record-owned reset rows"
    );
    assert_eq!(
        reward_keys.into_iter().collect::<BTreeSet<_>>(),
        BTreeSet::from([reward_key_owned, reward_record_owned]),
        "reward cleanup must include key-owned and embedded-record-owned reset rows"
    );
    assert_eq!(
        claim_keys.into_iter().collect::<BTreeSet<_>>(),
        BTreeSet::from([claim_reset]),
        "reward claims have no embedded lane and remain key-owned only"
    );
}
state_test! { sync apply_lane_geometry_updates_relabels_kura_storage
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let lane_count = nonzero!(1_u32);
    let_row! { initial_catalog = LaneCatalog::new( lane_count, vec![LaneConfig { alias: "Alpha Lane".to_string(), ..LaneConfig::default() }], ) .expect("initial catalog") };
    let initial_config = RuntimeLaneConfig::from_catalog(&initial_catalog);
    let_row! { lane_entry = initial_config .entry(LaneId::SINGLE) .expect("lane entry exists") };
    let_row! { kura_cfg = KuraConfig { init_mode: InitMode::Strict, store_dir: WithOrigin::inline(store_root.clone()), max_disk_usage_bytes: iroha_config::parameters::defaults::kura::MAX_DISK_USAGE_BYTES, blocks_in_memory: iroha_config::parameters::defaults::kura::BLOCKS_IN_MEMORY, debug_output_new_blocks: false, merge_ledger_cache_capacity: iroha_config::parameters::defaults::kura::MERGE_LEDGER_CACHE_CAPACITY, fsync_mode: iroha_config::kura::FsyncMode::Batched, fsync_interval: iroha_config::parameters::defaults::kura::FSYNC_INTERVAL, block_sync_roster_retention: iroha_config::parameters::defaults::kura::BLOCK_SYNC_ROSTER_RETENTION, roster_sidecar_retention: iroha_config::parameters::defaults::kura::ROSTER_SIDECAR_RETENTION, replica_advert: iroha_config::parameters::defaults::kura::REPLICA_ADVERT_POLICY, } };
    let (kura, _) = Kura::new(&kura_cfg, &initial_config).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
    let_row! { updated_catalog = LaneCatalog::new( lane_count, vec![LaneConfig { alias: "Payments Lane".to_string(), ..LaneConfig::default() }], ) .expect("updated catalog") };
    let updated_config = RuntimeLaneConfig::from_catalog(&updated_catalog);
    let_row! { updated_entry = updated_config .entry(LaneId::SINGLE) .expect("lane entry exists") };
    let old_dir = lane_entry.blocks_dir(&store_root);
    assert!(old_dir.exists(), "expected original directory to exist");
    let incarnations = derive_static_lane_incarnations(&initial_catalog);
    let activation_heights = BTreeMap::from([(LaneId::SINGLE, 0)]);
    let lineage = state.lane_incarnation_lineage_snapshot();
    state
        .apply_lane_geometry_updates(
            &initial_config,
            &updated_config,
            &incarnations,
            &incarnations,
            &activation_heights,
            &activation_heights,
            &lineage,
            &lineage,
            &BTreeSet::new(),
            0,
        )
        .expect("lane geometry update");
    let new_dir = updated_entry.blocks_dir(&store_root);
    assert!(new_dir.exists(), "expected relabelled directory to exist");
    assert!(
        !old_dir.exists(),
        "expected old directory to be removed after relabel"
    );
    drop(state);
    drop(kura);
}
