state_test! { sync apply_lane_lifecycle_allows_retiring_corrupt_autoscale_managed_lanes_for_repair
    struct RepairCase {
        name: &'static str,
        lane: LaneConfig,
        extra_dataspace: Option<DataSpaceId>,
        autoscale_enabled: bool,
    }
    let mut malformed = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    malformed.alias = "not-elastic-lane-1".to_owned();
    let out_of_range = autoscale_elastic_lane_config(LaneId::new(8), DataSpaceId::UNIVERSAL, 2);
    let off_default_dataspace = DataSpaceId::new(9);
    let off_default = autoscale_elastic_lane_config(LaneId::new(1), off_default_dataspace, 2);
    let disabled_owner = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    let_row! { mut profile_drift = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2) };
    profile_drift.storage = LaneStorageProfile::SplitReplica;
    for case in [
        RepairCase {
            name: "malformed",
            lane: malformed,
            extra_dataspace: None,
            autoscale_enabled: true,
        },
        RepairCase {
            name: "out-of-range",
            lane: out_of_range,
            extra_dataspace: None,
            autoscale_enabled: true,
        },
        RepairCase {
            name: "off-default",
            lane: off_default,
            extra_dataspace: Some(off_default_dataspace),
            autoscale_enabled: true,
        },
        RepairCase {
            name: "disabled-owner",
            lane: disabled_owner,
            extra_dataspace: None,
            autoscale_enabled: false,
        },
        RepairCase {
            name: "profile-drift",
            lane: profile_drift,
            extra_dataspace: None,
            autoscale_enabled: true,
        },
    ] {
        let query_handle = LiveQueryStore::start_test();
        let_row! { mut nexus = iroha_config::parameters::actual::Nexus { enabled: true, ..Default::default() } };
        nexus.autoscale.enabled = case.autoscale_enabled;
        if let Some(dataspace) = case.extra_dataspace {
            nexus.dataspace_catalog = dataspace_catalog_with_extra(dataspace);
        }
        nexus.lane_catalog = LaneCatalog::new(
            nonzero!(10_u32),
            vec![LaneConfig::default(), case.lane.clone()],
        )
        .unwrap_or_else(|err| panic!("corrupted {} catalog: {err}", case.name));
        nexus.lane_config = RuntimeLaneConfig::from_catalog(&nexus.lane_catalog);
        nexus.configured_lane_catalog = nexus.lane_catalog.clone();
        // This fixture intentionally installs a manifest-incompatible catalog so the repair
        // path can retire it. Open Kura at that exact physical geometry, but bypass ordinary
        // pre-genesis manifest admission for the deliberately corrupt catalog.
        let kura = Kura::blank_kura_for_testing_with_lane_config(&nexus.lane_config);
        let state = State::new_for_testing(World::default(), kura, query_handle);
        *state.nexus.write() = nexus;
        state.reseed_static_lane_incarnations_for_tests();
        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: Vec::new(),
                retire: vec![case.lane.id],
            })
            .unwrap_or_else(|err| panic!("{} repair retire failed: {err}", case.name));
        let nexus = state.nexus_snapshot();
        assert_eq!(
            nexus.lane_catalog.lanes(),
            &[LaneConfig::default()],
            "{} repair retire should remove only the corrupt autoscale-owned lane",
            case.name
        );
    }
}
