state_test! { sync apply_lane_lifecycle_internal_autoscale_rejects_malformed_managed_addition
    let_row! { mut bad_managed_value = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2) };
    bad_managed_value
        .metadata
        .insert(AUTOSCALE_META_MANAGED.to_owned(), "TRUE".to_owned());
    let mut bad_alias = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    bad_alias.alias = "elastic".to_owned();
    let mut bad_height = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    bad_height
        .metadata
        .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "0".to_owned());
    let mut restricted = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    restricted.visibility = LaneVisibility::Restricted;
    for (lane, expected_reason) in [
        (
            bad_managed_value,
            "autoscale.managed must be exactly `true`",
        ),
        (bad_alias, "alias must match elastic-lane-{id}"),
        (
            bad_height,
            "autoscale.created_height must be a positive integer",
        ),
        (restricted, "autoscale-managed lanes must be public"),
    ] {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        enable_nexus_autoscale_for_testing(&state);
        let lane_id = lane.id;
        let_row! { plan = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![lane], retire: Vec::new(), } };
        let_row! { err = state .apply_lane_lifecycle_with_options(&plan, false, true) .expect_err("internal autoscale lifecycle must reject malformed managed lanes") };
        assert!(matches!(
            err,
            LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
                if lane == lane_id && reason == expected_reason
        ));
        assert_eq!(state.nexus_snapshot().lane_catalog.lanes().len(), 1);
    }
}
