state_test! { sync apply_lane_lifecycle_allows_repair_retire_of_future_created_autoscale_lane
    let query_handle = LiveQueryStore::start_test();
    let future_created = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 42);
    let_row! { lane_catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), future_created]) .expect("future-created managed catalog") };
    let_row! { mut nexus = iroha_config::parameters::actual::Nexus { enabled: true, lane_catalog, ..Default::default() } };
    nexus.autoscale.enabled = true;
    let state = State::new_with_nexus_for_testing(World::default(), nexus, query_handle);
    let_row! { mut future_pin_intent = test_da_pin_intent( *state.network_id_ref(), LaneId::new(1), 7, 0, StorageTicketId::new([0x65; 32]), ManifestDigest::new([0x75; 32]), ) };
    future_pin_intent.alias = Some("future-created-repair-pin".to_owned());
    let_row! { mut retained_pin_intent = test_da_pin_intent( *state.network_id_ref(), LaneId::SINGLE, 7, 1, StorageTicketId::new([0x66; 32]), ManifestDigest::new([0x76; 32]), ) };
    retained_pin_intent.alias = Some("future-created-retained-pin".to_owned());
    seed_da_pin_intent_world_indexes_for_test(&state, future_pin_intent.clone(), 5, 0);
    seed_da_pin_intent_world_indexes_for_test(&state, retained_pin_intent.clone(), 5, 1);
    let_row! { override_set = LaneRelayEmergencyValidatorSet { peers: vec![PeerId::from(ALICE_ID.expect_single_signatory().clone())], expires_at_height: 10, metadata: Metadata::default(), } };
    {
        let mut wb = state.world.block();
        wb.lane_relay_emergency_validators
            .insert(LaneId::new(1), override_set.clone());
        wb.lane_relay_emergency_validators
            .insert(LaneId::SINGLE, override_set);
        wb.commit();
    }
    let_row! { unrelated = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![LaneConfig { id: LaneId::new(8), alias: "outside-range-before-repair".to_owned(), ..LaneConfig::default() }], retire: Vec::new(), } };
    let_row! { err = state .apply_lane_lifecycle(&unrelated) .expect_err("future-created autoscale lane must block unrelated lifecycle changes") };
    assert!(matches!(
        err,
        LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
            if lane == LaneId::new(1)
                && reason == "autoscale.created_height must not exceed the current block height"
    ));
    {
        let view = state.world.view();
        assert!(
            view.da_pin_intents_by_ticket()
                .get(&future_pin_intent.storage_ticket)
                .is_some(),
            "rejected unrelated lifecycle plan must preserve stale future-lane pin indexes"
        );
        assert!(
            view.lane_relay_emergency_validators()
                .get(&LaneId::new(1))
                .is_some(),
            "rejected unrelated lifecycle plan must preserve stale future-lane emergency overrides"
        );
    }
    let_row! { repair = iroha_data_model::nexus::LaneLifecyclePlan { additions: Vec::new(), retire: vec![LaneId::new(1)], } };
    state
        .apply_lane_lifecycle(&repair)
        .expect("future-created autoscale lane should be explicitly repair-retirable");
    assert_eq!(
        state.nexus_snapshot().lane_catalog.lanes(),
        &[LaneConfig::default()],
        "repair retire must remove the future-created autoscale lane"
    );
    let view = state.world.view();
    assert!(
        view.da_pin_intents_by_ticket()
            .get(&future_pin_intent.storage_ticket)
            .is_none(),
        "repair retire must prune stale future-lane pin intent tickets"
    );
    assert!(
        view.da_pin_intents_by_alias()
            .get("future-created-repair-pin")
            .is_none(),
        "repair retire must prune stale future-lane pin intent aliases"
    );
    assert!(
        view.da_pin_intents_by_manifest()
            .get(&future_pin_intent.manifest_hash)
            .is_none(),
        "repair retire must prune stale future-lane pin intent manifests"
    );
    assert!(
        view.da_pin_intents_by_lane_epoch()
            .get(&(
                future_pin_intent.lane_id,
                future_pin_intent.epoch,
                future_pin_intent.sequence,
            ))
            .is_none(),
        "repair retire must prune stale future-lane pin intent lane-epoch indexes"
    );
    assert!(
        view.da_pin_intents_by_ticket()
            .get(&retained_pin_intent.storage_ticket)
            .is_some(),
        "repair retire must preserve active-lane pin intent tickets"
    );
    assert!(
        view.lane_relay_emergency_validators()
            .get(&LaneId::new(1))
            .is_none(),
        "repair retire must prune stale future-lane emergency overrides"
    );
    assert!(
        view.lane_relay_emergency_validators()
            .get(&LaneId::SINGLE)
            .is_some(),
        "repair retire must preserve active-lane emergency overrides"
    );
}
