state_test! { sync apply_lane_lifecycle_prunes_stale_lane_relay_emergency_overrides
    let state = blank_test_state();
    state.nexus.write().enabled = true;
    let retained = LaneId::SINGLE;
    let added = LaneId::new(1);
    let stale_unknown = LaneId::new(9);
    let_row! { override_set = LaneRelayEmergencyValidatorSet { peers: vec![PeerId::from(ALICE_ID.expect_single_signatory().clone())], expires_at_height: 10, metadata: Metadata::default(), } };
    {
        let mut wb = state.world.block();
        wb.lane_relay_emergency_validators
            .insert(retained, override_set.clone());
        wb.lane_relay_emergency_validators
            .insert(added, override_set.clone());
        wb.lane_relay_emergency_validators
            .insert(stale_unknown, override_set);
        wb.commit();
    }
    state
        .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: added,
                alias: "new-emergency-lane".to_owned(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        })
        .expect("adding an unrelated lane should prune stale emergency overrides");
    let view = state.world.view();
    assert!(
        view.lane_relay_emergency_validators()
            .get(&retained)
            .is_some(),
        "active default-lane emergency override must remain"
    );
    assert!(
        view.lane_relay_emergency_validators().get(&added).is_none(),
        "pre-staged overrides for a newly created lane id must be pruned as stale prior-incarnation state"
    );
    assert!(
        view.lane_relay_emergency_validators()
            .get(&stale_unknown)
            .is_none(),
        "manual lifecycle updates must prune emergency overrides for lanes absent from the updated catalog"
    );
}
state_test! { sync set_nexus_recreation_preserves_lineage_across_snapshot_and_accepts_first_merge
    let_row! { _status_guard = crate::sumeragi::status::nexus_fee_test_lock() .lock() .expect("nexus status test lock") };
    crate::sumeragi::status::reset_nexus_economics_for_tests();
    let (mut state, kura) = blank_test_state_with_kura();
    let_row! { lane_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "beta".to_string(), ..LaneConfig::default() }, ], ) .expect("two-lane catalog") };
    let_row! { two_lane_nexus = iroha_config::parameters::actual::Nexus { enabled: true, lane_catalog: lane_catalog.clone(), ..iroha_config::parameters::actual::Nexus::default() } };
    let recreated_lane_config = RuntimeLaneConfig::from_catalog(&lane_catalog);
    state
        .set_nexus(two_lane_nexus)
        .expect("configure initial two-lane nexus");
    let_row! { historical_lane_incarnation = state .lane_incarnation(LaneId::new(1)) .expect("initial lane has an active incarnation") };
    let historical_lineage = state.lane_incarnation_lineage_snapshot()[&LaneId::new(1)];
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            ..iroha_config::parameters::actual::Nexus::default()
        })
        .expect("retire lane1 before simulating a restart and recreation");
    let retired_snapshot = norito::json::to_value(&state).expect("serialize retired state");
    let_row! { mut restarted = deserialize::KuraSeed { kura: Arc::clone(&kura), query_handle: LiveQueryStore::start_test(), #[cfg(feature = "telemetry")] telemetry: crate::telemetry::StateTelemetry::default(), } .into_state_from_json(retired_snapshot) .expect("restore retired state with retained incarnation lineage") };
    assert_eq!(
        restarted.lane_incarnation_lineage_snapshot()[&LaneId::new(1)],
        historical_lineage,
        "restart must retain the retired lane's latest incarnation lineage"
    );
    seed_stale_da_cursors_for_lane_recreation(&restarted, &recreated_lane_config, LaneId::new(1));
    let stale_status_bonded = Quantity::from(924_u32);
    let retained_status_bonded = Quantity::from(904_u32);
    record_public_lane_staking_status_for_test(LaneId::new(1), &stale_status_bonded);
    record_public_lane_staking_status_for_test(LaneId::SINGLE, &retained_status_bonded);
    restarted
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog,
            ..iroha_config::parameters::actual::Nexus::default()
        })
        .expect("config swap recreates lane1");
    let_row! { recreated_lane_incarnation = restarted .lane_incarnation(LaneId::new(1)) .expect("recreated lane has an active incarnation") };
    assert_ne!(
        recreated_lane_incarnation, historical_lane_incarnation,
        "config recreation must not reuse the historical lane incarnation"
    );
    let recreated_lineage = restarted.lane_incarnation_lineage_snapshot()[&LaneId::new(1)];
    assert_eq!(
        recreated_lineage.generation,
        historical_lineage.generation + 1
    );
    assert_eq!(recreated_lineage.incarnation, recreated_lane_incarnation);
    assert_recreated_lane_da_cursors_accept_fresh_sequence(&restarted, LaneId::new(1));
    assert_public_lane_staking_status_absent(
        LaneId::new(1),
        "set_nexus recreated lane must not inherit old operator staking status",
    );
    assert_public_lane_staking_status_bonded(
        LaneId::SINGLE,
        &retained_status_bonded,
        "set_nexus recreated lane reset must preserve unrelated operator staking status",
    );
    assert_eq!(
        expected_next_merge_lane_height(
            &restarted.merge_admission.read().latest_lane_snapshots,
            LaneId::new(1),
            DataSpaceId::UNIVERSAL,
            recreated_lane_incarnation,
        ),
        Some(1),
        "set_nexus reset must reopen the recreated lane-local height namespace at one"
    );
    let commit_keypairs = configure_commit_topology(&restarted, 4);
    install_lane_manifest_registry_for_keypairs(
        &restarted,
        &[LaneId::SINGLE, LaneId::new(1)],
        &commit_keypairs,
    );
    ensure_merge_carrier_parent_for_test(&restarted);
    let_row! { lane1_h1 = seed_effect_authenticated_relay_for_merge_test( &restarted, sample_lane_relay_envelope_for_state_at_heights_with_view( &restarted, 1, 1, LaneId::new(1), 0, &commit_keypairs, ), ) };
    restarted
        .lane_relays
        .write()
        .insert(lane1_h1.clone())
        .expect("recreated lane relay stored");
    let_row! { candidate = restarted .merge_entry_candidates_from_lane_relays() .into_iter() .next() .expect("recreated lane must produce a merge candidate") };
    assert!(
        candidate.lane_snapshots.iter().any(|snapshot| {
            snapshot.lane_id == LaneId::new(1)
                && snapshot.lane_incarnation == recreated_lane_incarnation
                && snapshot.lane_block_height == lane1_h1.block_height
        }),
        "set_nexus recreation must admit the fresh lane-local height-one relay"
    );
    let merge_qc = merge_qc_for_candidate(&restarted, &candidate, &commit_keypairs, &[0, 1, 2]);
    restarted
        .commit_merge_entry(merge_entry_from_candidate(candidate, merge_qc))
        .expect("first recreated-lane merge entry commits after set_nexus recreation");
    crate::sumeragi::status::reset_nexus_economics_for_tests();
}
fn asset_alias_catalog_retirement_fixture() -> (
    State,
    iroha_config::parameters::actual::Nexus,
    AssetDefinitionId,
    AssetDefinitionAlias,
    Permission,
) {
    let (mut state, asset_definition_id, _) = snapshot_state_with_numeric_asset();
    let removed_dataspace = DataSpaceId::new(7);
    let_row! { initial_nexus = iroha_config::parameters::actual::Nexus { enabled: true, dataspace_catalog: DataSpaceCatalog::new(vec![ DataSpaceMetadata { id: DataSpaceId::UNIVERSAL, alias: "universal".to_owned(), description: None, fault_tolerance: 1, }, DataSpaceMetadata { id: removed_dataspace, alias: "historical".to_owned(), description: None, fault_tolerance: 1, }, ]) .expect("initial dataspace catalog"), ..iroha_config::parameters::actual::Nexus::default() } };
    state
        .set_nexus(initial_nexus)
        .expect("install initial dataspace catalog");
    let alias: AssetDefinitionAlias = "coin#historical".parse().expect("asset alias");
    let_row! { permission = Permission::from( iroha_executor_data_model::permission::asset_definition::CanManageAssetDefinitionAlias { scope: iroha_executor_data_model::permission::asset_definition::AssetDefinitionAliasPermissionScope::Dataspace( removed_dataspace, ), }, ) };
    let mut world = state.world.block();
    world
        .asset_definition_aliases
        .insert(alias.clone(), asset_definition_id.clone());
    world.asset_definition_alias_bindings.insert(
        asset_definition_id.clone(),
        AssetDefinitionAliasBindingRecord {
            alias: alias.clone(),
            lease_expiry_ms: None,
            grace_until_ms: None,
            bound_at_ms: 0,
        },
    );
    world
        .account_permissions
        .insert(ALICE_ID.clone(), BTreeSet::from([permission.clone()]));
    world.commit();
    let_row! { attempted_nexus = iroha_config::parameters::actual::Nexus { enabled: true, dataspace_catalog: DataSpaceCatalog::new(vec![DataSpaceMetadata { id: DataSpaceId::UNIVERSAL, alias: "universal".to_owned(), description: None, fault_tolerance: 1, }]) .expect("retired dataspace catalog"), ..iroha_config::parameters::actual::Nexus::default() } };
    (
        state,
        attempted_nexus,
        asset_definition_id,
        alias,
        permission,
    )
}
state_test! { sync set_nexus_rejects_retiring_bound_asset_alias_namespace_atomically
    let_row! { (mut state, attempted_nexus, asset_definition_id, alias, permission) = asset_alias_catalog_retirement_fixture() };
    let before_nexus = state.nexus_snapshot();
    let before_incarnations = state.lane_incarnations_snapshot();
    let_row! { error = state .set_nexus(attempted_nexus) .expect_err("bound asset alias must block textual namespace retirement") };
    assert!(matches!(
        error,
        LaneLifecycleError::AssetDefinitionAliasNamespaceInUse {
            dataspace_alias,
            asset_definition_id: blocked_definition,
            asset_alias,
        } if dataspace_alias == "historical"
            && blocked_definition == asset_definition_id
            && asset_alias == alias
    ));
    let after_nexus = state.nexus_snapshot();
    assert_eq!(
        after_nexus.dataspace_catalog,
        before_nexus.dataspace_catalog
    );
    assert_eq!(after_nexus.lane_catalog, before_nexus.lane_catalog);
    assert_eq!(after_nexus.routing_policy, before_nexus.routing_policy);
    assert_eq!(state.lane_incarnations_snapshot(), before_incarnations);
    assert_eq!(
        state
            .world
            .asset_definition_alias_bindings
            .view()
            .get(&asset_definition_id)
            .map(|binding| &binding.alias),
        Some(&alias),
        "rejected retirement must preserve the authoritative binding"
    );
    assert!(
        state
            .world
            .account_permissions
            .view()
            .get(&ALICE_ID)
            .is_some_and(|permissions| permissions.contains(&permission)),
        "rejected retirement must not prune the capability before catalog validation succeeds"
    );
}
state_test! { sync set_nexus_retires_asset_alias_namespace_after_binding_is_cleared
    let_row! { (mut state, attempted_nexus, asset_definition_id, alias, permission) = asset_alias_catalog_retirement_fixture() };
    let mut world = state.world.block();
    world
        .asset_definition_alias_bindings
        .remove(asset_definition_id.clone());
    world.asset_definition_aliases.remove(alias.clone());
    world.commit();
    state
        .set_nexus(attempted_nexus)
        .expect("clearing the last asset alias binding permits namespace retirement");
    assert!(
        state
            .nexus_snapshot()
            .dataspace_catalog
            .by_alias("historical")
            .is_none()
    );
    assert!(
        state
            .world
            .asset_definition_alias_bindings
            .view()
            .get(&asset_definition_id)
            .is_none()
    );
    assert!(
        state
            .world
            .account_permissions
            .view()
            .get(&ALICE_ID)
            .is_none_or(|permissions| !permissions.contains(&permission)),
        "successful retirement prunes the now-stale dataspace capability"
    );
}
