    let_row! { err = state .set_tiered_backend(&iroha_config::parameters::actual::TieredState { enabled: true, hot_retained_keys: 1, hot_retained_bytes: iroha_config::parameters::defaults::tiered_state::HOT_RETAINED_BYTES, hot_retained_grace_snapshots: iroha_config::parameters::defaults::tiered_state::HOT_RETAINED_GRACE_SNAPSHOTS, cold_store_root: Some(temp_file.path().to_path_buf()), da_store_root: None, max_snapshots: 1, max_cold_bytes: iroha_config::parameters::defaults::tiered_state::MAX_COLD_BYTES, }) .expect_err("tiered startup geometry must reject a file root") };
