state_test! { sync autonomous_lane_diagnostic_same_identity_drift_is_conflict
    let incarnation = Hash::new(b"autonomous-diagnostic-conflict-incarnation");
    let_row! { (_, session, _) = lane_artifact_block_and_session_for_state_test( None, LaneId::SINGLE, DataSpaceId::UNIVERSAL, incarnation, 1, ) };
    let reservations = autonomous_diagnostic_reservations(&session.proposal);
    let_row! { mut left = AutonomousLaneDiagnosticEvidence::from_proposal_and_reservations( &session.proposal, &reservations, ) .expect("row") };
    left.payload_durable = true;
    left.row.executable_payload_hash = Some(Hash::new(b"first-payload"));
    let mut right = left.clone();
    right.row.executable_payload_hash = Some(Hash::new(b"conflicting-payload"));
    right.row.reservation_group_hash = Hash::new(b"conflicting-reservation-group");
    right.row.reservation_count = right.row.reservation_count.saturating_add(1);
    left.merge(right);
    let row = left.finish();
    assert_eq!(
        row.highest_durable_stage,
        SumeragiAutonomousLaneExecutionStage::Conflict
    );
    assert_eq!(
        row.stuck_reason,
        Some(SumeragiAutonomousLaneExecutionStuckReason::EvidenceConflict)
    );
}
