state_test! { sync lane_lifecycle_same_lane_policy_change_rejects_unapplied_certified_lane_block
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let recreated_lane_id = LaneId::new(1);
    let_row! { lane1_config = LaneConfig { id: recreated_lane_id, alias: "certified-reset".to_string(), visibility: LaneVisibility::Public, ..LaneConfig::default() } };
    let_row! { two_lane_catalog = LaneCatalog::new( nonzero!(2_u32), vec![LaneConfig::default(), lane1_config.clone()], ) .expect("two-lane catalog") };
    let two_lane_config = RuntimeLaneConfig::from_catalog(&two_lane_catalog);
    let initial_lane_config = RuntimeLaneConfig::from_catalog(&LaneCatalog::default());
    let_row! { kura = strict_kura_for_testing( temp_dir.path().join("certified-sidecar-reset-kura"), &initial_lane_config, ) };
    let state = blank_test_state_from_kura(&kura);
    install_existing_nexus_geometry_for_test(
        &state,
        iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: two_lane_catalog.clone(),
            lane_config: two_lane_config.clone(),
            ..Default::default()
        },
    );
    let keypair = crate::state::checked_keypair();
    let_row! { old_block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .sign(keypair.private_key()) .unpack(|_| {}) .into() };
    let old_block_height = old_block.header().height().get();
    kura.store_block(Arc::new(old_block.clone()))
        .expect("store old-incarnation block");
    {
        let mut block_hashes = state.block_hashes.block();
        block_hashes.push(old_block.hash());
        block_hashes.commit_for_tests();
    }
    let_row! { stale_lane_incarnation = state .lane_incarnation(recreated_lane_id) .expect("configured lane must have an active incarnation") };
    let_row! { (stale_session, stale_signer_pops) = sample_committed_lane_block_session_for_state_test( recreated_lane_id, DataSpaceId::UNIVERSAL, stale_lane_incarnation, old_block_height, old_block_height, ) };
    kura.persist_committed_lane_block_session(&stale_session, &stale_signer_pops)
        .expect("persist old-incarnation certified lane block");
    assert_eq!(
        state.unapplied_certified_lane_block_height(recreated_lane_id, DataSpaceId::UNIVERSAL),
        Some(old_block_height),
        "test setup should expose the old certified sidecar before lane reset"
    );
    assert_eq!(
        state
            .unapplied_certified_lane_block_heights_snapshot_cached()
            .get(&(recreated_lane_id, DataSpaceId::UNIVERSAL))
            .copied(),
        Some(old_block_height),
        "test setup should expose the old certified sidecar in proposal readiness snapshots before lane reset"
    );
    assert_eq!(
        state.certified_lane_block_sessions_snapshot_cached(8).len(),
        1,
        "test setup should expose the old certified session before lane reset"
    );
    assert_eq!(
        state
            .certified_lane_block_tips_snapshot_cached()
            .into_iter()
            .map(|(_, _, _, height, _)| height)
            .collect::<Vec<_>>(),
        vec![old_block_height],
        "test setup should expose the old certified tip before lane reset"
    );
    let_row! { policy_lane_config = LaneConfig { visibility: LaneVisibility::Restricted, ..lane1_config } };
    let_row! { policy_catalog = LaneCatalog::new( nonzero!(2_u32), vec![LaneConfig::default(), policy_lane_config.clone()], ) .expect("policy catalog") };
    let policy_config = RuntimeLaneConfig::from_catalog(&policy_catalog);
    assert_eq!(
        two_lane_config.shard_id(recreated_lane_id),
        policy_config.shard_id(recreated_lane_id),
        "test setup should keep the reset lane on the same storage shard"
    );
    let nexus_before = state.nexus_snapshot();
    let incarnations_before = state.lane_incarnations_snapshot();
    let lineage_before = state.lane_incarnation_lineage_snapshot();
    let activation_heights_before = state.lane_incarnation_activation_heights_snapshot();
    let_row! { error = state .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![policy_lane_config], retire: vec![recreated_lane_id], }) .expect_err("lifecycle policy replacement must reject unapplied certified work") };
    let_row! { LaneLifecycleError::Storage(message) = error else { panic!("pending certified work should fail through Kura retirement: {error:?}"); } };
    assert!(message.contains("kura journal"), "{message}");
    assert!(
        message.contains("pending certified work targets a retiring lane incarnation"),
        "{message}"
    );
    let nexus_after = state.nexus_snapshot();
    assert_eq!(nexus_after.lane_catalog, nexus_before.lane_catalog);
    assert_eq!(
        nexus_after.dataspace_catalog,
        nexus_before.dataspace_catalog
    );
    assert_eq!(nexus_after.routing_policy, nexus_before.routing_policy);
    assert_eq!(state.lane_incarnations_snapshot(), incarnations_before);
    assert_eq!(state.lane_incarnation_lineage_snapshot(), lineage_before);
    assert_eq!(
        state.lane_incarnation_activation_heights_snapshot(),
        activation_heights_before
    );
    assert_eq!(
        state
            .da_shard_cursors
            .read()
            .canonical_reset_height_for_lane(recreated_lane_id),
        None,
        "rejected reset must not install an in-memory DA reset watermark"
    );
    let da_cursor_journal_path = state.da_shard_cursor_journal_path();
    if da_cursor_journal_path.exists() {
        let_row! { journal = DaShardCursorJournal::load(&nexus_before.lane_config, &da_cursor_journal_path) .expect("load DA cursor journal after rejected reset") };
        assert_eq!(
            journal.canonical_reset_height_for_lane(recreated_lane_id),
            None,
            "rejected reset must not persist a DA reset watermark"
        );
    }
    assert!(
        kura.read_certified_lane_block_artifact(recreated_lane_id, old_block_height)
            .is_some(),
        "rejected reset must preserve the certified sidecar"
    );
    assert_eq!(
        state.unapplied_certified_lane_block_height(recreated_lane_id, DataSpaceId::UNIVERSAL),
        Some(old_block_height),
        "rejected reset must keep pending work visible to scale-in safety checks"
    );
    assert_eq!(
        state.certified_lane_block_sessions_snapshot_cached(8).len(),
        1,
        "rejected reset must preserve the committed lane session"
    );
    assert_eq!(
        state
            .certified_lane_block_tips_snapshot_cached()
            .into_iter()
            .map(|(_, _, _, height, _)| height)
            .collect::<Vec<_>>(),
        vec![old_block_height],
        "rejected reset must preserve the exact incarnation-bound certified tip"
    );
    assert_eq!(
        state
            .unapplied_certified_lane_block_heights_snapshot_cached()
            .get(&(recreated_lane_id, DataSpaceId::UNIVERSAL))
            .copied(),
        Some(old_block_height),
        "rejected reset must preserve proposal-readiness blocking"
    );
}
state_test! { sync canonical_reset_filters_same_incarnation_certified_lane_block_snapshots
    let lane_id = LaneId::new(1);
    let_row! { lane_config = LaneConfig { id: lane_id, alias: "canonical-reset-filter".to_string(), visibility: LaneVisibility::Public, ..LaneConfig::default() } };
    let_row! { lane_catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane_config]) .expect("two-lane catalog") };
    let runtime_lane_config = RuntimeLaneConfig::from_catalog(&lane_catalog);
    let kura = Kura::blank_kura_for_testing();
    let mut state = blank_test_state_from_kura(&kura);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog,
            lane_config: runtime_lane_config,
            ..Default::default()
        })
        .expect("apply two-lane nexus catalog");
    let_row! { lane_incarnation = state .lane_incarnation(lane_id) .expect("configured lane must have an active incarnation") };
    let reset_height = 1_u64;
    let stale_lane_block_height = 5_u64;
    let_row! { (stale_session, stale_signer_pops) = sample_committed_lane_block_session_for_state_test( lane_id, DataSpaceId::UNIVERSAL, lane_incarnation, reset_height, stale_lane_block_height, ) };
    kura.persist_committed_lane_block_session(&stale_session, &stale_signer_pops)
        .expect("persist same-incarnation pre-reset certified block");
    assert_eq!(
        state
            .certified_lane_block_tips_snapshot_cached()
            .into_iter()
            .map(|(_, _, _, height, _)| height)
            .collect::<Vec<_>>(),
        vec![stale_lane_block_height]
    );
    assert_eq!(
        state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
        Some(stale_lane_block_height)
    );
    assert!(
        !state.has_pending_merge_execution_sources(),
        "a certified height beyond the exact frontier successor must not keep execution readiness asserted"
    );
    state
        .da_shard_cursors
        .write()
        .mark_lanes_canonically_reset(&BTreeSet::from([lane_id]), reset_height);
    assert!(state.certified_lane_block_tips_snapshot_cached().is_empty());
    assert!(
        state
            .certified_lane_block_sessions_snapshot_cached(8)
            .is_empty()
    );
    assert!(
        state
            .unapplied_certified_lane_block_heights_snapshot_cached()
            .is_empty()
    );
    assert_eq!(
        state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
        None
    );
    assert!(!state.has_pending_merge_execution_sources());
    assert!(state.canonical_merge_execution_sources().is_none());
    assert!(
        state
            .build_merge_execution_batch(
                1,
                BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0),
            )
            .is_none()
    );
    let fresh_proposal_height = reset_height + 1;
    let fresh_lane_block_height = 1_u64;
    let_row! { (fresh_session, fresh_signer_pops) = sample_committed_lane_block_session_for_state_test( lane_id, DataSpaceId::UNIVERSAL, lane_incarnation, fresh_proposal_height, fresh_lane_block_height, ) };
    state
        .persist_committed_lane_block_session_lifecycle_bound(&fresh_session, &fresh_signer_pops)
        .expect("persist same-incarnation post-reset certified block");
    assert_eq!(
        state
            .latest_certified_lane_block_frontier_sessions_snapshot_cached()
            .into_iter()
            .map(|session| session.proposal.descriptor.lane_block_height)
            .collect::<Vec<_>>(),
        vec![fresh_lane_block_height],
        "the production frontier must cross the reset watermark to the lower fresh lane height"
    );
    assert_eq!(
        state
            .certified_lane_block_tips_snapshot_cached()
            .into_iter()
            .map(|(_, _, _, height, _)| height)
            .collect::<Vec<_>>(),
        vec![fresh_lane_block_height]
    );
    assert_eq!(
        state
            .certified_lane_block_sessions_snapshot_cached(8)
            .into_iter()
            .map(|session| session.proposal.descriptor.lane_block_height)
            .collect::<Vec<_>>(),
        vec![fresh_lane_block_height]
    );
    assert_eq!(
        state
            .unapplied_certified_lane_block_heights_snapshot_cached()
            .get(&(lane_id, DataSpaceId::UNIVERSAL))
            .copied(),
        Some(fresh_lane_block_height)
    );
    assert_eq!(
        state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
        Some(fresh_lane_block_height)
    );
    assert!(
        !state.has_pending_merge_execution_sources(),
        "a fresh certificate without its independently durable autonomous payload and execution input is not merge-ready"
    );
    assert!(
        state.canonical_merge_execution_sources().is_none(),
        "test-only source collection must require the same complete durable source"
    );
}
#[test]
fn lane_lifecycle_same_lane_policy_change_ignores_stale_direct_application_marker_after_reset() {
    let (mut state, _kura) = blank_test_state_with_kura();
    let reset_lane_id = LaneId::new(1);
    let_row! { lane1_config = LaneConfig { id: reset_lane_id, alias: "direct-marker-reset".to_string(), visibility: LaneVisibility::Public, ..LaneConfig::default() } };
    let_row! { two_lane_catalog = LaneCatalog::new( nonzero!(2_u32), vec![LaneConfig::default(), lane1_config.clone()], ) .expect("two-lane catalog") };
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: two_lane_catalog.clone(),
            ..Default::default()
        })
        .expect("apply initial two-lane nexus catalog");
    let_row! { old_block_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xA7; Hash::LENGTH])) };
    state.push_block_hash_for_testing(old_block_hash);
    let reset_height = 1_u64;
    let_row! { old_incarnation = state .lane_incarnation(reset_lane_id) .expect("reset lane has an old incarnation") };
    let_row! { stale_key = seed_direct_lane_application_marker_for_incarnation( &state, reset_lane_id, old_incarnation, DataSpaceId::UNIVERSAL, reset_height, 0xD3, ) };
    assert_eq!(
        state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
        Some(reset_height),
        "test setup should expose the old direct marker before lane reset"
    );
    let_row! { policy_lane_config = LaneConfig { visibility: LaneVisibility::Restricted, ..lane1_config } };
    state
        .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![policy_lane_config],
            retire: vec![reset_lane_id],
        })
        .expect("same-lane lifecycle policy reset should apply");
    assert_eq!(
        state
            .da_shard_cursors
            .read()
            .canonical_reset_height_for_lane(reset_lane_id),
        Some(reset_height),
        "same-lane policy reset should install the reset watermark"
    );
    assert!(
        state
            .world
            .view()
            .direct_lane_block_application_markers()
            .get(&stale_key)
            .is_none(),
        "same-lane policy reset should prune existing direct markers"
    );
    let_row! { stale_reintroduced_key = seed_direct_lane_application_marker_for_incarnation( &state, reset_lane_id, old_incarnation, DataSpaceId::UNIVERSAL, reset_height, 0xD4, ) };
    assert!(
        state
            .world
            .view()
            .direct_lane_block_application_markers()
            .get(&stale_reintroduced_key)
            .is_some(),
        "test setup should manually reintroduce stale marker evidence after reset"
    );
    assert_eq!(
        state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
        None,
        "stale pre-reset direct marker evidence must not block the fresh lane"
    );
    let_row! { fresh_height = reset_height .checked_add(1) .expect("fresh direct marker height should fit") };
    let_row! { fresh_incarnation = state .lane_incarnation(reset_lane_id) .expect("reset lane has a fresh incarnation") };
    seed_direct_lane_application_marker_for_incarnation(
        &state,
        reset_lane_id,
        fresh_incarnation,
        DataSpaceId::UNIVERSAL,
        fresh_height,
        0xD5,
    );
    assert_eq!(
        state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
        Some(fresh_height),
        "fresh post-reset direct marker evidence must still block unsafe scale-in"
    );
}
