fn seed_consensus_keys_with_pops(state: &State, keypairs: &[KeyPair]) {
    let mut world_block = state.world.block();
    {
        let mut peers = world_block.peers_mut_for_testing().transaction();
        for keypair in keypairs {
            let peer = PeerId::new(keypair.public_key().clone());
            if !peers.iter().any(|existing| existing == &peer) {
                peers.push(peer);
            }
        }
        peers.apply();
    }
    for keypair in keypairs {
        let_row! { pop = iroha_crypto::bls_normal_pop_prove(keypair.private_key()) .expect("generate pop for consensus key") };
        let id = derive_validator_key_id(keypair.public_key());
        let_row! { record = ConsensusKeyRecord { id: id.clone(), public_key: keypair.public_key().clone(), pop: Some(pop), activation_height: 0, expiry_height: None, hsm: None, replaces: None, status: ConsensusKeyStatus::Active, } };
        world_block
            .consensus_keys
            .insert(id.clone(), record.clone());
        let pk = record.public_key.to_string();
        let_row! { mut by_pk = world_block .consensus_keys_by_pk .get(&pk) .cloned() .unwrap_or_default() };
        if !by_pk.contains(&record.id) {
            by_pk.push(record.id.clone());
            world_block.consensus_keys_by_pk.insert(pk, by_pk);
        }
    }
    world_block.commit();
}
fn remove_world_peer_for_test(state: &State, peer: &PeerId) {
    let mut world_block = state.world.block();
    {
        let mut peers = world_block.peers_mut_for_testing().transaction();
        let_row! { retained: Vec<_> = peers .iter() .filter(|existing| *existing != peer) .cloned() .collect() };
        peers.clear();
        peers.extend(retained);
        peers.apply();
    }
    world_block.commit();
}
