fn structural_lane_finality_authority(envelope: &LaneRelayEnvelope) -> LaneFinalityAuthorityV1 {
    LaneFinalityAuthorityV1 {
        version: 1,
        global_block_height: envelope.block_header.height().get(),
        finality_artifact_hash: HashOf::from_untyped_unchecked(Hash::new(
            b"state-test-structural-lane-finality-authority",
        )),
        statement_proof: iroha_crypto::MerkleProof::from_audit_path(0, Vec::new()),
    }
}
fn lane_relay_header_for_state_test(state: &State, height: u64, view: u64) -> BlockHeader {
    let_row! { height_index = usize::try_from(height) .ok() .and_then(NonZeroUsize::new) .expect("relay fixture height fits usize") };
    if let Some(block) = state.kura.get_block(height_index) {
        return block.header();
    }
    let_row! { parent_block_hash = height .checked_sub(1) .and_then(|parent_height| usize::try_from(parent_height).ok()) .and_then(NonZeroUsize::new) .and_then(|parent_height| state.kura.get_block(parent_height)) .map(|block| block.hash()) };
    BlockHeader::new(
        NonZeroU64::new(height).expect("non-zero relay fixture height"),
        parent_block_hash,
        None,
        None,
        1_700_000_000_000,
        view,
    )
}
fn finalize_lane_relay_for_state_test(
    state: &State,
    envelope: &mut LaneRelayEnvelope,
    validator_keypairs: &[KeyPair],
) {
    use iroha_data_model::block::consensus_v2 as wire;
    let height = envelope.block_header.height().get();
    let_row! { height_index = usize::try_from(height) .ok() .and_then(NonZeroUsize::new) .expect("relay fixture height fits usize") };
    let_row! { block = if let Some(block) = state.kura.get_block(height_index) { assert_eq!( block.header(), envelope.block_header, "relay fixture must bind the canonical Kura header" ); block } else { let keypair = checked_keypair(); let block = Arc::new( iroha_data_model::block::builder::BlockBuilder::new(envelope.block_header) .build_with_signature(0, keypair.private_key()), ); state .kura .store_block(Arc::clone(&block)) .expect("store canonical relay finality carrier"); block } };
    let_row! { statement = envelope .lane_finality_statement() .expect("complete relay finality statement") };
    let_row! { statement_tree: MerkleTree<LaneFinalityStatement> = core::iter::once(HashOf::new(&statement)).collect() };
    let_row! { statement_commitment = statement_tree .commitment() .expect("one-leaf relay finality commitment") };
    let_row! { statement_proof = statement_tree .get_proof(0) .expect("one-leaf relay finality proof") };
    let_row! { mut validators = validator_keypairs .iter() .map(|keypair| (PeerId::new(keypair.public_key().clone()), keypair)) .collect::<Vec<_>>() };
    validators.sort_by(|left, right| left.0.cmp(&right.0));
    let_row! { roster = validators .iter() .map(|(validator, _)| wire::ValidatorPower { validator: validator.clone(), power: 1, }) .collect::<Vec<_>>() };
    let_row! { snapshot_bootstrap = (height > 1).then(|| { let parent_height = NonZeroUsize::new(usize::try_from(height - 1).expect("relay parent height fits usize")) .expect("relay parent height is non-zero"); let parent = state .kura .get_block(parent_height) .expect("non-genesis relay finality requires a canonical parent"); wire::SnapshotBootstrapAnchor { snapshot_height: height - 1, snapshot_block_hash: parent.hash(), snapshot_block_creation_time_ms: parent.header().creation_time_ms, snapshot_state_hash: Hash::new(b"state-test-relay-snapshot-state"), } }) };
    let_row! { context = wire::HeightContext { network_id: *state.network_id_ref(), protocol_version: wire::PROTOCOL_VERSION, height, epoch: 0, epoch_end_height: height.saturating_add(100), next_epoch_snapshot: None, mode: wire::ConsensusMode::Permissioned, parent_commit_qc: None, snapshot_bootstrap, quorum: wire::DualQuorum::from_roster(&roster).expect("valid relay finality quorum"), roster, nexus_amx_context_hash: Hash::new(b"state-test-relay-nexus-amx-context"), execution_policy_hash: Hash::new(b"state-test-relay-execution-policy"), da_layout: wire::SumeragiV2GenesisContextParameters::recommended().da_layout, leader_seed: [0x5A; 32], } };
    let_row! { subject = wire::BlockSubject { parent_block_hash: block.header().prev_block_hash(), block_hash: block.hash(), payload_hash: block .canonical_proposal_wire_hash() .expect("encode relay finality proposal"), } };
    let_row! { executed_block_wire_len = u64::try_from( block .canonical_wire() .expect("encode relay finality carrier") .as_framed() .len(), ) .expect("relay finality carrier length fits u64") };
    let_row! { mut execution_commitment = wire::ExecutionCommitment::without_topups_or_merge_carrier( Hash::new([0xBC; 4]), Hash::new([0xAB; 4]), Hash::new(b"state-test-relay-ordinary-writes"), executed_block_wire_len, block .executed_block_wire_hash() .expect("encode relay finality carrier"), ) };
    execution_commitment.lane_finality_manifest = Some(statement_commitment);
    execution_commitment
        .validate()
        .expect("valid relay execution commitment");
    let_row! { round = wire::ConsensusRound { context_id: context.id(), height, view: block.header().view_change_index(), } };
    let_row! { mut commit_qc = wire::QuorumCertificate { round, proposal_round: round, phase: wire::GlobalPhase::Commit, subject, execution_commitment, signers: (0..validators.len()) .map(|index| u32::try_from(index).expect("relay signer index fits u32")) .collect(), aggregate_signature: vec![1], } };
    let_row! { preimage = commit_qc .signer_preimage(&context, 0) .expect("derive relay finality signer preimage") };
    let_row! { signatures = validators .iter() .map(|(_, keypair)| { Signature::try_new(keypair.private_key(), &preimage) .expect("sign relay finality vote") .payload() .to_vec() }) .collect::<Vec<_>>() };
    let signature_refs = signatures.iter().map(Vec::as_slice).collect::<Vec<_>>();
    commit_qc.aggregate_signature = iroha_crypto::bls_normal_aggregate_signatures(&signature_refs)
        .expect("aggregate relay finality votes");
    let_row! { validator_set_pops = validators .iter() .map(|(_, keypair)| { iroha_crypto::bls_normal_pop_prove(keypair.private_key()) .expect("derive relay finality proof of possession") }) .collect() };
    let_row! { artifact = wire::finality::V2FinalityArtifact::new(context, subject, commit_qc, validator_set_pops) };
    artifact
        .verify()
        .expect("relay finality artifact is cryptographically valid");
    if state
        .kura
        .v2_finality_artifact(height)
        .expect("read existing relay finality")
        .is_some()
    {
        state
            .kura
            .overwrite_v2_finality_without_validation_for_tests(height, artifact.clone())
            .expect("replace relay finality fixture");
    } else {
        let_row! { _commit_receipt = state .kura .store_v2_finality_artifact(&artifact) .expect("store relay finality fixture") };
    }
    envelope.finality_authority = Some(LaneFinalityAuthorityV1 {
        version: 1,
        global_block_height: height,
        finality_artifact_hash: HashOf::new(&artifact),
        statement_proof,
    });
}
fn signer_bitmap(signers: &[usize], roster_len: usize) -> Vec<u8> {
    let mut bitmap = vec![0u8; roster_len.div_ceil(8)];
    for signer in signers {
        let byte_idx = signer / 8;
        let bit = signer % 8;
        if let Some(byte) = bitmap.get_mut(byte_idx) {
            *byte |= 1u8 << bit;
        }
    }
    bitmap
}
fn full_signer_bitmap(roster_len: usize) -> Vec<u8> {
    let indices: Vec<usize> = (0..roster_len).collect();
    signer_bitmap(&indices, roster_len)
}
