#[allow(clippy::too_many_arguments)]
fn sample_lane_relay_envelope_for_state_signers(
    state: &State,
    proposal_height: u64,
    lane_block_height: u64,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    view: u64,
    keypairs: &[KeyPair],
    _committee: &[PeerId],
    _signer_indices: &[usize],
) -> LaneRelayEnvelope {
    let header = lane_relay_header_for_state_test(state, proposal_height, view);
    let_row! { settlement = LaneBlockCommitment { block_height: lane_block_height, lane_id, lane_incarnation: state .lane_incarnation_at_height(lane_id, proposal_height) .expect("test lane must have an incarnation at the proposal height"), dataspace_id, tx_count: 1, total_local_amount: "0.000001".parse().expect("valid settlement quantity"), total_xor_due: "0.000001".parse().expect("valid settlement quantity"), total_xor_after_haircut: "0.000001".parse().expect("valid settlement quantity"), total_xor_variance: "0".parse().expect("valid settlement quantity"), swap_metadata: None, receipts: vec![LaneSettlementReceipt { source_id: [0xAA; 32], local_amount: "0.000001".parse().expect("valid settlement quantity"), xor_due: "0.000001".parse().expect("valid settlement quantity"), xor_after_haircut: "0.000001".parse().expect("valid settlement quantity"), xor_variance: "0".parse().expect("valid settlement quantity"), timestamp_ms: 1_700_000_000_000, }], nexus_fee_receipts: Vec::new(), native_amx_receipts: Vec::new(), } };
    let da_commitment_hash = header.da_commitments_hash();
    let_row! { mut envelope = LaneRelayEnvelope::new(header, da_commitment_hash, settlement, 0) .expect("valid envelope") .with_lane_block_descriptor_hash(Some(Hash::new( format!( "state-test-lane-descriptor:{}:{}:{proposal_height}:{lane_block_height}:{view}", dataspace_id.as_u64(), lane_id.as_u32() ) .as_bytes(), ))) .with_manifest_root(Some([0x44; 32])) };
    let fastpq_proof = sample_fastpq_proof_material(&envelope, view);
    envelope.fastpq_proof = Some(fastpq_proof);
    let_row! { next_global_height = u64::try_from(state.committed_height()) .unwrap_or(u64::MAX) .saturating_add(1) };
    if proposal_height <= next_global_height {
        finalize_lane_relay_for_state_test(state, &mut envelope, keypairs);
    } else {
        envelope.finality_authority = Some(structural_lane_finality_authority(&envelope));
    }
    envelope
}
