fn sample_fastpq_proof_material(
    envelope: &LaneRelayEnvelope,
    view: u64,
) -> LaneFastpqProofMaterial {
    let verified_at_height = envelope.block_header.height().get().saturating_add(view);
    LaneFastpqProofMaterial {
        proof_digest: Hash::new(
            format!(
                "state-test-fastpq-proof:{}:{}:{}:{verified_at_height}",
                envelope.dataspace_id.as_u64(),
                envelope.lane_id.as_u32(),
                envelope.block_height
            )
            .as_bytes(),
        ),
        verified_at_height,
    }
}
fn sample_verified_lane_relay_binding(dsid: DataSpaceId) -> AxtFastpqBinding {
    let claim_digest = Hash::new(b"state-test-lane-relay-claim");
    AxtFastpqBinding {
        parameter: fastpq_prover::AXT_DEFAULT_PARAMETER.to_owned(),
        source_dsid: dsid.as_u64(),
        source_dataspace: format!("state-test-dataspace-{}", dsid.as_u64()),
        source_receipt_id: "state-test-lane-relay-receipt".to_owned(),
        source_tx_commitment: hex::encode(Hash::new(b"state-test-lane-relay-source").as_ref()),
        claim_type: "authorization".to_owned(),
        claim_digest: hex::encode(claim_digest.as_ref()),
        witness_commitment: hex::encode(Hash::new(b"state-test-lane-relay-witness").as_ref()),
        policy_commitment: hex::encode(Hash::new(b"state-test-lane-relay-policy").as_ref()),
        verified_effect_type: LANE_RELAY_FASTPQ_EFFECT_TYPE.to_owned(),
        corridor: "state-test-lane-relay".to_owned(),
        verifier_id: "fastpq".to_owned(),
        verifier_version: "v1".to_owned(),
        target_dsids: vec![dsid.as_u64()],
        effect_binding: None,
    }
}
fn sample_verified_lane_relay_record(envelope: &LaneRelayEnvelope) -> VerifiedLaneRelayRecord {
    let_row! { material = envelope .fastpq_proof .expect("sample envelope must carry FastPQ proof material") };
    let_row! { manifest_root = envelope .manifest_root .expect("verified lane relay samples must carry a manifest root") };
    let mut fastpq_binding = sample_verified_lane_relay_binding(envelope.dataspace_id);
    let claim_digest = lane_relay_fastpq_claim_digest(envelope).expect("lane relay claim digest");
    fastpq_binding.claim_digest = hex::encode(claim_digest.as_ref());
    let_row! { lane_finality_statement_hash = envelope .lane_finality_statement_hash() .expect("sample verified relay must have a finality statement") };
    let fastpq_old_root = Hash::new([0xBC; 4]).into();
    let fastpq_new_root = Hash::new([0xAB; 4]).into();
    VerifiedLaneRelayRecord::new(
        envelope.clone(),
        material.proof_digest,
        Hash::new(b"state-test-lane-relay-statement").into(),
        lane_finality_statement_hash,
        fastpq_old_root,
        fastpq_new_root,
        lane_finality_statement_hash.into(),
        Hash::new(b"state-test-lane-relay-inner-proof"),
        material.verified_at_height,
        manifest_root,
        fastpq_binding,
    )
}
fn prove_finalized_lane_relay_for_registration(
    mut envelope: LaneRelayEnvelope,
) -> (LaneRelayEnvelope, ProofBlob) {
    let manifest_root = envelope.manifest_root.expect("relay manifest root");
    let_row! { finality_statement_hash = envelope .lane_finality_statement_hash() .expect("complete lane finality statement") };
    let_row! { claim_digest = lane_relay_fastpq_claim_digest(&envelope).expect("lane relay FastPQ claim digest") };
    let relay_ref = envelope.relay_ref();
    let relay_ref_bytes = norito::to_bytes(&relay_ref).expect("encode lane relay reference");
    let source_tx_commitment = Hash::new(&relay_ref_bytes);
    let_row! { binding = AxtFastpqBinding { parameter: fastpq_prover::AXT_DEFAULT_PARAMETER.to_owned(), source_dsid: envelope.dataspace_id.as_u64(), source_dataspace: format!("dataspace-{}", envelope.dataspace_id.as_u64()), source_receipt_id: format!("relay-{}", hex::encode(&relay_ref_bytes)), source_tx_commitment: hex::encode(source_tx_commitment.as_ref()), claim_type: "authorization".to_owned(), claim_digest: hex::encode(claim_digest.as_ref()), witness_commitment: hex::encode(Hash::new(envelope.settlement_hash.as_ref()).as_ref()), policy_commitment: hex::encode(Hash::new(manifest_root).as_ref()), verified_effect_type: LANE_RELAY_FASTPQ_EFFECT_TYPE.to_owned(), corridor: "state-test-lane-relay".to_owned(), verifier_id: "fastpq".to_owned(), verifier_version: "v1".to_owned(), target_dsids: vec![DataSpaceId::UNIVERSAL.as_u64()], effect_binding: None, } };
    let mut dsid = [0_u8; 16];
    dsid[..8].copy_from_slice(&envelope.dataspace_id.as_u64().to_le_bytes());
    let_row! { mut batch = fastpq_prover::TransitionBatch::new( fastpq_prover::AXT_DEFAULT_PARAMETER, fastpq_prover::PublicInputs { dsid, slot: envelope.block_header.height().get(), old_root: Hash::new([0xBC; 4]).into(), new_root: Hash::new([0xAB; 4]).into(), perm_root: Hash::new(manifest_root).into(), tx_set_hash: finality_statement_hash.into(), }, ) };
    batch.push(fastpq_prover::StateTransition::new(
        b"axt/state-test/lane-relay".to_vec(),
        relay_ref_bytes,
        claim_digest.as_ref().to_vec(),
        fastpq_prover::OperationKind::MetaSet,
    ));
    batch.sort();
    batch.metadata.insert(
        "entry_hash".to_owned(),
        source_tx_commitment.as_ref().to_vec(),
    );
    fastpq_prover::bind_axt_batch(&mut batch, &binding).expect("bind lane relay AXT batch");
    let_row! { proof = fastpq_prover::Prover::canonical_with_modes( fastpq_prover::AXT_DEFAULT_PARAMETER, fastpq_prover::ExecutionMode::Cpu, fastpq_prover::PoseidonExecutionMode::Cpu, ) .expect("construct lane relay FastPQ prover") .prove(&batch) .expect("prove lane relay statement") };
    let_row! { proof_payload = fastpq_prover::encode_axt_fastpq_payload(&batch, proof) .expect("encode lane relay FastPQ payload") };
    let_row! { proof_envelope = AxtProofEnvelope { dsid: envelope.dataspace_id, manifest_root, da_commitment: envelope .da_commitment_hash .map(|commitment| Hash::from(commitment).into()), proof: proof_payload, fastpq_binding: Some(binding), committed_amount: None, amount_commitment: None, } };
    let_row! { proof_blob = ProofBlob { payload: norito::to_bytes(&proof_envelope).expect("encode lane relay proof envelope"), expiry_slot: Some(envelope.block_header.height().get().saturating_add(10)), } };
    envelope.fastpq_proof = Some(LaneFastpqProofMaterial {
        proof_digest: Hash::new(&proof_blob.payload),
        verified_at_height: envelope.block_header.height().get(),
    });
    (envelope, proof_blob)
}
