state_test! { sync merge_candidates_restart_hydrates_only_active_verified_lane_relay_records
    let (mut state, validator_keypairs) = setup_lane_relay_burn_state();
    let_row! { validator_ids: Vec<_> = validator_keypairs .iter() .map(|keypair| AccountId::new(keypair.public_key().clone())) .collect() };
    let signers: Vec<&KeyPair> = validator_keypairs.iter().collect();
    let signers_bitmap = full_signer_bitmap(validator_keypairs.len());
    let future_created_lane = LaneId::new(1);
    install_autoscale_elastic_catalog_for_test(
        &state,
        autoscale_elastic_catalog_lane_for_test(future_created_lane, 7),
    );
    state.push_block_hash_for_testing(HashOf::from_untyped_unchecked(Hash::new(
        b"verified-lane-relay-restart-parent",
    )));
    let_row! { active_envelope = sample_lane_relay_envelope_for_state(&state, 1, LaneId::SINGLE, &validator_keypairs) .with_manifest_root(Some([0x44; 32])) };
    let_row! { stale_unknown_envelope = sample_lane_relay_envelope(2, LaneId::new(7), &signers, signers_bitmap) .with_manifest_root(Some([0x77; 32])) };
    let_row! { future_created_envelope = sample_lane_relay_envelope( 2, future_created_lane, &signers, full_signer_bitmap(validator_keypairs.len()), ) .with_manifest_root(Some([0x88; 32])) };
    let active_record = sample_verified_lane_relay_record(&active_envelope);
    let stale_unknown_record = sample_verified_lane_relay_record(&stale_unknown_envelope);
    let future_created_record = sample_verified_lane_relay_record(&future_created_envelope);
    let mut snapshot_nexus = state.nexus_snapshot();
    snapshot_nexus.autoscale.enabled = false;
    snapshot_nexus.lane_catalog = LaneCatalog::default();
    snapshot_nexus.lane_config = RuntimeLaneConfig::default();
    install_existing_nexus_geometry_for_test(&state, snapshot_nexus);
    let_row! { active_key = State::verified_lane_relay_state_key(&active_envelope).expect("active state key") };
    let_row! { stale_unknown_key = State::verified_lane_relay_state_key(&stale_unknown_envelope) .expect("stale unknown state key") };
    let_row! { future_created_key = State::verified_lane_relay_state_key(&future_created_envelope) .expect("future-created state key") };
    insert_verified_lane_relay_record_state(&state, active_key.clone(), &active_record);
    insert_verified_lane_relay_record_state(
        &state,
        stale_unknown_key.clone(),
        &stale_unknown_record,
    );
    insert_verified_lane_relay_record_state(
        &state,
        future_created_key.clone(),
        &future_created_record,
    );
    assert_eq!(
        state
            .verified_lane_relay_records_from_contract_state()
            .len(),
        3,
        "test setup must persist all relay records before restart"
    );
    assert!(
        state.lane_relay_snapshot().is_empty(),
        "contract-state persistence alone must not populate the runtime relay cache"
    );
    let json_value = norito::json::to_value(&state).expect("serialize state snapshot");
    let_row! { restarted = deserialize::KuraSeed { kura: Kura::blank_kura_for_testing(), query_handle: LiveQueryStore::start_test(), #[cfg(feature = "telemetry")] telemetry: crate::telemetry::StateTelemetry::default(), } .into_state_from_json(json_value) .expect("deserialize restarted state") };
    {
        let mut nexus = restarted.nexus.write();
        nexus.enabled = true;
        nexus.fees.settlement_mode =
            iroha_config::parameters::actual::NexusFeeSettlementMode::LaneRelayBurn;
    }
    install_autoscale_elastic_catalog_for_test(
        &restarted,
        autoscale_elastic_catalog_lane_for_test(future_created_lane, 7),
    );
    install_lane_manifest_registry(
        &restarted,
        &[(LaneId::SINGLE, DataSpaceId::UNIVERSAL, validator_ids)],
    );
    assert_eq!(
        restarted
            .verified_lane_relay_records_from_contract_state()
            .len(),
        3,
        "restart should recover all persisted canonical relay records before hydration filters apply"
    );
    assert!(restarted.lane_relay_snapshot().is_empty());
    let candidates = restarted.merge_entry_candidates_from_lane_relays();
    assert_eq!(
        restarted.lane_relay_snapshot(),
        vec![active_envelope.clone()],
        "restart hydration must admit only relays for active Nexus catalog lanes"
    );
    assert_eq!(candidates.len(), 1);
    let_row! { snapshot = candidates[0] .lane_snapshots .iter() .find(|snapshot| snapshot.lane_id == LaneId::SINGLE) .expect("active lane snapshot") };
    assert_eq!(snapshot.dataspace_id, DataSpaceId::UNIVERSAL);
    assert_eq!(snapshot.lane_block_height, active_envelope.block_height);
    assert_eq!(snapshot.tip_hash, active_envelope.block_header.hash());
    let contract_state = restarted.world.smart_contract_state.view();
    assert!(
        contract_state.get(&active_key).is_some(),
        "active relay record should remain persisted after restart hydration"
    );
    assert!(
        contract_state.get(&stale_unknown_key).is_some(),
        "unknown-lane relay state should remain persisted but inert after restart hydration"
    );
    assert!(
        contract_state.get(&future_created_key).is_some(),
        "future-created relay state should remain persisted but inert after restart hydration"
    );
}
#[test]
fn merge_candidates_restart_rejects_replayed_verified_relay_from_old_lane_incarnation() {
    let (state, validator_keypairs) = setup_lane_relay_burn_state();
    let_row! { validator_ids: Vec<_> = validator_keypairs .iter() .map(|keypair| AccountId::new(keypair.public_key().clone())) .collect() };
    let lane_id = LaneId::new(1);
    let_row! { lane_config = LaneConfig { id: lane_id, alias: "replayed-verified-relay".to_owned(), ..LaneConfig::default() } };
    let_row! { add_lane = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![lane_config.clone()], retire: Vec::new(), } };
    state.apply_lane_lifecycle(&add_lane).expect("add lane");
    install_lane_manifest_registry(
        &state,
        &[
            (
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                validator_ids.clone(),
            ),
            (lane_id, DataSpaceId::UNIVERSAL, validator_ids.clone()),
        ],
    );
    let_row! { mut old_envelope = sample_lane_relay_envelope_for_state(&state, 1, lane_id, &validator_keypairs) .with_manifest_root(Some([0x51; 32])) };
    resign_lane_relay_for_state_test(&state, &mut old_envelope, &validator_keypairs);
    let old_record = sample_verified_lane_relay_record(&old_envelope);
    let old_key = State::verified_lane_relay_state_key(&old_envelope).expect("old state key");
    let_row! { old_map_key = State::verified_lane_relay_contract_map_state_key(&old_key) .expect("old contract map state key") };
    seed_committed_height_for_state_test(&state, 1);
    insert_verified_lane_relay_record_state(&state, old_key.clone(), &old_record);
    assert!(
        !state.merge_entry_candidates_from_lane_relays().is_empty(),
        "test setup should prove the old verified relay can hydrate before lane reset"
    );
    seed_committed_height_for_state_test(&state, 2);
    state
        .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
            additions: Vec::new(),
            retire: vec![lane_id],
        })
        .expect("retire lane");
    state
        .apply_lane_lifecycle(&add_lane)
        .expect("recreate lane");
    let_row! { recreated_incarnation = state .lane_incarnation(lane_id) .expect("recreated lane has an active incarnation") };
    assert_ne!(recreated_incarnation, old_envelope.lane_incarnation);
    insert_verified_lane_relay_record_state(&state, old_key.clone(), &old_record);
    insert_smart_contract_state_payload(
        &state,
        old_map_key.clone(),
        encode_verified_lane_relay_record_contract_map_state_for_test(&old_record),
    );
    assert_eq!(
        state.verified_lane_relay_records_from_contract_state(),
        vec![old_record.clone()],
        "adversarial replay should restore the old canonical record to contract state"
    );
    let_row! { stale_error = state .record_lane_relay(&old_envelope) .expect_err("old-incarnation relay should fail incarnation validation") };
    assert!(matches!(
        stale_error,
        LaneRelayError::LaneIncarnationMismatch {
            lane,
            expected,
            actual,
        } if lane == lane_id
            && expected == recreated_incarnation
            && actual == old_envelope.lane_incarnation
    ));
    assert!(
        state.merge_entry_candidates_from_lane_relays().is_empty(),
        "old-incarnation verified relay must not hydrate after lane reset"
    );
    assert!(state.lane_relay_snapshot().is_empty());
    assert!(
        state
            .verified_lane_relay_records_from_contract_state()
            .is_empty(),
        "stale replay should be pruned after failed hydration"
    );
    {
        let contract_state = state.world.smart_contract_state.view();
        assert!(
            contract_state.get(&old_key).is_none(),
            "stale canonical replay key should be pruned after failed hydration"
        );
        assert!(
            contract_state.get(&old_map_key).is_none(),
            "stale contract-map replay key should be pruned after failed hydration"
        );
    }
    seed_autoscale_sample_history_for_snapshot_test(&state);
    let json_value = norito::json::to_value(&state).expect("serialize state snapshot");
    let_row! { restarted = deserialize::KuraSeed { kura: Kura::blank_kura_for_testing(), query_handle: LiveQueryStore::start_test(), #[cfg(feature = "telemetry")] telemetry: crate::telemetry::StateTelemetry::default(), } .into_state_from_json(json_value) .expect("deserialize restarted state") };
    {
        let mut nexus = restarted.nexus.write();
        nexus.enabled = true;
        nexus.fees.settlement_mode =
            iroha_config::parameters::actual::NexusFeeSettlementMode::LaneRelayBurn;
    }
    if nexus_catalog_geometry_lane_dataspace(lane_id, &restarted.nexus_snapshot()).is_none() {
        restarted
            .apply_lane_lifecycle(&add_lane)
            .expect("restore recreated lane");
    }
    install_lane_manifest_registry(
        &restarted,
        &[
            (
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                validator_ids.clone(),
            ),
            (lane_id, DataSpaceId::UNIVERSAL, validator_ids),
        ],
    );
    insert_verified_lane_relay_record_state(&restarted, old_key.clone(), &old_record);
    insert_smart_contract_state_payload(
        &restarted,
        old_map_key.clone(),
        encode_verified_lane_relay_record_contract_map_state_for_test(&old_record),
    );
    assert_eq!(
        restarted.verified_lane_relay_records_from_contract_state(),
        vec![old_record.clone()],
        "adversarial replay after restart should restore the old canonical record to contract state"
    );
    let_row! { restarted_incarnation = restarted .lane_incarnation(lane_id) .expect("restarted recreated lane has an active incarnation") };
    assert_eq!(restarted_incarnation, recreated_incarnation);
    let_row! { restarted_stale_error = restarted .record_lane_relay(&old_envelope) .expect_err("old-incarnation relay should remain stale after restart") };
    assert!(matches!(
        restarted_stale_error,
        LaneRelayError::LaneIncarnationMismatch {
            lane,
            expected,
            actual,
        } if lane == lane_id
            && expected == restarted_incarnation
            && actual == old_envelope.lane_incarnation
    ));
    assert!(
        restarted
            .merge_entry_candidates_from_lane_relays()
            .is_empty(),
        "restart hydration must keep old-incarnation verified relays inert"
    );
    assert!(restarted.lane_relay_snapshot().is_empty());
    assert!(
        restarted
            .verified_lane_relay_records_from_contract_state()
            .is_empty(),
        "restart stale replay should be pruned after failed hydration"
    );
    {
        let contract_state = restarted.world.smart_contract_state.view();
        assert!(
            contract_state.get(&old_key).is_none(),
            "restart stale canonical replay key should be pruned after failed hydration"
        );
        assert!(
            contract_state.get(&old_map_key).is_none(),
            "restart stale contract-map replay key should be pruned after failed hydration"
        );
    }
    seed_committed_height_for_state_test(&restarted, 3);
    let_row! { mut fresh_envelope = sample_lane_relay_envelope_for_state_at_heights_with_view( &restarted, 3, 1, lane_id, 0, &validator_keypairs, ) .with_manifest_root(Some([0x52; 32])) };
    resign_lane_relay_for_state_test(&restarted, &mut fresh_envelope, &validator_keypairs);
    let fresh_record = sample_verified_lane_relay_record(&fresh_envelope);
    insert_verified_lane_relay_record_state(
        &restarted,
        State::verified_lane_relay_state_key(&fresh_envelope).expect("fresh state key"),
        &fresh_record,
    );
    let candidates = restarted.merge_entry_candidates_from_lane_relays();
    assert_eq!(
        restarted.lane_relay_snapshot(),
        vec![fresh_envelope.clone()],
        "only the post-reset verified relay should hydrate"
    );
    assert_eq!(candidates.len(), 1);
    assert!(
        candidates[0].lane_snapshots.iter().any(|snapshot| {
            snapshot.lane_id == lane_id && snapshot.lane_block_height == fresh_envelope.block_height
        }),
        "fresh post-reset relay must still produce a merge candidate"
    );
}
