state_test! { sync lane_relay_committee_seed_is_deterministic
    let state = blank_test_state();
    let seed = state.lane_relay_committee_seed(DataSpaceId::UNIVERSAL, LaneId::new(0), 1);
    let same = state.lane_relay_committee_seed(DataSpaceId::UNIVERSAL, LaneId::new(0), 1);
    assert_eq!(seed, same);
    let different_lane = state.lane_relay_committee_seed(DataSpaceId::UNIVERSAL, LaneId::new(1), 1);
    assert_ne!(seed, different_lane);
    let different_ds = state.lane_relay_committee_seed(DataSpaceId::new(1), LaneId::new(0), 1);
    assert_ne!(seed, different_ds);
}
state_test! { sync lane_relay_committee_from_pool_is_deterministic
    let_row! { members = (1_u8..=8) .map(|seed| { PeerId::new( KeyPair::try_from_seed(vec![seed; 32], Algorithm::BlsNormal) .expect("derive deterministic relay committee member") .public_key() .clone(), ) }) .collect::<Vec<_>>() };
    let mut pool = members.iter().rev().cloned().collect::<Vec<_>>();
    pool.push(members[0].clone());
    let seed = [0x11; 32];
    let_row! { committee = State::lane_relay_committee_from_pool(&pool, members.len(), seed).expect("committee") };
    let_row! { again = State::lane_relay_committee_from_pool(&pool, members.len(), seed).expect("committee") };
    assert_eq!(committee, again);
    let_row! { alternate_flags = norito::core::default_encode_flags() ^ norito::core::header_flags::COMPACT_LEN };
    let_row! { under_alternate_layout = { let _ambient = norito::core::DecodeFlagsGuard::enter(alternate_flags); State::lane_relay_committee_from_pool(&pool, members.len(), seed) .expect("ambient layout cannot change a consensus committee") } };
    assert_eq!(committee, under_alternate_layout);
    assert_eq!(committee.len(), members.len());
    let mut unique = committee.clone();
    unique.sort();
    unique.dedup();
    assert_eq!(unique.len(), committee.len());
    for member in committee {
        assert!(pool.iter().any(|candidate| candidate == &member));
    }
}
