state_test! { sync authoritative_lane_peers_for_stake_elected_lane_require_present_live_peer
    let state = blank_test_state();
    state.nexus.write().enabled = true;
    let live_keypair = crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal);
    let removed_keypair = crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal);
    let disabled_keypair = crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal);
    seed_consensus_keys_with_pops(&state, &[live_keypair.clone(), removed_keypair.clone()]);
    seed_consensus_key_with_lifecycle_for_test(
        &state,
        &disabled_keypair,
        ConsensusKeyStatus::Disabled,
        0,
        None,
    );
    let live_validator = AccountId::new(live_keypair.public_key().clone());
    let removed_validator = AccountId::new(removed_keypair.public_key().clone());
    let disabled_validator = AccountId::new(disabled_keypair.public_key().clone());
    {
        let mut world_block = state.world.block();
        for (validator, keypair, total_stake) in [
            (&live_validator, &live_keypair, 1_000_u64),
            (&removed_validator, &removed_keypair, 9_000_u64),
            (&disabled_validator, &disabled_keypair, 8_000_u64),
        ] {
            world_block.public_lane_validators.insert(
                (LaneId::SINGLE, validator.clone()),
                PublicLaneValidatorRecord {
                    lane_id: LaneId::SINGLE,
                    validator: validator.clone(),
                    peer_id: PeerId::new(keypair.public_key().clone()),
                    stake_account: validator.clone(),
                    total_stake: iroha_primitives::numeric::Quantity::from(total_stake),
                    self_stake: iroha_primitives::numeric::Quantity::from(total_stake),
                    metadata: Metadata::default(),
                    status: PublicLaneValidatorStatus::Active,
                    activation_epoch: None,
                    activation_height: None,
                    last_reward_epoch: None,
                },
            );
        }
        world_block.commit();
    }
    let removed_peer = PeerId::new(removed_keypair.public_key().clone());
    remove_world_peer_for_test(&state, &removed_peer);
    assert_eq!(
        state.authoritative_lane_peer_ids(LaneId::SINGLE),
        vec![PeerId::new(live_keypair.public_key().clone())],
        "stake-elected lane authority must ignore removed peers and non-live consensus keys even when their stale stake rows are heavier"
    );
    assert_eq!(
        state.authoritative_lane_validator_accounts(LaneId::SINGLE),
        vec![live_validator],
        "stake-elected validator accounts must follow the same present-live peer boundary"
    );
}
fn autoscale_elastic_catalog_lane_for_test(
    lane_id: LaneId,
    created_height: u64,
) -> iroha_data_model::nexus::LaneConfig {
    let_row! { mut lane = iroha_data_model::nexus::LaneConfig { id: lane_id, alias: format!("elastic-lane-{}", lane_id.as_u32()), visibility: iroha_data_model::nexus::LaneVisibility::Public, ..Default::default() } };
    lane.metadata.insert(
        iroha_data_model::nexus::AUTOSCALE_META_MANAGED.to_owned(),
        "true".to_owned(),
    );
    lane.metadata.insert(
        iroha_data_model::nexus::AUTOSCALE_META_CREATED_HEIGHT.to_owned(),
        created_height.to_string(),
    );
    attach_synthetic_autoscale_committee_for_test(&mut lane);
    lane
}
fn autoscale_elastic_catalog_lane_with_committee_for_test(
    lane_id: LaneId,
    created_height: u64,
    keypairs: &[KeyPair],
) -> iroha_data_model::nexus::LaneConfig {
    let mut lane = autoscale_elastic_catalog_lane_for_test(lane_id, created_height);
    let mut members = keypairs.to_vec();
    members.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    let_row! { validator_set = members .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let_row! { validator_pops = members .iter() .map(|keypair| { iroha_crypto::bls_normal_pop_prove(keypair.private_key()) .expect("test autoscale committee PoP") }) .collect::<Vec<_>>() };
    let_row! { committee = autoscale_lane_committee_from_validator_set(validator_set, validator_pops) .expect("test autoscale committee") };
    lane.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        encode_autoscale_lane_committee(&committee).expect("test committee encoding"),
    );
    lane
}
fn install_autoscale_elastic_catalog_for_test(
    state: &State,
    lane: iroha_data_model::nexus::LaneConfig,
) {
    install_autoscale_elastic_lanes_for_test(state, vec![lane]);
}
fn install_autoscale_elastic_lanes_for_test(
    state: &State,
    lanes: Vec<iroha_data_model::nexus::LaneConfig>,
) {
    let_row! { lane_count = lanes .iter() .map(|lane| lane.id.as_u32()) .max() .unwrap_or(0) .saturating_add(1) };
    let mut catalog_lanes = Vec::with_capacity(lanes.len().saturating_add(1));
    catalog_lanes.push(iroha_data_model::nexus::LaneConfig::default());
    catalog_lanes.extend(lanes);
    let_row! { lane_catalog = LaneCatalog::new( core::num::NonZeroU32::new(lane_count).expect("nonzero lane count"), catalog_lanes, ) .expect("autoscale lane catalog") };
    let mut nexus = state.nexus_snapshot();
    nexus.enabled = true;
    nexus.autoscale.enabled = true;
    nexus.autoscale.min_lanes = nonzero!(1_u32);
    nexus.autoscale.max_lanes =
        core::num::NonZeroU32::new(lane_count).expect("nonzero autoscale lane bound");
    nexus.lane_catalog = lane_catalog;
    nexus.lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
    install_existing_nexus_geometry_for_test(state, nexus);
}
fn seed_latest_lane_authority_height_for_test(state: &State, height: u64) {
    let height = NonZeroU64::new(height).expect("test authority height must be nonzero");
    let header = BlockHeader::new(height, None, None, None, 0, 0);
    state.update_latest_block_header_cache_for_tests(header);
}
state_test! { sync lane_active_for_authority_respects_future_created_autoscale_height
    let state = blank_test_state();
    let lane_id = LaneId::new(1);
    install_autoscale_elastic_catalog_for_test(
        &state,
        autoscale_elastic_catalog_lane_for_test(lane_id, 7),
    );
    seed_latest_lane_authority_height_for_test(&state, 6);
    assert!(!state.is_lane_active_for_authority(lane_id));
    assert!(state.is_lane_active_for_authority(LaneId::SINGLE));
    seed_latest_lane_authority_height_for_test(&state, 7);
    assert!(state.is_lane_active_for_authority(lane_id));
}
