state_test! { sync record_lane_relay_builds_merge_candidate_for_single_lane
    let (state, _validator_ids, validator_keypairs) = lane_relay_manifest_test_state();
    let keypairs = configure_commit_topology_preserving_world_peers(&state, 1);
    ensure_merge_carrier_parent_for_test(&state);
    let_row! { envelope = seed_effect_authenticated_relay_for_merge_test( &state, sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(0), &validator_keypairs), ) };
    state.record_lane_relay(&envelope).expect("relay accepted");
    let candidates = state.merge_entry_candidates_from_lane_relays();
    assert_eq!(candidates.len(), 1);
    let_row! { candidate = candidates .first() .expect("merge candidate computed from relay") };
    let lane_tips = candidate.lane_tips();
    let merge_hint_roots = candidate.merge_hint_roots();
    assert_eq!(candidate.epoch_id, 1);
    assert_eq!(lane_tips.as_slice(), &[envelope.block_header.hash()]);
    assert_eq!(
        merge_hint_roots.as_slice(),
        &[envelope.merge_hint_root().expect("merge hint root")]
    );
    assert_eq!(
        candidate.global_state_root,
        crate::merge::reduce_merge_hint_roots(&merge_hint_roots)
    );
    let qc = merge_qc_for_candidate(&state, candidate, &keypairs, &[0]);
    let entry = merge_entry_from_candidate(candidate.clone(), qc);
    let_row! { committed = state .commit_merge_entry(entry) .expect("merge entry commit succeeds") };
    assert_eq!(committed.epoch_id, 1);
}
state_test! { sync record_lane_relay_builds_merge_candidate_from_active_lanes
    let mut state = blank_test_state();
    let (validator_ids, validator_keypairs) = bls_accounts_in("validators", 4);
    seed_consensus_keys_with_pops(&state, &validator_keypairs);
    let_row! { lane_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "beta".to_string(), dataspace_id: DataSpaceId::UNIVERSAL, ..LaneConfig::default() }, ], ) .expect("two-lane catalog") };
    let_row! { nexus = iroha_config::parameters::actual::Nexus { enabled: true, lane_catalog, ..iroha_config::parameters::actual::Nexus::default() } };
    state
        .set_nexus(nexus)
        .expect("apply two-lane Nexus catalog");
    install_lane_manifest_registry(
        &state,
        &[
            (
                LaneId::new(0),
                DataSpaceId::UNIVERSAL,
                validator_ids.clone(),
            ),
            (
                LaneId::new(1),
                DataSpaceId::UNIVERSAL,
                validator_ids.clone(),
            ),
        ],
    );
    let keypairs = configure_commit_topology_preserving_world_peers(&state, 1);
    ensure_merge_carrier_parent_for_test(&state);
    let_row! { lane0 = seed_effect_authenticated_relay_for_merge_test( &state, sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(0), &validator_keypairs), ) };
    let_row! { lane1 = seed_effect_authenticated_relay_for_merge_test( &state, sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(1), &validator_keypairs), ) };
    state.record_lane_relay(&lane0).expect("lane0 accepted");
    let single_lane_candidates = state.merge_entry_candidates_from_lane_relays();
    assert_eq!(
        single_lane_candidates.len(),
        1,
        "active-only merge must not wait for configured idle lanes"
    );
    assert_eq!(
        single_lane_candidates[0].lane_tips().as_slice(),
        &[lane0.block_header.hash()]
    );
    state.record_lane_relay(&lane1).expect("lane1 accepted");
    let candidates = state.merge_entry_candidates_from_lane_relays();
    assert_eq!(candidates.len(), 1);
    let_row! { candidate = candidates .first() .expect("merge candidate computed once both lanes relayed") };
    let lane_tips = candidate.lane_tips();
    let merge_hint_roots = candidate.merge_hint_roots();
    assert_eq!(candidate.epoch_id, 1);
    assert_eq!(
        lane_tips.as_slice(),
        &[lane0.block_header.hash(), lane1.block_header.hash()]
    );
    assert_eq!(
        merge_hint_roots.as_slice(),
        &[
            lane0.merge_hint_root().expect("lane0 merge hint root"),
            lane1.merge_hint_root().expect("lane1 merge hint root")
        ]
    );
    assert_eq!(
        candidate.global_state_root,
        crate::merge::reduce_merge_hint_roots(&merge_hint_roots)
    );
    let qc = merge_qc_for_candidate(&state, candidate, &keypairs, &[0]);
    let entry = merge_entry_from_candidate(candidate.clone(), qc);
    let_row! { committed = state .commit_merge_entry(entry) .expect("merge entry commit succeeds once lanes relayed") };
    assert_eq!(committed.epoch_id, 1);
}
