fn validate_da_shard_cursors_rejects_retired_lane_storage_ticket_reuse() {
    let (mut state, kura) = blank_test_state_with_kura();
    let lane0 = LaneConfig::default();
    let_row! { lane1 = LaneConfig { id: LaneId::new(1), alias: "lane1".to_string(), ..LaneConfig::default() } };
    let catalog = LaneCatalog::new(nonzero!(2_u32), vec![lane0, lane1.clone()]).expect("catalog");
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: catalog,
            lane_config,
            ..Default::default()
        })
        .expect("apply Nexus catalog for retired-lane duplicate ticket test");
    let keypair = crate::state::checked_keypair();
    let_row! { first = DaCommitmentRecord::new( lane1.id, 1, 1, BlobDigest::new([0x61; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x62; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x63; 32]), None, RetentionClass::default(), StorageTicketId::new([0x64; 32]), checked_da_ack_signature(0x65), ) };
    let_row! { first_block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(DaCommitmentBundle::new(vec![first.clone()]))) .sign(keypair.private_key()) .unpack(|_| {}) .into() };
    kura.store_block(Arc::new(first_block.clone()))
        .expect("store first block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(first_block.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydrate committed lane1 ticket before retirement");
    state
        .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
            additions: Vec::new(),
            retire: vec![lane1.id],
        })
        .expect("retire lane1");
    assert!(
        state
            .da_commitments()
            .get_by_storage_ticket(&first.storage_ticket)
            .is_none(),
        "retired lane ticket should be pruned from query index"
    );
    let_row! { second = DaCommitmentRecord::new( LaneId::new(0), 1, 1, BlobDigest::new([0x71; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x72; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x73; 32]), None, RetentionClass::default(), first.storage_ticket, checked_da_ack_signature(0x74), ) };
    let_row! { second_block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&first_block)) .with_da_commitments(Some(DaCommitmentBundle::new(vec![second]))) .sign(keypair.private_key()) .unpack(|_| {}) .into() };
    let state_block = state.block(second_block.header());
    let_row! { err = state_block .validate_da_shard_cursors(&second_block) .expect_err("storage ticket reuse after lane retirement must fail") };
    assert!(matches!(
        err,
        BlockValidationError::DaCommitmentBundle(
            DaCommitmentValidationError::CommittedStorageTicket {
                lane,
                epoch: 1,
                sequence: 1,
                existing_lane,
                existing_epoch: 1,
                existing_sequence: 1
            }
        ) if lane == LaneId::new(0) && existing_lane == lane1.id
    ));
}
state_test! { sync hydrate_da_indexes_rejects_cursor_regression
    let (state, kura) = blank_test_state_with_kura();
    let keypair = crate::state::checked_keypair();
    let_row! { make_record = |sequence: u64| { DaCommitmentRecord::new( LaneId::new(0), 1, sequence, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) } };
    let first_bundle = DaCommitmentBundle::new(vec![make_record(1)]);
    let_row! { first_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(first_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_first: SignedBlock = first_block.into();
    kura.store_block(Arc::new(signed_first.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_first.hash());
        hashes.commit_for_tests();
    }
    let second_bundle = DaCommitmentBundle::new(vec![make_record(0)]);
    let_row! { second_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(second_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_second: SignedBlock = second_block.into();
    kura.store_block(Arc::new(signed_second.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_second.hash());
        hashes.commit_for_tests();
    }
    let_row! { err = state .ensure_da_indexes_hydrated() .expect_err("hydration should fail on regression") };
    match err {
        DaIndexHydrationError::ShardCursor(DaShardCursorError::Regression {
            shard_id,
            lane_id,
            observed_sequence,
            current_sequence,
            ..
        }) => {
            assert_eq!(shard_id, 0);
            assert_eq!(lane_id, LaneId::new(0));
            assert_eq!(observed_sequence, 0);
            assert_eq!(current_sequence, 1);
            let height_str = signed_second.header().height().get().to_string();
            assert!(
                err.to_string().contains(&height_str),
                "expected error message to include height {height_str}"
            );
        }
        other => panic!("unexpected error: {other:?}"),
    }
}
