state_test! { sync hydrate_da_indexes_retains_unknown_lane_bundle_without_active_indexes
    let (state, kura) = blank_test_state_with_kura();
    let keypair = crate::state::checked_keypair();
    let_row! { record = DaCommitmentRecord::new( LaneId::new(9), 0, 0, BlobDigest::new([0x01; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x02; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x03; 32]), None, RetentionClass::default(), StorageTicketId::new([0x05; 32]), checked_da_ack_signature(0x06), ) };
    let key = DaCommitmentKey::from_record(&record);
    let bundle = DaCommitmentBundle::new(vec![record.clone()]);
    let_row! { block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_block: SignedBlock = block.into();
    kura.store_block(Arc::new(signed_block.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_block.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("unknown historical lane should not poison DA hydration");
    {
        let commitments = state.da_commitments();
        let_row! { stored_bundle = commitments .bundle_at(signed_block.header().height().get()) .expect("committed bundle retained") };
        assert_eq!(stored_bundle.commitments, vec![record.clone()]);
        assert!(
            commitments.get_committed_by_key(&key).is_some(),
            "unknown-lane commitment identity should stay available for committed validation"
        );
        assert!(
            commitments
                .get_by_lane_epoch_sequence(LaneId::new(9).as_u32(), record.epoch, record.sequence,)
                .is_none(),
            "unknown-lane commitment must not be query-visible"
        );
        assert!(
            commitments.get_by_manifest(&record.manifest_hash).is_none(),
            "unknown-lane manifest must not be query-visible"
        );
    }
    assert!(
        state.da_shard_cursor_index().is_empty(),
        "unknown-lane commitment should not advance shard cursors"
    );
    assert_eq!(
        state
            .da_receipt_cursors()
            .highest(LaneEpoch::new(LaneId::new(9), 0)),
        None,
        "unknown-lane commitment should not advance receipt cursors"
    );
}
#[test]
#[allow(clippy::too_many_lines)]
fn hydrate_da_indexes_replays_multiple_shards() {
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let lane_count = nonzero!(2_u32);
    let_row! { catalog = LaneCatalog::new( lane_count, vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), shard_id: Some(ShardId::new(5)), alias: "lane1".to_string(), ..LaneConfig::default() }, ], ) .expect("lane catalog") };
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let_row! { mut state = State::try_new( World::default(), Arc::clone(&kura), query_handle, #[cfg(feature = "telemetry")] <_>::default(), ) .expect("open multi-bundle DA test State against configured Kura") };
    state.install_pre_genesis_nexus_for_testing(iroha_config::parameters::actual::Nexus {
        enabled: true,
        lane_catalog: catalog,
        lane_config,
        ..Default::default()
    });
    state.configure_test_runtime_defaults();
    let keypair = crate::state::checked_keypair();
    let_row! { first_bundle = DaCommitmentBundle::new(vec![ DaCommitmentRecord::new( LaneId::new(0), 1, 1, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ), DaCommitmentRecord::new( LaneId::new(1), 1, 2, BlobDigest::new([0xAB; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBC; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCD; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEF; 32]), checked_da_ack_signature(0x12), ), ]) };
    let_row! { first_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(first_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_first: SignedBlock = first_block.into();
    kura.store_block(Arc::new(signed_first.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_first.hash());
        hashes.commit_for_tests();
    }
    let_row! { second_bundle = DaCommitmentBundle::new(vec![DaCommitmentRecord::new( LaneId::new(1), 2, 0, BlobDigest::new([0xAC; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBD; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCE; 32]), None, RetentionClass::default(), StorageTicketId::new([0xF0; 32]), checked_da_ack_signature(0x13), )]) };
    let_row! { second_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(second_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_second: SignedBlock = second_block.into();
    kura.store_block(Arc::new(signed_second.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_second.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydration should succeed");
    let cursors = state.da_shard_cursor_index();
    let shard_zero = cursors.get(0).expect("shard 0 cursor present");
    assert_eq!((shard_zero.epoch, shard_zero.sequence), (1, 1));
    assert_eq!(shard_zero.last_block_height, 1);
    let shard_five = cursors.get(5).expect("shard 5 cursor present");
    assert_eq!((shard_five.epoch, shard_five.sequence), (2, 0));
    assert_eq!(shard_five.last_block_height, 2);
}
state_test! { sync resharding_clears_stale_shard_cursors
    let target_lane = LaneId::new(1);
    let_row! { initial_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: target_lane, alias: "reshard-target".to_owned(), ..LaneConfig::default() }, ], ) .expect("catalog") };
    let initial_config = RuntimeLaneConfig::from_catalog(&initial_catalog);
    let initial_shard = initial_config.shard_id(target_lane);
    let_row! { mut state = State::new_with_nexus_for_testing( World::default(), iroha_config::parameters::actual::Nexus { enabled: true, lane_catalog: initial_catalog, lane_config: initial_config.clone(), ..Default::default() }, LiveQueryStore::start_test(), ) };
    state
        .ensure_da_indexes_hydrated()
        .expect("hydrate DA indexes before advancing");
    let_row! { advance = DaCommitmentRecord::new( target_lane, 1, 1, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) };
    state
        .advance_da_shard_cursors_from_bundle(3, std::slice::from_ref(&advance))
        .expect("advance cursor");
    {
        let cursors = state.da_shard_cursor_index();
        let_row! { cursor = cursors .get(initial_shard) .expect("cursor stored under original shard") };
        assert_eq!(cursor.last_block_height, 3);
    }
    let_row! { reshard_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: target_lane, shard_id: Some(ShardId::new(5)), alias: "reshard-target".to_owned(), ..LaneConfig::default() }, ], ) .expect("reshard catalog") };
    let reshard_config = RuntimeLaneConfig::from_catalog(&reshard_catalog);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: reshard_catalog,
            lane_config: reshard_config,
            ..Default::default()
        })
        .expect("apply resharding Nexus catalog");
    let_row! { resharded_record = DaCommitmentRecord::new( target_lane, 2, 0, BlobDigest::new([0xAB; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBC; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCD; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEF; 32]), checked_da_ack_signature(0x12), ) };
    state
        .advance_da_shard_cursors_from_bundle(4, std::slice::from_ref(&resharded_record))
        .expect("reshard cursor");
    let cursors = state.da_shard_cursor_index();
    assert!(
        cursors.get(initial_shard).is_none(),
        "old shard entry should be cleared after reshard"
    );
    let cursor = cursors.get(5).expect("cursor re-seeded under new shard id");
    assert_eq!((cursor.epoch, cursor.sequence), (2, 0));
    assert_eq!(cursor.last_block_height, 4);
}
state_test! { sync rewind_da_indexes_truncates_to_requested_height
    let (mut state, kura) = blank_test_state_with_kura();
    let catalog = LaneCatalog::new(nonzero!(1_u32), vec![LaneConfig::default()]).expect("catalog");
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: catalog,
            lane_config: lane_config.clone(),
            ..Default::default()
        })
        .expect("apply Nexus catalog before rewind");
    let keypair = crate::state::checked_keypair();
    let_row! { make_record = |sequence: u64| { DaCommitmentRecord::new( LaneId::new(0), 1, sequence, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) } };
    let first_bundle = DaCommitmentBundle::new(vec![make_record(1)]);
    let_row! { first_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(first_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_first: SignedBlock = first_block.into();
    kura.store_block(Arc::new(signed_first.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_first.hash());
        hashes.commit_for_tests();
    }
    let second_bundle = DaCommitmentBundle::new(vec![make_record(2)]);
    let_row! { second_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(second_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_second: SignedBlock = second_block.into();
    kura.store_block(Arc::new(signed_second.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_second.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydration should succeed");
    {
        let cursors = state.da_shard_cursor_index();
        let_row! { cursor = cursors .get(lane_config.shard_id(LaneId::new(0))) .expect("cursor present at tip") };
        assert_eq!(cursor.sequence, 2);
        assert_eq!(cursor.last_block_height, 2);
    }
    state
        .rewind_da_indexes_to_height(1)
        .expect("rewind should succeed");
    {
        let cursors = state.da_shard_cursor_index();
        let_row! { cursor = cursors .get(lane_config.shard_id(LaneId::new(0))) .expect("cursor retained after rewind") };
        assert_eq!(cursor.sequence, 1);
        assert_eq!(cursor.last_block_height, 1);
    }
    assert!(
        state.da_commitments().bundle_at(2).is_none(),
        "reverted height should be dropped from commitment index"
    );
}
#[test]
#[allow(clippy::too_many_lines)]
fn hydrate_da_indexes_replays_multi_shard_bundle() {
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let_row! { catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), shard_id: Some(ShardId::new(5)), alias: "lane1".to_string(), ..LaneConfig::default() }, ], ) .expect("lane catalog") };
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let_row! { mut state = State::try_new( World::default(), Arc::clone(&kura), query_handle, #[cfg(feature = "telemetry")] <_>::default(), ) .expect("open dual-lane DA test State against configured Kura") };
    state.install_pre_genesis_nexus_for_testing(iroha_config::parameters::actual::Nexus {
        enabled: true,
        lane_catalog: catalog,
        lane_config: lane_config.clone(),
        ..Default::default()
    });
    state.configure_test_runtime_defaults();
    let_row! { lane_zero_record = DaCommitmentRecord::new( LaneId::new(0), 1, 0, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) };
    let_row! { lane_one_record = DaCommitmentRecord::new( LaneId::new(1), 3, 7, BlobDigest::new([0x10; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x21; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x32; 32]), None, RetentionClass::default(), StorageTicketId::new([0x54; 32]), checked_da_ack_signature(0x65), ) };
    let bundle = DaCommitmentBundle::new(vec![lane_zero_record.clone(), lane_one_record.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed: SignedBlock = block.into();
    kura.store_block(Arc::new(signed.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydration should succeed");
    let cursors = state.da_shard_cursor_index();
    let shard_zero = lane_config.shard_id(LaneId::new(0));
    let shard_one = lane_config.shard_id(LaneId::new(1));
    let zero_cursor = cursors.get(shard_zero).expect("lane 0 cursor");
    assert_eq!((zero_cursor.epoch, zero_cursor.sequence), (1, 0));
    assert_eq!(zero_cursor.last_block_height, 1);
    let one_cursor = cursors.get(shard_one).expect("lane 1 cursor");
    assert_eq!(
        (one_cursor.epoch, one_cursor.sequence),
        (lane_one_record.epoch, lane_one_record.sequence)
    );
    assert_eq!(one_cursor.last_block_height, 1);
}
state_test! { sync hydrate_da_indexes_replaces_stale_snapshot_state
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let catalog = LaneCatalog::new(nonzero!(1_u32), vec![LaneConfig::default()]).expect("catalog");
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            lane_catalog: catalog,
            lane_config: lane_config.clone(),
            ..Default::default()
        })
        .expect("apply Nexus catalog for shard gating test");
    let_row! { committed_record = DaCommitmentRecord::new( LaneId::new(0), 1, 1, BlobDigest::new([0x01; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x02; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x03; 32]), None, RetentionClass::default(), StorageTicketId::new([0x05; 32]), checked_da_ack_signature(0x06), ) };
    let bundle = DaCommitmentBundle::new(vec![committed_record.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed: SignedBlock = block.into();
    kura.store_block(Arc::new(signed.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed.hash());
        hashes.commit_for_tests();
    }
    let_row! { stale_record = DaCommitmentRecord::new( LaneId::new(0), 9, 9, BlobDigest::new([0x10; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x20; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0x30; 32]), None, RetentionClass::default(), StorageTicketId::new([0x50; 32]), checked_da_ack_signature(0x60), ) };
    state
        .advance_da_shard_cursors_from_bundle(42, std::slice::from_ref(&stale_record))
        .expect("seed stale cursor");
    {
        let mut store = state.da_commitments.write();
        store.insert_bundle(42, DaCommitmentBundle::new(vec![stale_record]));
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydration should succeed");
    let cursors = state.da_shard_cursor_index();
    let_row! { cursor = cursors .get(lane_config.shard_id(LaneId::new(0))) .expect("cursor after hydration") };
    assert_eq!(
        (cursor.epoch, cursor.sequence, cursor.last_block_height),
        (committed_record.epoch, committed_record.sequence, 1)
    );
    assert!(
        state.da_commitments().bundle_at(42).is_none(),
        "stale commitment bundle should be dropped after replay"
    );
}
state_test! { sync da_commitment_lookup_hydrates_from_kura_after_state_restart
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let catalog = LaneCatalog::new(nonzero!(1_u32), vec![LaneConfig::default()]).expect("catalog");
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");
    let mut state = blank_test_state_from_kura(&kura);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            lane_catalog: catalog.clone(),
            lane_config: lane_config.clone(),
            ..Default::default()
        })
        .expect("apply Nexus catalog before commitment replay");
    let_row! { record = DaCommitmentRecord::new( LaneId::new(0), 4, 9, BlobDigest::new([0xA1; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xB2; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xC3; 32]), None, RetentionClass::default(), StorageTicketId::new([0xE5; 32]), checked_da_ack_signature(0xF6), ) };
    let bundle = DaCommitmentBundle::new(vec![record.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed: SignedBlock = block.into();
    kura.store_block(Arc::new(signed.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed.hash());
        hashes.commit_for_tests();
    }
    assert_eq!(
        state.find_da_commitment_by_manifest(&record.manifest_hash),
        Some(record.clone()),
        "pre-restart lookup should hydrate from the committed block"
    );
    drop(state);
    let_row! { mut restarted = State::new_for_testing( World::default(), Arc::clone(&kura), LiveQueryStore::start_test(), ) };
    restarted
        .set_nexus(iroha_config::parameters::actual::Nexus {
            lane_catalog: catalog,
            lane_config,
            ..Default::default()
        })
        .expect("apply Nexus catalog after restart");
    {
        let mut hashes = restarted.block_hashes.block();
        hashes.push(signed.hash());
        hashes.commit_for_tests();
    }
    assert!(
        restarted
            .da_commitments
            .read()
            .get_by_manifest(&record.manifest_hash)
            .is_none(),
        "fresh state should start with an empty in-memory commitment index"
    );
    assert_eq!(
        restarted.find_da_commitment_by_manifest(&record.manifest_hash),
        Some(record.clone()),
        "manifest lookup should hydrate from Kura after restart"
    );
    assert_eq!(
        restarted.find_da_commitment_by_lane_epoch_sequence(0, record.epoch, record.sequence),
        Some(record.clone()),
        "lane/epoch/sequence lookup should hydrate from Kura after restart"
    );
    let commitments = restarted.da_commitments();
    let_row! { stored_bundle = commitments .bundle_at(signed.header().height().get()) .expect("replayed commitment bundle should be retained by block height") };
    assert_eq!(stored_bundle.commitments, vec![record]);
}
state_test! { sync block_and_revert_requires_fresh_da_shard_cursor
    let (mut state, kura) = blank_test_state_with_kura();
    let lane0 = LaneConfig::default();
    let_row! { lane1 = LaneConfig { id: LaneId::new(1), alias: "secondary".to_owned(), ..LaneConfig::default() } };
    let catalog = LaneCatalog::new(nonzero!(2_u32), vec![lane0, lane1]).expect("catalog");
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let dataspace_catalog = dataspace_catalog_for_lane_catalog(&catalog);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: catalog,
            lane_config: lane_config.clone(),
            dataspace_catalog,
            ..Default::default()
        })
        .expect("apply Nexus catalog for block-and-revert test");
    let keypair = crate::state::checked_keypair();
    let_row! { make_record = |lane_id: LaneId, sequence: u64| { let lane_byte = u8::try_from(lane_id.as_u32()).unwrap_or(0x7F); let sequence_byte = u8::try_from(sequence).unwrap_or(0x7F); let tag = lane_byte .wrapping_mul(17) .wrapping_add(sequence_byte) .max(1); DaCommitmentRecord::new( lane_id, 1, sequence, BlobDigest::new([0xA0 ^ tag; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xB0 ^ tag; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xC0 ^ tag; 32]), None, RetentionClass::default(), StorageTicketId::new([0xD0 ^ tag; 32]), checked_da_ack_signature(0xE0 ^ tag), ) } };
    let first_bundle = DaCommitmentBundle::new(vec![make_record(LaneId::new(0), 1)]);
    let_row! { first_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(first_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_first: SignedBlock = first_block.into();
    kura.store_block(Arc::new(signed_first.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_first.hash());
        hashes.commit_for_tests();
    }
    let second_bundle = DaCommitmentBundle::new(vec![make_record(LaneId::new(1), 1)]);
    let_row! { second_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(second_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_second: SignedBlock = second_block.into();
    kura.store_block(Arc::new(signed_second.clone()))
        .expect("store block");
    {
        let mut hashes = state.block_hashes.block();
        hashes.push(signed_second.hash());
        hashes.commit_for_tests();
    }
    state
        .ensure_da_indexes_hydrated()
        .expect("hydration should succeed");
    let replacement_bundle = DaCommitmentBundle::new(vec![make_record(LaneId::new(1), 2)]);
    let_row! { replacement_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(replacement_bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let replacement_signed: SignedBlock = replacement_block.into();
    let mut state_block = state.block_and_revert(replacement_signed.header());
    state_block.touched_lanes.insert(LaneId::new(0));
    let_row! { err = state_block .validate_da_shard_cursors(&replacement_signed) .expect_err("replacement block must refresh shard cursor at its height") };
    match err {
        BlockValidationError::DaShardCursor(DaShardCursorError::StaleCursor {
            lane_id,
            shard_id,
            observed_height,
            required_height,
            ..
        }) => {
            assert_eq!(lane_id, LaneId::new(0));
            assert_eq!(shard_id, lane_config.shard_id(LaneId::new(0)));
            assert_eq!(observed_height, 1);
            assert_eq!(required_height, replacement_signed.header().height().get());
        }
        other => panic!("unexpected error: {other:?}"),
    }
}
