state_test! { sync apply_without_execution_persists_da_shard_cursor_journal_in_background
    strict_single_lane_kura_fixture!(temp_dir, catalog, lane_config, kura);
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
    state
        .set_nexus(iroha_config::parameters::actual::Nexus {
            lane_catalog: catalog,
            lane_config: lane_config.clone(),
            ..Default::default()
        })
        .expect("apply Nexus catalog for apply persistence test");
    let_row! { record = DaCommitmentRecord::new( LaneId::new(0), 1, 2, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) };
    let bundle = DaCommitmentBundle::new(vec![record.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed: SignedBlock = block.into();
    let mut state_block = state.block(signed.header());
    let valid = ValidBlock::validate_unchecked(signed, &mut state_block).unpack(|_| {});
    let committed = valid.commit_unchecked().unpack(|_| {});
    let _ = state_block.apply_without_execution(&committed, Vec::new());
    state_block.commit().expect("commit state block");
    let path = state.da_shard_cursor_journal_path();
    let deadline = Instant::now() + Duration::from_secs(1);
    while !path.exists() && Instant::now() < deadline {
        std::thread::sleep(Duration::from_millis(10));
    }
    assert!(
        path.exists(),
        "journal path should exist after background persist"
    );
    let journal = DaShardCursorJournal::load(&lane_config, &path).expect("load journal");
    let_row! { cursor = journal .cursor_for_lane(record.lane_id) .expect("cursor persisted") };
    assert_eq!(
        (cursor.epoch, cursor.sequence),
        (record.epoch, record.sequence)
    );
    assert_eq!(
        cursor.last_block_height,
        committed.as_ref().header().height().get()
    );
}
state_test! { sync da_bundle_indexes_are_not_committed_when_block_height_mismatches
    let state = blank_test_state();
    let keypair = crate::state::checked_keypair();
    let_row! { first_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_first: SignedBlock = first_block.into();
    let record = sample_da_commitment_record(LaneId::new(0), 1, 0, 0xA0);
    let_row! { mut intent = test_da_pin_intent( *state.network_id_ref(), LaneId::new(0), 1, 0, StorageTicketId::new([0xB0; 32]), ManifestDigest::new([0xB1; 32]), ) };
    intent.alias = Some("height-mismatch-pin".to_owned());
    let_row! { second_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, Some(&signed_first)) .with_da_commitments(Some(DaCommitmentBundle::new(vec![record]))) .with_da_pin_intents(Some(DaPinIntentBundle::new(vec![intent]))) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_second: SignedBlock = second_block.into();
    let mut state_block = state.block(signed_second.header());
    let_row! { committed_second = ValidBlock::new_unverified_for_tests(signed_second) .commit_unchecked() .unpack(|_| {}) };
    let _events = state_block.apply_without_execution(&committed_second, Vec::new());
    assert!(state_block.pending_da_commitments.is_some());
    assert!(state_block.pending_da_pin_intents.is_some());
    assert!(state.da_commitments().bundle_at(2).is_none());
    assert!(
        state
            .da_receipt_cursors()
            .highest(LaneEpoch::new(LaneId::new(0), 1))
            .is_none()
    );
    assert!(
        state
            .da_pin_intents()
            .get_by_alias("height-mismatch-pin")
            .is_none()
    );
    let_row! { err = state_block .commit() .expect_err("height mismatch must abort staged DA indexes") };
    assert!(matches!(
        err,
        TransactionsBlockError::HeightMismatch {
            expected_current_height: 1,
            actual_current_height: 2
        }
    ));
    assert!(state.da_commitments().bundle_at(2).is_none());
    assert!(
        state
            .da_receipt_cursors()
            .highest(LaneEpoch::new(LaneId::new(0), 1))
            .is_none()
    );
    assert!(
        state
            .da_pin_intents()
            .get_by_alias("height-mismatch-pin")
            .is_none()
    );
    assert_eq!(state.transactions.view().latest_height_for_tests(), 0);
}
