state_test! { sync new_state_initializes_sm2_distid_default
    struct DistidGuard(String);
    impl Drop for DistidGuard {
        fn drop(&mut self) {
            Sm2PublicKey::set_default_distid(self.0.clone())
                .expect("sm2_distid_default must be valid");
        }
    }
    let original = Sm2PublicKey::default_distid();
    let _guard = DistidGuard(original.clone());
    Sm2PublicKey::set_default_distid("pre-existing".to_owned()).expect("distid must be valid");
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let world = World::default();
    let _state = State::new_for_testing(world, kura, query_handle);
    assert_eq!(Sm2PublicKey::default_distid(), original);
}
