state_test! { sync asset_definition_domain_index_tracks_exact_membership
    let state = blank_state();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
    let mut state_block = state.block(header);
    let mut stx = state_block.transaction();
    let wonderland: DomainId = DomainId::try_new("wonderland", "universal").expect("domain id");
    let denoland: DomainId = DomainId::try_new("denoland", "universal").expect("domain id");
    for domain_id in [&wonderland, &denoland] {
        Register::domain(Domain::new(domain_id.clone()))
            .execute(&ALICE_ID, &mut stx)
            .expect("register domain");
    }
    Register::account(new_sample_account(&ALICE_ID))
        .execute(&ALICE_ID, &mut stx)
        .expect("register account");
    let_row! { rose_id = AssetDefinitionId::derive_from_components(wonderland.clone(), "rose".parse().unwrap()) };
    let_row! { tulip_id = AssetDefinitionId::derive_from_components(wonderland.clone(), "tulip".parse().unwrap()) };
    let_row! { cactus_id = AssetDefinitionId::derive_from_components(denoland.clone(), "cactus".parse().unwrap()) };
    let_row! { unowned_id = AssetDefinitionId::from_uuid_bytes([ 0x2e, 0x3d, 0x34, 0xbe, 0xb8, 0xa8, 0x42, 0x39, 0xb3, 0xd9, 0x59, 0x07, 0x70, 0xf1, 0x18, 0x9e, ]) .expect("unowned asset definition id") };
    for (definition_id, name, owning_domain) in [
        (&rose_id, "rose", &wonderland),
        (&tulip_id, "tulip", &wonderland),
        (&cactus_id, "cactus", &denoland),
    ] {
        Register::asset_definition(AssetDefinition::numeric(
            definition_id.clone(),
            name,
            iroha_data_model::asset::AssetBalancePolicy::Global,
            Some(owning_domain.clone()),
        ))
        .execute(&ALICE_ID, &mut stx)
        .expect("register owned asset definition");
    }
    Register::asset_definition(AssetDefinition::numeric(
        unowned_id.clone(),
        "cbdc",
        iroha_data_model::asset::AssetBalancePolicy::Global,
        None,
    ))
    .execute(&ALICE_ID, &mut stx)
    .expect("register unowned asset definition");
    let_row! { wonderland_definitions = stx .world .asset_definitions_in_domain_iter(&wonderland) .map(|definition| definition.id().clone()) .collect::<BTreeSet<_>>() };
    assert_eq!(
        wonderland_definitions,
        BTreeSet::from([rose_id.clone(), tulip_id.clone()]),
        "wonderland should only expose its own definitions"
    );
    let_row! { denoland_definitions = stx .world .asset_definitions_in_domain_iter(&denoland) .map(|definition| definition.id().clone()) .collect::<BTreeSet<_>>() };
    assert_eq!(
        denoland_definitions,
        BTreeSet::from([cactus_id.clone()]),
        "denoland should only expose its own definitions"
    );
    assert!(
        stx.world
            .domain_asset_definitions
            .iter()
            .all(|(_, definitions)| !definitions.contains(&unowned_id)),
        "unowned asset definitions must not create internal domain index entries"
    );
    let_row! { alice_definitions = stx .world .asset_definitions_owned_by_iter(&ALICE_ID) .map(|definition| definition.id().clone()) .collect::<BTreeSet<_>>() };
    assert_eq!(
        alice_definitions,
        BTreeSet::from([
            rose_id.clone(),
            tulip_id.clone(),
            cactus_id.clone(),
            unowned_id.clone()
        ]),
        "owner index should include domain-owned and unowned definitions"
    );
    Unregister::asset_definition(cactus_id.clone())
        .execute(&ALICE_ID, &mut stx)
        .expect("unregister asset definition");
    assert!(
        stx.world
            .asset_definitions_in_domain_iter(&denoland)
            .next()
            .is_none(),
        "empty domains should not leak definitions from other domains"
    );
    assert!(
        stx.world.domain_asset_definitions.get(&denoland).is_none(),
        "empty domain index entries should be removed"
    );
    assert!(
        !stx.world
            .asset_definitions_by_owner
            .get(&ALICE_ID)
            .is_some_and(|definitions| definitions.contains(&cactus_id)),
        "unregister should remove the definition from the owner index"
    );
}
state_test! { sync asset_definition_holder_index_tracks_asset_lifecycle
    asset_index_transaction!(state, state_block, stx, domain_id);
    let_row! { asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::derive_from_components( DomainId::try_new("wonderland", "universal").unwrap(), "rose".parse().unwrap(), ) };
    Register::asset_definition(AssetDefinition::numeric(
        asset_def_id.clone(),
        "rose",
        iroha_data_model::asset::AssetBalancePolicy::Global,
        Some(domain_id.clone()),
    ))
    .execute(&ALICE_ID, &mut stx)
    .expect("register asset definition");
    let alice_id = ALICE_ID.clone();
    let asset_id = AssetId::new(asset_def_id.clone(), alice_id.clone());
    crate::smartcontracts::isi::asset::isi::seed_numeric_asset_balance_for_test(
        &mut stx.world,
        &asset_id,
        &Quantity::from(1_u32),
    )
    .expect("insert asset through helper");
    assert!(
        stx.world
            .asset_definition_holders
            .get(&asset_def_id)
            .is_some_and(|holders| holders.contains(&alice_id)),
        "holder index should include account after insert"
    );
    assert!(
        stx.world
            .asset_definition_assets
            .get(&asset_def_id)
            .is_some_and(|asset_ids| asset_ids.contains(&asset_id)),
        "definition index should include concrete asset id after insert"
    );
    assert!(
        stx.world
            .assets_by_account
            .get(&alice_id)
            .is_some_and(|asset_ids| asset_ids == &BTreeSet::from([asset_id.clone()])),
        "account projection should contain exactly the inserted asset id"
    );
    assert!(
        stx.world
            .assets_by_domain
            .get(&domain_id)
            .is_some_and(|asset_ids| asset_ids == &BTreeSet::from([asset_id.clone()])),
        "domain projection should contain exactly the inserted asset id"
    );
    assert!(
        stx.world
            .asset_definition_nonzero_holders
            .get(&asset_def_id)
            .is_some_and(|holders| holders.contains(&alice_id)),
        "non-zero holder index should include account after non-zero insert"
    );
    let removed = stx.world.remove_asset_and_metadata(&asset_id);
    assert!(removed.is_some(), "asset removed");
    assert!(
        stx.world
            .asset_definition_holders
            .get(&asset_def_id)
            .is_none(),
        "holder index should remove empty holder set"
    );
    assert!(
        stx.world
            .asset_definition_assets
            .get(&asset_def_id)
            .is_none(),
        "definition index should remove empty asset-id set"
    );
    assert!(
        stx.world.assets_by_account.get(&alice_id).is_none(),
        "account projection should remove an empty asset-id set"
    );
    assert!(
        stx.world.assets_by_domain.get(&domain_id).is_none(),
        "domain projection should remove an empty asset-id set"
    );
    assert!(
        stx.world
            .asset_definition_nonzero_holders
            .get(&asset_def_id)
            .is_none(),
        "non-zero holder index should remove empty holder set"
    );
}
state_test! { sync asset_definition_holder_index_waits_for_last_partition_removal
    asset_index_transaction!(state, state_block, stx, domain_id);
    let_row! { asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::derive_from_components( DomainId::try_new("wonderland", "universal").unwrap(), "rose".parse().unwrap(), ) };
    Register::asset_definition(AssetDefinition::numeric(
        asset_def_id.clone(),
        "rose",
        iroha_data_model::asset::AssetBalancePolicy::Global,
        Some(domain_id.clone()),
    ))
    .execute(&ALICE_ID, &mut stx)
    .expect("register asset definition");
    let global_asset_id = AssetId::new(asset_def_id.clone(), ALICE_ID.clone());
    let (_, global_asset_value) = Asset::new(global_asset_id.clone(), 1_u32).into_key_value();
    stx.world
        .assets
        .insert(global_asset_id.clone(), global_asset_value);
    stx.world.track_asset_holder(&global_asset_id);
    stx.world.track_nonzero_asset_holder(&global_asset_id);
    let_row! { scoped_asset_id = AssetId::with_scope( asset_def_id.clone(), ALICE_ID.clone(), iroha_data_model::asset::AssetBalanceScope::Dataspace( iroha_data_model::nexus::DataSpaceId::new(7), ), ) };
    let (_, scoped_asset_value) = Asset::new(scoped_asset_id.clone(), 1_u32).into_key_value();
    stx.world
        .assets
        .insert(scoped_asset_id.clone(), scoped_asset_value);
    stx.world.track_asset_holder(&scoped_asset_id);
    stx.world.track_nonzero_asset_holder(&scoped_asset_id);
    let removed_global = stx.world.remove_asset_and_metadata(&global_asset_id);
    assert!(removed_global.is_some(), "global partition removed");
    assert!(
        stx.world
            .asset_definition_holders
            .get(&asset_def_id)
            .is_some_and(|holders| holders.contains(&ALICE_ID)),
        "holder should remain while another partition exists"
    );
    assert!(
        stx.world
            .asset_definition_assets
            .get(&asset_def_id)
            .is_some_and(|asset_ids| {
                !asset_ids.contains(&global_asset_id) && asset_ids.contains(&scoped_asset_id)
            }),
        "definition index should keep only the surviving partition"
    );
    assert!(
        stx.world
            .asset_definition_nonzero_holders
            .get(&asset_def_id)
            .is_some_and(|holders| holders.contains(&ALICE_ID)),
        "non-zero holder should remain while another non-zero partition exists"
    );
    let removed_scoped = stx.world.remove_asset_and_metadata(&scoped_asset_id);
    assert!(removed_scoped.is_some(), "scoped partition removed");
    assert!(
        stx.world
            .asset_definition_holders
            .get(&asset_def_id)
            .is_none(),
        "holder entry should be removed after last partition disappears"
    );
    assert!(
        stx.world
            .asset_definition_assets
            .get(&asset_def_id)
            .is_none(),
        "definition index should be removed after last partition disappears"
    );
    assert!(
        stx.world
            .asset_definition_nonzero_holders
            .get(&asset_def_id)
            .is_none(),
        "non-zero holder entry should be removed after last non-zero partition disappears"
    );
}
state_test! { sync assets_by_definition_iter_includes_all_tracked_partitions
    asset_index_transaction!(state, state_block, stx, domain_id);
    let_row! { asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::derive_from_components( DomainId::try_new("wonderland", "universal").unwrap(), "rose".parse().unwrap(), ) };
    Register::asset_definition(AssetDefinition::numeric(
        asset_def_id.clone(),
        "rose",
        iroha_data_model::asset::AssetBalancePolicy::Global,
        Some(domain_id.clone()),
    ))
    .execute(&ALICE_ID, &mut stx)
    .expect("register asset definition");
    let_row! { other_asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::derive_from_components( DomainId::try_new("wonderland", "universal").unwrap(), "tulip".parse().unwrap(), ) };
    Register::asset_definition(AssetDefinition::numeric(
        other_asset_def_id.clone(),
        "tulip",
        iroha_data_model::asset::AssetBalancePolicy::Global,
        Some(domain_id.clone()),
    ))
    .execute(&ALICE_ID, &mut stx)
    .expect("register other asset definition");
    let global_asset_id = AssetId::new(asset_def_id.clone(), ALICE_ID.clone());
    let_row! { scoped_asset_id = AssetId::with_scope( asset_def_id.clone(), ALICE_ID.clone(), iroha_data_model::asset::AssetBalanceScope::Dataspace( iroha_data_model::nexus::DataSpaceId::new(7), ), ) };
    let other_asset_id = AssetId::new(other_asset_def_id, ALICE_ID.clone());
    for asset_id in [
        global_asset_id.clone(),
        scoped_asset_id.clone(),
        other_asset_id,
    ] {
        let (_, asset_value) = Asset::new(asset_id.clone(), 1_u32).into_key_value();
        stx.world.assets.insert(asset_id.clone(), asset_value);
        stx.world.track_asset_holder(&asset_id);
    }
    stx.apply();
    state_block.commit().expect("commit state block");
    let view = state.view();
    let world = view.world();
    let_row! { mut assets: Vec<_> = world .assets_by_definition_iter(&asset_def_id) .map(|asset| asset.id) .collect() };
    assets.sort();
    let_row! { mut entry_assets: Vec<_> = world .asset_entries_by_definition_iter(&asset_def_id) .map(|asset| asset.id().clone()) .collect() };
    entry_assets.sort();
    let_row! { mut entry_assets_from_many: Vec<_> = world .asset_entries_by_definition_ids_iter(vec![asset_def_id.clone()]) .map(|asset| asset.id().clone()) .collect() };
    entry_assets_from_many.sort();
    let_row! { mut entry_assets_from_ids: Vec<_> = world .asset_entries_by_ids_iter(vec![global_asset_id.clone(), scoped_asset_id.clone()]) .map(|asset| asset.id().clone()) .collect() };
    entry_assets_from_ids.sort();
    assert_eq!(
        assets,
        vec![global_asset_id, scoped_asset_id],
        "definition iterator should return every tracked partition for the definition"
    );
    assert_eq!(
        entry_assets, assets,
        "borrowed definition iterator should match the owned iterator"
    );
    assert_eq!(
        entry_assets_from_many, assets,
        "multi-definition borrowed iterator should match the single-definition iterator"
    );
    assert_eq!(
        entry_assets_from_ids, assets,
        "asset-id borrowed iterator should resolve the selected stored entries"
    );
}
