state_test! { result time_trigger_failure_populates_entrypoint_instructions
    let kura = Kura::blank_kura_for_testing();
    let query = LiveQueryStore::start_test();
    let state = State::new(World::default(), kura, query);
    let header = BlockHeader::new(NonZeroU64::new(1).unwrap(), None, None, None, 0, 0);
    let mut state_block = state.block(header);
    {
        let mut stx = state_block.transaction();
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal")?;
        Register::domain(Domain::new(domain_id.clone()))
            .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
        Register::account(new_sample_account(&ALICE_ID))
            .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
        Register::asset_definition(AssetDefinition::numeric(
            iroha_data_model::asset::AssetDefinitionId::derive_from_components(
                domain_id.clone(),
                "rose".parse()?,
            ),
            "rose",
            iroha_data_model::asset::AssetBalancePolicy::Global,
            Some(domain_id),
        ))
        .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
        stx.apply();
    }
    let trigger_id: TriggerId = "failing_time_trigger".parse()?;
    let_row! { asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::derive_from_components( DomainId::try_new("wonderland", "universal")?, "rose".parse()?, ) };
    let alice_asset = AssetId::new(asset_def_id.clone(), ALICE_ID.clone());
    let_row! { failing_instruction: InstructionBox = Transfer::asset_quantity(alice_asset, 1_u32, BOB_ID.clone()).into() };
    let_row! { trigger = Trigger::new( trigger_id.clone(), Action::new( vec![failing_instruction.clone()], Repeats::Exactly(1), ALICE_ID.clone(), TimeEventFilter(ExecutionTime::Schedule(Schedule { start_ms: 0, period_ms: Some(1_000), })), ) .expect("trigger action fixture satisfies validation invariants"), ) };
    {
        let mut stx = state_block.transaction();
        Register::trigger(trigger).execute(&ALICE_ID, &mut stx)?;
        stx.apply();
    }
    let time_event = state_block.create_time_event(&header);
    let_row! { action = { state_block .world .triggers() .time_triggers() .get(&trigger_id) .expect("time trigger registered") .clone() } };
    let_row! { (entrypoint, result) = state_block.execute_time_trigger(&trigger_id, &action, &time_event, 0) };
    assert!(result.is_err(), "expected trigger execution to fail");
    let expected_step = ExecutionStep(ConstVec::from(vec![failing_instruction]));
    assert_eq!(entrypoint.instructions, expected_step);
    assert_eq!(entrypoint.id, trigger_id);
    assert_eq!(entrypoint.authority, *ALICE_ID);
    Ok(())
}
state_test! { result time_trigger_same_id_reschedule_keeps_new_repeat_budget
    let kura = Kura::blank_kura_for_testing();
    let query = LiveQueryStore::start_test();
    let state = State::new(World::default(), kura, query);
    let_row! { block1 = new_dummy_block_with_payload(|h| { h.set_height(NonZeroU64::new(1).unwrap()); h.creation_time_ms = 0; }) };
    let mut state_block = state.block(block1.as_ref().header());
    let trigger_id: TriggerId = "self_reschedule".parse()?;
    {
        let mut stx = state_block.transaction();
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal")?;
        Register::domain(Domain::new(domain_id)).execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
        Register::account(new_sample_account(&ALICE_ID))
            .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
        let_row! { replacement_schedule = Schedule { start_ms: 10_000, period_ms: None, } };
        let_row! { replacement_trigger = Trigger::new( trigger_id.clone(), Action::new( Vec::<InstructionBox>::new(), Repeats::Exactly(1), ALICE_ID.clone(), TimeEventFilter(ExecutionTime::Schedule(replacement_schedule)), ) .expect("trigger action fixture satisfies validation invariants"), ) };
        let_row! { instructions = vec![ InstructionBox::from(Unregister::trigger(trigger_id.clone())), InstructionBox::from(Register::trigger(replacement_trigger)), ] };
        let_row! { trigger = Trigger::new( trigger_id.clone(), Action::new( instructions, Repeats::Exactly(1), ALICE_ID.clone(), TimeEventFilter(ExecutionTime::Schedule(Schedule { start_ms: 0, period_ms: None, })), ) .expect("trigger action fixture satisfies validation invariants"), ) };
        Register::trigger(trigger).execute(&ALICE_ID, &mut stx)?;
        stx.apply();
    }
    let _ = state_block.apply_without_execution(&block1, Vec::new());
    state_block.commit()?;
    let_row! { block2 = new_dummy_block_with_payload(|h| { h.set_height(NonZeroU64::new(2).unwrap()); h.creation_time_ms = 2; }) };
    let mut state_block = state.block(block2.as_ref().header());
    let time_event = state_block.create_time_event(&block2.as_ref().header());
    let_row! { original_action = state_block .world .triggers() .time_triggers() .get(&trigger_id) .expect("original trigger should be registered") .clone() };
    let_row! { (_entrypoint, result) = state_block.execute_time_trigger(&trigger_id, &original_action, &time_event, 0) };
    assert!(
        result.is_ok(),
        "self-rescheduling trigger should execute successfully: {:?}",
        result
    );
    let_row! { action = state_block .world .triggers() .time_triggers() .get(&trigger_id) .expect("replacement trigger should remain registered") };
    assert_eq!(action.repeats, Repeats::Exactly(1));
    assert_eq!(
        action
            .metadata()
            .get(&"__registered_block_height".parse::<Name>()?)
            .and_then(|json| json.try_into_any_norito::<u64>().ok()),
        Some(2)
    );
    match action.filter.0 {
        ExecutionTime::Schedule(schedule) => {
            assert_eq!(schedule.start_ms, 10_000);
            assert_eq!(schedule.period_ms, None);
        }
        ExecutionTime::PreCommit => panic!("expected replacement schedule"),
    }
    Ok(())
}
state_test! { sync time_trigger_nft_seq_base_strides_by_256
    let base0 = StateBlock::time_trigger_nft_seq_base(42, 0);
    let base1 = StateBlock::time_trigger_nft_seq_base(42, 1);
    let base2 = StateBlock::time_trigger_nft_seq_base(42, 2);
    assert_eq!(base1, base0.saturating_add(256));
    assert_eq!(base2, base1.saturating_add(256));
    let next_block = StateBlock::time_trigger_nft_seq_base(43, 0);
    assert!(next_block > base2);
}
