state_test! { sync block_sweeps_expired_governance_locks_and_records_height
    let kura = Kura::blank_kura_for_testing();
    let query = LiveQueryStore::start_test();
    let state = State::new_for_testing(World::default(), kura, query);
    let referendum_id = "0xdeadbeef".to_owned();
    let voter = (*ALICE_ID).clone();
    {
        let mut world_block = state.world.block();
        let mut locks = GovernanceLocksForReferendum::default();
        locks.locks.insert(
            voter.clone(),
            GovernanceLockRecord {
                owner: voter.clone(),
                amount: 42_u64.into(),
                slashed: Quantity::zero(),
                expiry_height: 5,
                direction: 0,
                duration_blocks: 0,
                custody: Some(GovernanceLockCustody {
                    escrowed: false,
                    asset_definition_id: state.gov.voting_asset_id.clone(),
                    bond_escrow_account: state.gov.bond_escrow_account.clone(),
                    slash_receiver_account: state.gov.slash_receiver_account.clone(),
                }),
            },
        );
        world_block.put_governance_locks(referendum_id.clone(), locks);
        *world_block.governance_last_unlock_sweep_height.get_mut() = 1;
        world_block.commit();
    }
    let header = BlockHeader::new(nonzero!(10_u64), None, None, None, 0, 0);
    let block = state.block(header);
    assert!(!block.world.merge_execution_write_set_bytes().is_empty());
    let recorded_height = *block.world.governance_last_unlock_sweep_height;
    assert_eq!(
        recorded_height, 10,
        "sweep height must match current block height"
    );
    assert!(
        block.world.governance_locks.get(&referendum_id).is_none(),
        "fully expired referendum lock containers must be deleted"
    );
    assert_eq!(
        *block.world.governance_unlock_stats,
        GovernanceUnlockStatsSnapshot {
            evaluated_height: 10,
            expired_locks_now: 0,
            referenda_with_expired: 0,
        }
    );
}
